/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170421-9","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"文教委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"しながわこども冒険ひろばの開設","agenda":"しながわこども冒険ひろばの開設","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"品川区は子育て支援策、非常にいろいろ充実していると思うのですけれども、やはり都心部だけあって、自然とダイナミックに触れ合う機会というのは少なくなりがちですので、今後もこういったものをできる限りつくっていただきたいと思うのですけれども、北浜ができてから、いろいろ議論はあり、要望もあったものの、２カ所目が１４年後ということで、これまでどういったことがネックだったのか。","respondent":"高山子ども育成課長","answer":"今後の方向性ということで、今後、もちろん３カ所目、４カ所目ということで、機会を捉えて開設については努力してまいりたいとは思うのですが、都心部である品川区においては、そういった機会が必ずしも計画的に訪れるわけではありませんので、そういったものについては。","voiceIndex":20,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"こうしたものを開設していくのに、さまざまな区民の活動、ＮＰＯとかの団体もいろいろな活動をされていたと思います。ここでは、ＮＰＯ法人ふれあいの家－おばちゃんちに委託ということなのですけれども、例えば、保育園や遊び場をつくったりといいますか、そういったさまざまな団体との関係とこの運営、どういうふうな関係になっているのかということも教えてください。","respondent":"高山子ども育成課長","answer":"ご説明のほうが漏れてしまったのですが、本事業の委託先は、北浜こども冒険ひろばと同じ、ＮＰＯ法人ふれあいの家－おばちゃんちということなのですが、このプレイパークの、例えばプレイワーカー小屋、詰所などの配置であるとか、あるいは遊具とか水場の配置などにつきましては。","voiceIndex":22,"id":"exchange-002"},{"speaker":"新妻委員","kind":"質問・要望","question":"何点か確認させていただきたいと思います。今後また品川区全域で検討していただきたいと思うのですけれども、荏原地域も含めて、難しいところもあると思いますが、そのような要望もいただいておりますので、荏原地域のほうも含めてぜひご検討いただければと思いますが、以上の点をお願いいたします。","respondent":"高山子ども育成課長","answer":"場所的な偏りにつきましては、委員ご案内のとおり、我々としてもでき得る限りバランスよくこういった施設を配置していきたいと思っているところではあるのですが、今回、１,４００m2という面積で確保したのですが、実際、訪れていただきますと。","voiceIndex":25,"id":"exchange-003"},{"speaker":"新妻委員","kind":"確認","question":"１点だけ。事故の対応ですけれども、当然、対応はしていただけると思うのですけれども、具体的に行く病院を指定しているのかとか、そこら辺の確認を１点だけお願いいたします。","respondent":"高山子ども育成課長","answer":"いわゆるけがの程度などにもよるとは思うのですが、当然、１１９番などをしますと、あいている病院などを検索した後の対応になりますので、事故の時間帯にもよるかとは思うのですが、そういう意味では、可能な限りというか、できる限りの速やかな対応ということで。","voiceIndex":27,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料の中に、事業目的のところに、自主性や創造性とともに自己責任の意識ということが書いてあるのですけれども、これは具体的に子どもに何を身につけてほしいということなのでしょうか。例えば、どういうことをすればけがをするとか、危険だとか、そういったことを身につけるということと捉えてよろしいのでしょうか。","respondent":"高山子ども育成課長","answer":"例えば、プレイパークをやっているところから、事業者からお話を伺いますと、あえてコンクリートの上に飛びおりる、そんなような体験をさせて、危険だとわかっていながら、今の自分ならできるのかできないのかとか。","voiceIndex":29,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１日４人ということなのかどうか、その辺を具体的に教えていただきたいのと、北浜のところは月曜日から土曜日で午後ということで、午前中はやっていなくて、ここは１日やるということで、いいなと思っているのですが、やはり土日やってしまうと、金土は難しいのでしょうか。その辺の曜日とか時間の問題をどう考えたらいいのか、教えてください。","respondent":"高山子ども育成課長","answer":"これの考え方なのですけれども、やはり受託していただく方々ともお話をする中で、有資格者を配置する、そして、必要なスタッフを開園時間中は必ず確保するという観点からすれば、やはり週に２日程度の休みは必要になってくるというようなことは、実は仕様をつくる過程の中で。","voiceIndex":31,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資格のない方について、ＮＰＯ法人ふれあいの家－おばちゃんちなんかは、子育てのところは独自の研修とかをしているというふうに書いてあるのですけれども、大きな事業の一つがこのプレイパークだと思うのですけれども、ここのところの資格を持った方以外の研修がどうなっているのか教えていただきたいのが１つと、あと、遊びの内容的には、大体ここに書いてある感じという受けとめ方でいいのでしょうか。","respondent":"高山子ども育成課長","answer":"これはやはり大人がいるところでないと、大変危険なものですので、そういった意味では、そういった事業については必ず実施するようにというようなことで、仕様書上はうたっているところです。","voiceIndex":33,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特にこういった、お子さんが体験したことのないような遊びを初めて楽しむといった意味においては、指導員でいらっしゃる方の力量というのですか、経験豊かな方というのがすごく重要だと思うので、研修とかをやはり注目、きちんとやっていただきたいと思うのと、先ほど出ましたけれども、保育園なんかもそうだけれども、けがをされたときのことを想定して、どこと連絡をとるのかとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"ちょっと細かくなってすみません。どんなふうに考えているのかというところ、それからあと最後に、委託ということなのですけれども、毎年毎年更新されていく形態の委託なのか、それとも複数年で結ばれる契約とするのでしょうか。","respondent":"高山子ども育成課長","answer":"最後に委託につきましては、今回、当然、行政ですので、単年度の契約ということではありますが、事業の実績なども踏まえまして、次年度以降の計画については、契約部分もご相談しながら決めてまいりたいというふうに考えております。","voiceIndex":36,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"けがへの対応というのは何点か出ていたと思うのですけれども、例えば、その場での簡易な救急セットみたいなものは、こういったこの場所に備えられているのかどうか。北浜のほうもあわせてこれをお伺いしたいと思います。やはり転落とかぶつかりとかいうのもあるかと思うので、ＡＥＤが近くにあるかどうか。それが開園時間中といいますか、活動時間中に使えるような状態であるのかということを教えてください。","respondent":"高山子ども育成課長","answer":"けがへの対応ということで、救急セットのような簡易なものについては、５月７日のオープンということもありますので、現在、そういったものを備品、もろもろ備えているところですので、これについては北浜も同様に備えているというものです。","voiceIndex":39,"id":"exchange-010"}]},{"id":"topic-02","title":"子ども食堂フォーラムの開催","agenda":"子ども食堂フォーラムの開催","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"目的のところで「開設を支援し」というふうにあるので、確認なのですけれども、品川区としては子ども食堂をつくっていく、開設を今後区内に増やしていくということには、積極的に支援していこうという姿勢であるということでいいのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"２つ目としましては、そういう子ども食堂にかかわっている方たちのネットワークの中で出た意見というのを、事務局を社会福祉協議会に委託する予定としておりますけれども、社会福祉協議会、もちろん私どもも参加したりとかしながら。","voiceIndex":45,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"子ども食堂を開きたいと思っていらっしゃる方から、品川のほうで開設をしたいのだけれども、ちょっとストップがかかっているというようなことも聞いたものですから、かつどこが開設する、しないみたいなことを、区内の団体が選別しているといったら言葉がよくはないかもしれないのですけれども、そのように捉えているようなことも伺ったのですけれども、この情報なり。","respondent":"廣田子ども家庭支援課長","answer":"自主的に区のエリアで飲食を提供できる場所を借りられてやる分には、区が介入することではないのですが、多分、お話が混同されていて、区が無償で提供するかどうかということについては、全容を把握してからでないと、ある１団体にということは難しいので少しお待ちください。","voiceIndex":47,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"それについては、確かにおっしゃるとおり、どこに対してどう提供していくかというのは、ある程度選んでいく必要があるだろうと。そうした意味では、他区などでも公共施設をある程度提供してという例はあると思うのですけれども、品川区としても、団体や事業主によっては公共施設を一部使っていただいてという選択肢自体は持っているというふうに見ておいてよろしいのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"現時点で具体的にここと決めているわけではないのですけれども、現在、ゆうゆうプラザを多世代交流施設としてつくっていたりであるとか、社会福祉法人でいろいろ地域の貢献活動、法律的に変わって、そのような取り組みがあるので、そちらの情報を区は持っているので。","voiceIndex":49,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この事業は子ども家庭支援課で行っていますけれども、私がクロモンカフェへ視察に行ったときに印象的だったのが、地域の学校にも理解をしていただきたいのだけれども、なかなかそこが伝わらないみたいなお話をちらっと伺ったので、ずっとかかわらなくてもいいので、こういう貴重なフォーラムが行われるので、学校の関係者にもここに参加していただいて。","respondent":"廣田子ども家庭支援課長","answer":"今後、子ども食堂にとどまるつもりはもともとなく、この後に報告しようと思っていたのですが、居場所づくりについては、学習支援であったりとか、食事の提供であったりとか、いろいろただの居場所でなくて、さまざま絡むので。","voiceIndex":51,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"いよいよフードバンク機能の確立が進んでいくと思うのですけれども、社協が絡んでの今回、子ども食堂フォーラムがキックオフということで進んでいくと思うのですが、フードバンク機能の中で、これを進めていく中で、区の生活福祉課と連携をして、子どもたちだけでなく、世代関係なく、そういう生活困窮の方にもフードバンク機能が対象となっていくのかどうかというところを１点。","respondent":"廣田子ども家庭支援課長","answer":"フードバンク機能というふうに書いているのですが、普通の子ども食堂のためのフードバンクということではなくて、社会福祉協議会にありますボランティアセンターの中で寄附いただいたものを福祉施設であるとか各団体に配布しているのですけれども。","voiceIndex":53,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"なぜかというと、先ほど子ども食堂に関する区の方針を説明していただけて非常によくわかったので、今後の流れもわかったのですが、出席される方々は経験されている、実際やられている方のお話を伺えるのもそうですし、区はどうなのみたいな話になったときに、先ほどあったように、いろいろなそごがあったりする場合もあるので、その辺はどうなのかということです。","respondent":"廣田子ども家庭支援課長","answer":"内容についてはこれだけだと、チラシだとすごく少ないのですけれども、実際はこの中で、区の考えも、近藤さんの実施されている内容は私ども区の求める子ども食堂と近いので、それは打ち合わせしてお話をお願いしているのですけれども。","voiceIndex":56,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話をお伺いして、個人ファンドの仕組みとか、そういう問題を考えることは必要だと思うので、ぜひどちらかの場面できちんと内容を説明していただいて、これからやる方の参考になるようにしていただきたいと思います。子ども食堂の性格については、また後で子どもの未来プロジェクトのほうで伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-017"}]},{"id":"topic-03","title":"子どもの未来応援プロジェクト","agenda":"子どもの未来応援プロジェクト","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"不安感・孤独感の解消というところ。これは今回の調査とかかわる部分とすぐにイコールにならない、重なるけれども対象が違ってくるという部分もあるかと思うので、この対象だけではないと思うのですけれども、どこかで区としてひきこもりの状態の実態調査というものもやっていきつつ、こうした施策と絡めていくということも必要ではないかと思うのですけれども、そこはどのようにお考えでしょうか。","respondent":"廣田子ども家庭支援課長、高山子ども育成課長","answer":"高校生はどこまでというお話なのですけれども、高校生をどこまでやっていくかというところで、平成２９年度で手をつけていくのですけれども、新規の学習支援事業につきましては、ひとり親家庭の中と、あと。他の団体との連携という点で申しますと、そこの利用は無料ですので、まずそこの利用をきっかけに、例えば、そういった学習支援をしているＮＰＯのやっている夏季の合宿などに参加して。","voiceIndex":65,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"あまりオープンに突っ込むのは今日はやめておきたいのですけれども、ただ、こうした施策と、それから教育委員会との情報交換ですね。そこら辺から始めるキャリアデザインというのは、すごく私は大切だと思っているのですけれども、そういったことも視点に入っているかどうかということをお伺いしたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"教育委員会との情報共有ということなのですけれども、平成２９年度、またさらに審議を進めていくのですが、先ほど組織を説明したように、平成２８年度の組織というふうに説明させていただいたのですが、平成２９年度につきましては。","voiceIndex":68,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"ご説明ありがとうございました。経済的支援のところで、就学援助についてはこの間、私も再三求めてきました入学資金の支給時期検討ということで、おそらく早期の支給の検討だと思うのですけれども、現在どういうところまで、これから検討していくことだと思うのですけれども、今現状の検討段階、どういった状況まで進んでいるのか、伺いたいと思います。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"それについては、実際には区の中では、要望については既に生活保護者については出ているということで、それを受けて、いわゆる準要保護の取り扱いをどうするかということの検討にこれから入っていくというような段階です。奨学金につきましては、今さっきご答弁させていただいたとおり、高校等に調査をかけて、授業料以外のお金がどのぐらい、どういう時期にかかってくるのかというところの把握をした上で検討を進めていくのですけれども。","voiceIndex":70,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"奨学金については、今、平成３０年度生に適用できるようにということでしたけれども、返還免除型がありますけれども、給付型の奨学金をぜひつくっていただきたいと思いますが、これは高校生が対象ということですか。さっき高校生の調査ということでしたので、大学生のほうの対象ということも考えられているのか。","respondent":"廣田子ども家庭支援課長","answer":"大学につきましては、国の制度で、第一種の貸し付けについて幅が広がりましたし、低所得世帯については、支援が平成２９年度から前倒しでやりながら平成３０年度というところで、大学については国にお任せするのがよしと現時点では考えています。","voiceIndex":73,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"しかし、経済支援のほうも、やはり家庭の経済状況によってアルバイトをしながら勉学していくという、両立していくのがなかなか大変だというところで中退される方もいらっしゃいますので、そういったところへの経済的支援も必要だと思いますけれども、お考えを伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"生保世帯の大学進学につきましては、プロジェクトの中に生活福祉課長、福祉部長も入っておりますので、福祉部のほうで検討するというふうに言われているので、新規事業等ありましたら、厚生委員会のほうに出ると思うのですが、情報が入りましたら。","voiceIndex":77,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、なかなか貧困と格差が広がっている中で、やはりこういったところ、親の経済力で子どもの未来が左右されないように、しっかりと区のほうでも支援していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１９ページのところに、カテゴリ別の就労支援のところなのですが、若者と女性というところが書かれていますけれども、先ほどもひきこもりというところがあったのですが、特に若者のところは、中学とか高校の中退者、途中で宙ぶらりんになっている子どもたちのところの相談の場所がなかなかないといったところにおいては、学び直しでまたそこから就労につなげていくといった。","respondent":"廣田子ども家庭支援課長","answer":"若者の学び直し云々の話をいただいたのですけれども、問題がいろいろあるのですが、中退云々の関係につきましては、今後審議していって、都の相談の制度であるとか、そこに中学３年、高校に入ってからの間の抜け落ちている部分のつなぎをどうしていくかとか、使える資源。","voiceIndex":80,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"つなぎを考えていただきたいと思います。子どもの貧困を、貧困だけではなくて、広く子どもをというところがあると思うのですが、今回の大綱ができた大もとのところは、やはり子どもの貧困、見えないところをしっかり見るといったところが位置づけられているので、しっかりと位置づけをしていただきたいということですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-025"}]},{"id":"topic-04","title":"子ども・子育て会議の報告","agenda":"子ども・子育て会議の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"３回目のところの３点目です。（仮称）品川区子ども・若者計画の策定と平成２９年度以降の品川区子ども・子育て会議についてと書いてあるのですが、私も議事録をとって見たのですけれども、よくわからないのです。だから、結論的に、一緒になった会議が今後どうやって子ども・子育てのところ、策定をどうやって会議的に結論を出したのか、結論のところを教えていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"２番目のひろまち保育園の件につきまして、確かに第２回目の議事録のほうでも保育の質についての質問が出ていまして、それにつきましては、保育士がかわるということに対するのが一番保護者説明会でも多かった質問だったということが、議事録に記載されております。","voiceIndex":88,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ひろまち保育園のところは、今、急に聞いてもなかなかわかる問題ではないと思うので、４月以降というか、きっと３月の終わりあたりから、どうやっていこうかというところで、いろいろ手厚くやられているのではないかと思っているので、その辺はきちんと、業者がかわったので、保護者の方に心配をさせない、子どもたちを安心して預けられるといったところの引き継ぎがどのようにされているのか。","respondent":"吉田保育施設調整担当課長、高山子ども育成課長","answer":"子ども・若者の会議のメンバーについては、かぶる者もありますし、同じになる者もあります。ひろまち保育園の引き継ぎにつきましては、後日お答えさせていただければと思います。今般、子ども・子育て会議の場で、次世代育成支援対策推進行動計画の部分につきましては、今後策定を予定しております（仮称）子ども・若者計画と一体的に審議をすると。そのようなことについてご了解をいただいたものです。","voiceIndex":90,"id":"exchange-027"}]},{"id":"topic-05","title":"平成２９年度学級編制","agenda":"平成２９年度学級編制","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ピンクの弾力的運用なのですけれども、品川区の判断でやったものだということでしたけれども、これは何か条例とか、そういったものに基づいてやられているということなのでしょうか。","respondent":"有馬学務課長","answer":"したがって、こういう場合が必ずこうとかという明確な基準というものはないというふうなことで認識しております。","voiceIndex":97,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"就学相談の中で、特別支援が必要な方がいるということで、人数を少なくして、指導が充実できるようにということで、こうされているということでよろしいのでしょうか。","respondent":"有馬学務課長","answer":"ピンクのところでいいますと、いわゆるここについては、普通級には通わずに、通級のみで行くという判断が出たお子さんが、先ほど言った三木小学校と上神明小学校には大体７名ぐらいずついるということで、それの配慮ということで１クラス増やして、そういうふうにいくと。","voiceIndex":99,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"仕組みの問題で教えていただきたいのですけれども、ここで区の判断での学級編制ということで、学級数が計２クラス分増えているわけですけれども、それは担任の数が２人余分に必要になってくるということで、これは、全体、トータルとしては、固有教員がいるからできることなのですか。確認です。","respondent":"有馬学務課長","answer":"ということで、この場合につきましては、区の固有教員を活用してという形で、区の判断による学級編制という形でお示しをしております。","voiceIndex":101,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"今の固有教員のところなのですけれども、今、手だてが必要なところで、少人数にして学級数を増やすというところはわかったのですが、固有教員の配置について、ほかに基準があるのか。概要にはどこに固有教員を配置されているかは書いてあるのですけれども、どういうところに配置をしているのか、全体の人数と、あと、どういった考えで配置しているのか、基本的なところを教えてほしいのが１点です。","respondent":"有馬学務課長、熊谷指導課長","answer":"小山台小学校が１１名、日野学園が５名ということで、合計１１０名、兄弟で入れなかった方が３名です。中学校のほうは、戸越台中学校で６名ということになってあります。固有教員の配置ですが、これまでと変わってございません。１５中学校区に２名ずつということで配置しておりますけれども、ただ、この２校については、そうした配慮も踏まえて配置をしています。","voiceIndex":103,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"確認","question":"学年が変わるときに転入された方がいて、直前にクラスが１つ増えたところがあるとお聞きしているのですけれども、２クラスだったのが３クラス、そのときにかなり影響があったと思うのですが、そのあたりをどう対応して、カバーされたのかということと、そのほか、もしもう一人転出されると、次の年度はまたクラスが３つから２つになってしまうのかということの確認です。","respondent":"有馬学務課長","answer":"要するに人数の基準に照らして、１人でも２人でも増減すれば学級数は増減していくということにはなります。","voiceIndex":106,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"確認","question":"それが非常に直前だったので、中学校の先生は、言葉は悪いですけれども、１クラス分の先生が増えた訳ですけれども、中学校の場合は教科の問題があるので、そこの教科のほうで先生のやり繰りとかが結構大変になることがあると思うので、その辺ご苦労されて新年度に臨まれたと思うので、そこのところのお話と、これがまた９年生になったときに８０人になると２クラスになるのですよねという確認です。","respondent":"熊谷指導課長","answer":"ただ、１名増になっていますので、次年度、クラスが１クラス減ってしまったときには、過員ということで、次年度の異動の教員を過員対象として異動させるということになっているところです。","voiceIndex":108,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"急にクラスの数が増えるということは大変ですが、一方で学校運営上でもいろいろ、行事などでもやりやすくなる部分もあるということで、非常にいいことなので、現場の先生方が随分ご苦労されて、時間割も全部変えたというふうにお聞きしているので、そのあたりも教育委員会のほうでバックアップしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-034"}]},{"id":"topic-06","title":"平成２９年度品川区立学校長・副校長、幼稚園長異動者名簿","agenda":"平成２９年度品川区立学校長・副校長、幼稚園長異動者名簿","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"３点目、逆にどんどん再任用の校長先生が増えていらっしゃるということなのですけれども、これはまだまだ増えていくということで、背景には管理職不足といったこともあると思うのですが、それについては区教委としてどのように、今後もさらに再任用が増えていくのか、あるいはもうちょっと管理職に対する魅力を上げていくとか、あるいは負担軽減ですとか。","respondent":"熊谷指導課長","answer":"２点目なのですけれども、まず、幼稚園なのですが、幼稚園の採用は２３区で実施しております。そういった中で、今回のように人事交流ということで、お互いに園長の交流、または副園長の交流といったことをこれまでも行ってまいりました。","voiceIndex":118,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"今後もこういう方が出てくることを期待して、そうすると、次は校長先生という話になるのですけれども、いろいろ壁があるということをお聞きしたのですけれども、区独自の先生方がこのように副校長先生にはなれますけれども、校長先生になるためのハードルがかなり高いとお聞きしているのですけれども、もちろんなっていただいて、品川区の学校の責任者になっていただくことを期待してという意味で。","respondent":"熊谷指導課長","answer":"そういったところを、現在固有教員をとっている杉並区、まだ校長を輩出しておりませんので、杉並区と連携しながら都に求め、また、国にも求めていくことを行っていきたいというふうに考えております。","voiceIndex":122,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"仮に人事交流で都費の方になったとすると、人事交流ですから、そこで退職されるわけではなくて、戻ってくると。そうすると、校長先生ではなくなってしまうということなのでしょうか。","respondent":"熊谷指導課長","answer":"そのときに、区の職員ですので、今後、校長職という立場でいくのか、また、区の教育委員会の何らかの立場でいくのか、そういったことも含めて、副校長が出たところですので、検討を進めてまいりたいと思います。","voiceIndex":124,"id":"exchange-037"}]},{"id":"topic-07","title":"品川コミュニティ・スクール","agenda":"品川コミュニティ・スクール","exchanges":[{"speaker":"高橋（し）委員","kind":"確認","question":"ちょっと確認なのですけれども、区費教職員等の活用に関する意見が言えるとあるのですけれども、これを読まれても、区費教員ということがわからない方もいらっしゃるのかと思ったので、説明するときに補足して、本当は注釈みたいなのがあればあれなのですけれども、そういう形をしていただけると。何かフォローしていただくことが大事かと。どこかに区費教員の説明というのは入っているのでしょうか。","respondent":"熊谷指導課長","answer":"さまざまな活用について、こんなことをしてほしいのだけれどもということで例を出しておりますが、また学校で説明される際にも、そういったことでということで、区費教職員とは一体どういう人たちなのかということの説明も加えていただくように、伝えていきたいと思います。","voiceIndex":131,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"最後、１つだけ。現在１５校があるのですけれども、コーディネーターの方が入ってやられていると思うのですが、もう決まっていないところはないのでしょうか。１６校についてそういった状況のところが今どれぐらいかというのをお尋ねします。","respondent":"熊谷指導課長","answer":"平成２９年度の指定校につきましては、まだこれからというところもありまして、９割ぐらい決まっているのですけれども、実際に走りながら探していきますという所もありますので、やはりコーディネーターは重要ですので、丁寧に学校が見つけて、そして。","voiceIndex":133,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"今日これをいただいて、体裁はいろいろご苦労があるのだなと受けとめましたけれども、内容的には特に変わったところはないと受けとめていいのでしょうか。やはりこれから始まりますよね。その辺をどう具体的に進めていくのかというのが大きな課題であると思うのが１つです。いろいろな人のお力をかりるという意味では、ちょっとそこが心配だというご意見もいただいたので、その２点をお伺いしたいと思います。","respondent":"熊谷指導課長","answer":"ですので、校区教育協働委員会で話し合った内容を実際にボランティア、学校支援地域本部におろしていくときに、これは地域支援本部にやってもらうこと、これは教員がやること、さまざまあると思いますので。","voiceIndex":135,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"意見","question":"お力をいただく人を選んでいくというか、なかなか難しいと思いますし、あと、コーディネーターの仕事もたくさんあるので、複数名にしたらどうかというアドバイスもありましたし、また、そういった意味では、校長先生の役割も、ものすごく人員が増えてくるという中で、大変であろうと思っています。今は思っている段階なので、またいろいろ現場の声もこれから聞かせていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-041"},{"speaker":"あべ委員","kind":"意見","question":"このパンフレット、デザイン、頑張ったというだけあって、とてもかわいい出来になっていて、２０１７ということで、多分また来年は２０１８を出されると思うのです。２０１８のほうではぜひ言葉をもう少しやわらかくしていただいたらいいのではないかと思います。","respondent":"熊谷指導課長","answer":"大分やわらかくしたつもりだったのですけれども、私たちがかたいので、まだまだというところはありますが、ただ、今回、２０１７としましたのは、まず学校できちんとこれを使いながら説明をしていただくというところと、あと、今ご意見ございましたように。","voiceIndex":138,"id":"exchange-042"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"創刊号はご説明いただいて、今回３号ということで、２号の報告がなかったと思うのですけれども、何か違いがあるのでしょうか。今、年度当初だということだったのですが、そういうことなのでしょうか。","respondent":"横山品川図書館長","answer":"創刊が昨年１０月でありまして、年度初めに当たっては初めてでしたので、ご紹介がてらご報告させていただきました。","voiceIndex":146,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4910#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":56331,"voices":148}},{"id":"h29-20170421-5","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"総務委員会","time":"午後 １時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年度組織改正","agenda":"平成２９年度組織改正","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"地域振興部の産業活性化担当、一定の方向性が出たので廃止という説明でしたけれども、今回、総務委員会ということもあって私も具体的には承知していないのですが、確かに担当を設置して、そしてＳＨＩＰをつくり、さまざまな施策をやってきたのではないかなという認識は持っているのですけれども、その辺、もう少し具体的に教えていただきたいなと思います。","respondent":"柏原企画調整課長","answer":"商業・ものづくり課になった際に、今後の産業施策をどういった形で進めるのだということで、区の中でも方向性の検討を行ったところです。それをリードしていく形での産業活性化担当ということで、課長ポストとなったものです。","voiceIndex":24,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"長期基本計画の人口推計等も、この間も随分やって、かなり具体的な冊子なんかもつくられてやっていることはよくわかっているのですけれども、それよりもさらにもう少し突っ込んだというか、もう少し具体的なというか、体制をもっと広くしてやる必要があるというようなご認識なのですか。","respondent":"柏原企画調整課長","answer":"一例として人口推計を挙げさせていただきましたけれども、人口推計の部分で申しますと、人口が何年後にどのぐらいになるのだというような推計をするわけですが、これまでの推計の中で、その推計以上の動きがあったりだとか、それからあと、経済の状況であったりとか。","voiceIndex":26,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"最後に、将来に向けた人口推計をしていくということは、それは本当に大事なことだと思うのですけれども、将来ばかり見ていないで、今の状況、現実を見たり、足元を見たり、そういうことも同時に、もちろん私が言うまでもなく、そういうご認識を持っておられると思いますけれども、やっぱり今の区民の状況がどうなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"今、交代されて新しい課長、部長がこうやって総務委員会の席につかれているわけですが、榎本部長ももともと企画財政課長でいらっしゃる。総務委員会の方は今回ほとんど変わらない。場所、席は変わっていますけれども、そういうことが何かあるのですかとちょっと不思議に思うのですが、簡単に教えてください。","respondent":"黒田人事課長","answer":"人事異動につきましては、退職等がありまして、その際の組織の必要に応じて人材を配置しているということで、派閥等があるものではございません。","voiceIndex":30,"id":"exchange-004"}]},{"id":"topic-02","title":"ケーブルテレビ品川による地域ＢＷＡ事業の開始","agenda":"ケーブルテレビ品川による地域ＢＷＡ事業の開始","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"最初は個人所有のところでやっていたのですけれども、最近は、数年前から品川区も場所を提供していただいて、大変喜ばれている状況があるのですが、そういう個人というか、エリアとか、そういうところは全く関係なく、イッツ・コミュニケーションズ株式会社、こういういわゆる企業との、無線だから個人というか全く１人でというだけではなくて。","respondent":"柏原企画調整課長","answer":"アンテナの設置の場所がどの辺からですけれども、具体的にどこからということはまだ聞いていないのですが、区内全域がカバーできるようにということで、公共施設も含めて、アンテナ設置については、協力を得ながら、設置できるところから進めていきたいという形で聞いてあります。","voiceIndex":36,"id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"ＦＭだったかもしれません。でも、無線として随分頑張ってこられて、高いアンテナを立てて、非常に苦労して、機器の精度も含めて苦労しておられて、何度も区で補助金を出してくれないかみたいなことも含めて、そんなお話をされたことがあったのですが、ＦＭ放送と言っていましたね。すみません、間違えました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今回、自治体で免許を了解するということで出すのですが、これによって特段ケーブルテレビ品川に独占権というのですか、そういうふうに縛られることはないと考えてよろしいのですよね。","respondent":"柏原企画調整課長","answer":"その帯域を使うのですけれども、例えば区と連携して防災目的等で使うときは優先的にその回線がつながるような仕組みにはなるのですが、それ以外のところでは、一般で使う場合には、本当に一般と同じ使い方になりますので、全国的に使っている通信の会社。","voiceIndex":40,"id":"exchange-007"},{"speaker":"つる副委員長","kind":"質問","question":"アンテナの設置なのですが、公共施設とかを中心にという答弁があったかと思うのですけれども、アンテナの設置協力費みたいなものがこういう場合に発生するのかどうかとか、月とかですね、そういう何らかの収入になっていくのかどうか、このあたりを教えてください。","respondent":"柏原企画調整課長","answer":"聞くところによりますと、１つのアンテナで２キロ四方ぐらいをカバーするというところで、先ほど申しましたように、２０カ所以上はつけないといけないということです。","voiceIndex":43,"id":"exchange-008"},{"speaker":"つる副委員長","kind":"確認","question":"確認ですけれども、そもそも区の公共施設にしろ、そうでないにしろ、こういうアンテナを設置するときというのは、何らかの費用が発生するもの、例えば電柱だとか電線だとか、区としていただくものという部分と、あとは、私も以前の経験上、民間の携帯電話会社にアンテナを設置させたときに収入になるというところで協力をしたという経緯があるものですから、こういう場合にそういった何らかの収入。","respondent":"立川経理課長","answer":"区の施設、道路、公園等にアンテナを立てるとか電柱を立てるとかといった場合は、全て規定により料金をいただいているです。","voiceIndex":45,"id":"exchange-009"},{"speaker":"つる副委員長","kind":"質問","question":"そもそも前提でそういう料金が発生するものかという。そこをもしケーブルテレビ品川から伺っていなければ、また別途で結構ですけれども。","respondent":"柏原企画調整課長","answer":"今、経理課長からもご答弁させていただきましたけれども、区の施設にアンテナを置いてということであれば、料金というところで想定しますので、それは使用の用途によっていろいろ規定とかありますので、その規定を見ながら、どういった形でお貸しできるか。","voiceIndex":47,"id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"話がわからなくなってしまったのですけれども、サービス自体は、２の、「サービス開始後、区内避難所の通信環境の提供を行っていく」というのが今までのやりとりだったのですが、スケジュールの平成２９年４月から９月の間に全てのサービス提供に向けた整備を行っていくということでいいのですね。","respondent":"柏原企画調整課長","answer":"ケーブルテレビ品川に聞いてありますのは、４月から順次ということで話は聞いていたのですが、アンテナの設置の具合によっては、１個アンテナを設置してもサービスはできないような状況ですので、９月までには全部準備をして。","voiceIndex":50,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、４月から９月のある程度の一定期間をもっても、既に今４月ですから、２１日たっていますが、このサービスに向けた準備あるいは整備等の着手はしているけれども、９月までに全てのサービスが行われるような段取りを立てていって、９月以降は、書いてあるように、サービスが開始されるという時系列でいいのでしょうか。","respondent":"柏原企画調整課長","answer":"今ご指摘いただいたとおりでございまして、そういったスケジュール感で動くということで、ケーブルテレビ品川からも聞いてあります。","voiceIndex":52,"id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"もし活用されているところがあれば、そういったところも教えていただければと思うのと、免許取得に先立ち、地域福祉に寄与するといったお話もありましたけれども、防災対策等で連携することは確認されていますが、その後のインフラ拡大という部分も、そういう部分ではできるのかどうかを確認されているのかどうか、余地があるのかどうかというのを教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"区での今後の展開ですけれども、設置の状況等を見ながらですが、先ほど申しましたように、防災の関係でもう少し広く使えないかというようなところの検討であったり、例えばこれもほかの自治体の事例ですけれども、商店街の中の地域だけ、エリアのネットワークといったものとか。","voiceIndex":58,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。そういった意味では、今後、品川区、エリアを絞っても可能だし、防災対策以外でも見守り、監視等でも活用ができるのではないかというところでしたが、そういったものを検証していくところの必要性について、そういった方向性はどういう感じで進めていくのかというイメージがもしあれば、教えていただきたいです。","respondent":"柏原企画調整課長","answer":"単に区が全部行うのがいいのか、まちの方というか、地域の方が主体で動くのがいいのか、そういったところもありますので、他自治体の事例等をよく見ながら、区の中でも検討を進めたいと思っています。","voiceIndex":60,"id":"exchange-014"}]},{"id":"topic-03","title":"品川音頭","agenda":"品川音頭","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"うまく歌詩におさまってよかったと思うのですけれども、１点、前の陳情を審議した委員会でも著作権のことが議題に上がって、歌詩のもともとの公募した方の著作権は品川区にあるけれども、補作詩の方のほうの著作権の問題ということで、これから協議ということなのでしょうか。","respondent":"中元広報広聴課長","answer":"これまでに文化庁にも確認させていただいたところ、今回のケースですと、著作権の法的な問題ということもありますが、まずは歌詩に手を入れるというところがあるので。","voiceIndex":66,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"それで、一部手直しをしただけで八潮の皆さんのご要望が入るということで、本当に喜ばれるのではないかと思います。この「八潮水辺も」と「笑顔に」という言葉を選ばれた方はどこのどなたか、個人名は別にいいのですけれども、どういうふうにしてこういう言葉が決まっていったのかなという経過を教えてください。","respondent":"中元広報広聴課長","answer":"こちらは区内の音楽家の方にご相談をしながらご提案をいただき、ただそれをそのままということではなく、区としても、広報広聴課といたしましても検討し、また、区の内部でも会議等を開き、検討した結果、これがよろしいのではないかということになりました。","voiceIndex":70,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"（２）に歌無ダンスリミックスというのがいまいちわからなかったので、どういうふうになるか教えていただきたいのと、あと、先ほどのお話の中でも、歌詩の変更は最小で、ご家族や遺族の方にもご了承いただくといっても、八潮というところをしっかりと入れていかなければいけないというのは陳情があったのでわかるのですが、「踊る人の輪」というのが「踊る笑顔に」に変わっている部分について。","respondent":"中元広報広聴課長","answer":"もう１点の「踊る人の輪」ですが、先ほどと繰り返しのご説明になりますが、区の基本構想の「輝く笑顔」というところの「笑顔」を入れていったらどうかということで、区として考えさせていただきました。","voiceIndex":72,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"八潮を入れてほしいというお話だったと思うので、もともとつくっている方の思いが詰まっていると思うので、こちらはわざわざ変更しなくてもいい点でもあるのかなと感じたので、「笑顔」も大切ですが、「輪」も大切だろうと思っているので、その辺、何かお考えがあれば、お話いただければと思います。","respondent":"中元広報広聴課長","answer":"先ほどの歌詩のところですが、委員のご意見も踏まえまして、今後、検討、調整をさせていただければと思います。","voiceIndex":74,"id":"exchange-018"}]},{"id":"topic-04","title":"オープンデータ利活用による地域課題を考えるワークショップの開催","agenda":"オープンデータ利活用による地域課題を考えるワークショップの開催","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"この募集の仕方なのですけれども、大勢集まってきたとして、抽選の仕方なのですが、例えば地域とか年齢とか、そういうことは一切なく、純粋にまるっきり全体の中からいわゆる抽選をするという趣旨なのでしょうか。その辺を教えてください。","respondent":"仁平情報推進課長","answer":"さまざまな年代の方とか性別関係など、平均して集まっていただければうれしいかなと思うのですけれども、公募抽選という形ですので、別に色をつけたような抽選はとらずに、シャッフルした中で、その結果に沿ってということで、公平性を担保していきたいと考えております。","voiceIndex":80,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"だから、みんなで一緒になって地域づくり、まちづくりを考えることはいいのだけれども、その辺、あまり心配しないで、こういう企画を立てて、平成２８年度の制度で採択されたというところなので、あまり心配する必要もないのかなとも思うのですが、そのあたりの齟齬が出たときに、どういうふうにしたらいいのかなというのを教えてください。","respondent":"仁平情報推進課長","answer":"方向性が皆さんでまとめるには難しいなという方向性になれば、講師と相談しながら、どういう対応をしていくかというのは、区の委託事業ではありますので、ある種、その辺は連携しながらという形になると思いますけれども。","voiceIndex":83,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"できるだけ区民の総意というところで、大事にしていただければと思います。それから、さっき聞いておけばよかったのですけれども、恥ずかしい話なのですが、今後の予定のところに、１０月にアイデアソン、１１月にハッカソン、これがわからないので、お願いします。教えてください。","respondent":"仁平情報推進課長","answer":"そういう意味では、いわゆるホワイトハッカーといいますか、いい意味でコンピューター関係が詳しい方というのがもともとのハッカーという意味で、そこに先ほどのマラソンということで、ハッカーとマラソンを掛け合わせた造語になっておりまして。","voiceIndex":85,"id":"exchange-021"},{"speaker":"吉田委員","kind":"提案","question":"土曜日の１時から４時ということなので、わりと誰もが参加しやすい時間帯、曜日設定かなと思いますので、とりあえず１回やってみるという感じで、そうしないとわからないですから、やってみるというのはいいかなと思います。できましたら、最終的な結果のところだけではなくて、１回１回ご報告があると私たちも意見を言ったりしやすいかなと思いますので、その辺だけ、要望します。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-022"}]},{"id":"topic-05","title":"八潮北公園改修工事請負契約","agenda":"八潮北公園改修工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"何メートルとかという数字がないので、どのくらいの広さかわからないのだけれども、コート舗装（砂入人工芝）のところで７４１平米あるというから、相当大きな場所なのかなと、敷地面積がね、そんなふうに想像するのですけれども、全然わからないので教えてほしいのですが、日本パブリックサービス株式会社も含めて、それなりの知識のある事業所ということでいいのですよね。","respondent":"立川経理課長","answer":"公園全体から見たスケートボード場の位置ですけれども、基本的にこの計画の前段階で、フットサルコートやテニスコートをまず計画しておりまして、それで、その後、オリンピック競技にスケートボードが決まったということもありまして。","voiceIndex":93,"id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"利用したいという場合には、どこかに申し込んで、申し込み制なのですよね。どなたか管理者を配置、常駐も含めて、そのあたりとか、あと、料金は、これから設計してやるので大分先だと思うのですが、その辺はどんなふうに考えているのか、考え方を教えてください。","respondent":"立川経理課長","answer":"料金については現在検討中ですけれども、周辺にスケートボード場が幾つかありますので、そちらの料金設定の状況とかを勘案して検討すると聞いているところです。管理につきまして、有人の管理施設がありますので、一体的に管理していくということです。","voiceIndex":95,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"すごく基本的な質問です。全然スケートボードがわからないので、スケートパーク設備の中のコンクリート製セクション３基が何かを教えていただけますか。","respondent":"立川経理課長","answer":"平面図の一番下のところなのですけれども、コンクリート製セクションということで、いわゆるコンクリート製の遊具というか、そこを滑って遊ぶみたいな、そういったイメージです。","voiceIndex":98,"id":"exchange-025"},{"speaker":"大倉委員","kind":"確認","question":"いろいろお話が出たので気になって聞かせてもらうのですが、スケートパークの特徴とかというのが品川区のスケートパークはあるのか。中級者向けとか初心者向けとか、幅広く使えるのか、上級者も楽しめるようなものなのか、どういう人たちに利用されたいのかというのも、前、もしかしたら聞いたかもしれませんが、改めて確認をさせてください。","respondent":"立川経理課長","answer":"そういった内容、どういった利用者を想定するかとかいうことも含めまして、日本スケートボード協会と協議しながら計画をつくっていくです。","voiceIndex":103,"id":"exchange-026"},{"speaker":"大倉委員","kind":"質問","question":"これからこういう内容については検討していくというお話なのですか。","respondent":"立川経理課長","answer":"どういった遊具を配置するかとか、そういったことを日本スケートボード協会と協議しているですので、今後、設計内容に入っていくと考えています。","voiceIndex":105,"id":"exchange-027"}]},{"id":"topic-06","title":"品川区西五反田二丁目付近再構築工事請負契約","agenda":"品川区西五反田二丁目付近再構築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですけれども、再構築工事と出ていますよね。ということは、何年か前に工事をされていて、やはり排水の能力が不足したために、今回、それも兼ねて行うという対応なのですか。何年ぐらい前にやったのですか。","respondent":"立川経理課長","answer":"再構築工事につきましては、整備後、約５０年経過したことから、実施していると聞いております。","voiceIndex":111,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2072#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26866,"voices":117}},{"id":"h29-20170425-14","meetingId":"h29-cm04","date":"2017年4月25日","dateIso":"2017-04-25","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年請願第４号、羽田空港機能強化による品川区低空への新飛行ルート","agenda":"平成２９年請願第４号、羽田空港機能強化による品川区低空への新飛行ルート","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な影響の説明という点では、まず最初にお伺いしたいのは、再三、前回も前々回も伺ったのですが、主要駅ですら高さが明らかにされていないというところも何なのかなと思うのですが、私もこの委員会で聞いたのですが、目黒、大崎、立会川の主要駅、あと、影響が大きい八潮の高度や騒音の程度については、国に回答を求めていただいたのでしょうか。それと、回答があったのでしょうか。伺います。","respondent":"中村都市計画課長","answer":"各品川区内の主要駅からの高さですけれども、こちらのほうは過去に国のほうへは確認をした結果、まだ案という段階、そして、この駅の上空を通るかどうかも、まだ詳しい位置というのは未定で、あくまで案の段階ということですので。","voiceIndex":19,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"大体計算すれば出ると思うのです。この計算のやり方で間違いないかというのを伺いたいと思いますし、また、私たち、試算としてはこの高さだというふうに試算してみたのですが、この試算で正しいかどうか、国は言ってくれないわけですから、国に事実確認をしていただきたいのですけれども、いかがでしょうか。それは高さの点。伺います。","respondent":"中村都市計画課長","answer":"納得しているのかですけれども、先ほど最後の質問でも同じように、Ａ滑走路とＣ滑走路、左から右への飛行のための設備ではないかですが、新飛行ルートを仮に国が実施をするとしたときに、Ａ、Ｃ滑走路、両滑走路を使う、このための設備としては。","voiceIndex":23,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"高さのところ関してはちょっとくどいのですけれども、すみません。それは重大だと私は思います。現状、昨年の２０１６年では既に２,４００万人を達成しているわけですけれども、お伺いしたいのですが、現在の訪日外国人数のうちの羽田空港利用者の人数や割合というのは、どれぐらいなのでしょうか。伺いたいと思います。それをまずお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"訪日外国人の割合、空港の割合ですけれども、こちらのほうは羽田とか成田とか関西ですとか、重立った空港の中で占める割合が、羽田は全体の１２.６％、これは２０１５年の出入国管理統計からそういった数字の記載があります。","voiceIndex":25,"id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"大体１２％ぐらいだということなのですけれども、それが法務省、国の資料だということですが、２０２０年の４,０００万人の目標達成のためには、現在が、直近でいうと２,４００万人なわけですから、あと１,６００万人を増やすことが必要で、大体１.６倍にしなくてはいけないのですけれども、今度の新ルート計画、提案されているのが南風時の３時から７時で。","respondent":"中村都市計画課長","answer":"労働環境ですけれども、こちらのほうは航空関係に従事する方の人材、人員不足などがやはり新聞などでも先日書かれていたかと思いますけれども、こういったものにつきましては、労働の量に対してしっかりと適正な人員配置をしていただかなければ、事故というものは。","voiceIndex":27,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"この点からも、新ルートはやるべきではないということは明らかだと思うのですけれども、この観点からやはりやめるべきだと思うのですけれども、いかがでしょうか。が１つ。１,６００万人のうち、羽田空港で増やすというのは２１２万人なので、それを引くと、１,３８８万人分をほかの全ての空港で増やさなくてはいけないということになるのですけれども、そういう計画なのでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"国のほうからの説明の資料がホームページなどで掲載されているものでは、２０２０年オリンピック・パラリンピック開催以降の方策というのが、考え方として１つ示されております。","voiceIndex":29,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"労働関係のところはそういった、テロを防ぐための大事なものである検査の現場でも、労働者がどんどんやめているような体制になっているというところで、そうした中で、わざわざ都心のほうに海上ルートを持ってくるというのは自殺行為ではないですかと私は思っているので、そういった意味でもやめるべきではないかということをお伺いしましたので、そこの点はご答弁をお願いしたいと思います。","respondent":"中村都市計画課長","answer":"航空機の飛行の時間帯につきましては、これは外国の時差ですとか、あるいは国際線がピークになる時間帯といった、そういった対外的な接続の関係でこの時間が設定されているですので、今現在、出された案、実質４時間の中の。","voiceIndex":31,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺があるので、やはり今から将来の増便を見据えたような、将来の品川低空飛行のさらなる増加を危惧されているような状況がありますので、しっかりとこの時点で計画はやめるべきだということを言うべきだと思いますけれども、いかがでしょうか。現在インターネット公開というのはされているのか、改めて伺いたいと思います。","respondent":"中村都市計画課長","answer":"訪日外国人の増加に伴いまして、飛行便数が増加することによって、さらに品川区上空を通過する航空機の数が増加するのではないかですけれども、こちらのほうは、今、Ａ滑走路とＣ滑走路を利用する新飛行経路案に対する情報提供を求めているという段階ですので。","voiceIndex":33,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこでも言っているのかどうかというのは、１３回の幹事会のなどでどのような議論があって、品川区は何を発言したのか伺いたいと思います。今回の請願は、説明会について開いてほしいという、ある意味ささやかな要求かと思うのですけれども、説明会については再三求めているというふうに言っていると思うのですけれども、この幹事会等ではどのような議論になっているのか、それもあわせて伺いたいと思います。","respondent":"中村都市計画課長","answer":"この都の会議に出席して、品川区といたしましては、やはり区民の皆様の不安を払拭するための、地域への説明をしっかり行ってほしいということと、あと、必要な情報をしっかり提供してほしいと。これを国に伝えてほしいというようなことを申し上げております。","voiceIndex":37,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"しっかりと多くの方々が、これだけの方が品川区の上を飛ぶことで大変な犠牲が払われるということに対してやめてほしいと考えていますので、品川区がやはり反対、やめてほしいと言えば、局面は動くのです。ですから、必要な情報提供や不安の払拭など、説明を丁寧にという意見にとどまらない反対表明をぜひしていただきたいと。そして、連絡会も開いてほしいと。述べてほしいというふうに要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"いろいろと議論を伺わせていただいたのですけれども、例えば、先ほどのご質問の中にあった、全体の総事業費が区としては全体として把握していないとか、それから効果の部分、今いただいている資料では、国の資料なのですけれども、まさに国の資料っぽいなと思ったのは、例えば、国際線の処理能力が６万回から９.９万回と大幅に拡大するというふうに書いてありますけれども、昼間のかつ国際線ということで。","respondent":"中村都市計画課長","answer":"ただ、今、委員ご指摘の趣旨の中には、区として独自に何か調査をしたりですとか、あるいは極端に言えば、飛行経路案を区が考えて、これでやれば増えるではないかといったような提案すらも検討することも必要なのかといったものも含まれているかと思いますけれども。","voiceIndex":40,"id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"ご答弁ありがとうございました。１点目のほうなのですけれども、品川区としては、羽田空港の利用客がさらに増えることをプラスと考えているという、その考え方でよろしいのでしょうか。それはつまり、増便を品川区として望んでいるという意味になってしまうのですけれども、それでよろしいのでしょうか。ここを確認させてください。","respondent":"中村都市計画課長","answer":"そういった中で、まずは東京都も含めて国に対して意見を言っていく場合の分析などは連携して行っていく必要があるというふうに考えてありますので、そういったところは東京都にもそういった問題点を指摘してまいりたいと考えています。","voiceIndex":42,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"いずれにせよ、品川区としてもう少し当事者意識を持ってこの問題を考えていただきたいと思っているのです。完全に例えば、白紙撤回が役所として難しい、難しくないという議論もあるかもしれませんけれども、でも、どうやってできるだけ区民を守っていけるかという視点でぜひ物事を考えていただきたいのであって、質問にただ答えるために答えるような形で進めてはいただきたくないと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"伺いたいと思います。そして、労働問題のところで、国のほうでは人材育成に力を入れているというお話でしたけれども、先ほどもありました、実態に即していないと私も思います。先ほど示された事例でも、勤務状況が劣悪になっているというところで、どういった人材育成に力を入れているということをやっているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"人材育成ですけれども、これは国の説明会等、あるいは公表されている資料の中でも、パイロットの研修ですとか、あと、厳しい検査によってしっかりとした業務を行っていただく、また、そういった高い技術のもとで業務を行っていただくという。","voiceIndex":45,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"決定していない中で強行しようと国がしているという状況なのではないかと思いますけれども、区もそういった認識があるのか、改めて伺いたいと思います。そして、労働条件のほうでは、パイロットの研修などを行っているということでしたけれども、今回紹介された事例でいえば、検査員の方の事例でしたけれども、そういったところの人材育成はやられていないということなのでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"検査員の育成ですけれども、これは今回新たに国のほうで、駐機中の航空機に対して抜き打ちでチェックをするというところで、これは国の職員が行うですけれども、これはいきなり知識のない者が行っても検査はできないわけですので。","voiceIndex":47,"id":"exchange-014"},{"speaker":"のだて委員","kind":"確認","question":"もう一つの質問のほうで、飛ぶために限らないということで、決定ではないから飛ぶために限らないというお話でしたけれども、その可能性があるというお話でしたけれども、それはやはり可能性であって、実際には飛ぶための施設整備をしていると私は認識していますが、区の認識を伺いたいと思います。その後、約２カ月が経過しましたけれども、確認されたのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"飛行経路の見直しに必要な施設整備ということで、この資料には書いてあります。ただ、国のほうでは、今現在の品川区上空を南風時に通る経路につきましては、あくまで案だです。それ以外の説明は国のほうではございません。","voiceIndex":49,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"前回も安全性、世界各国で同レベルだと説明されましたけれども、各国、基準以上の部分についてはばらつきがあるのではないかと思っているのですけれども、いかがでしょうかということです。それと、１９９４年のときには、中華航空の墜落事故で２６４名の死亡者も出ているというところで、新ルートによる増便の国外航空機の割合もわからずに、安全性は同レベルと言えるのか伺います。","respondent":"中村都市計画課長","answer":"特に整備なんかは、機種がいろいろ違いますので、やはりなかなか機械化は非常に難しいと思います。そういった意味からしますと、しっかりと労働環境を適正に保っていただくことが、飛行経路下にある地域の安全につながると思いますので、これは国のほうに申し伝えてまいります。","voiceIndex":51,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"努力はされていると思うのですけれども、しっかり監視できていない部分もあるというところで、日本の航空機と海外の航空機が同レベルだと本当に言えるのか、改めて伺いたいと思います。そして、日本で国際基準より高い部分はあるのかということもお伺いしたので、改めて伺いたいと思います。","respondent":"中村都市計画課長","answer":"航空機の整備に関しましては、それぞれの機体ごとに整備マニュアルというのが個別に整備されていると聞いておりますので、その範囲の中でしっかりと適正な整備が行われていると考えております。","voiceIndex":53,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"そのためにも、そういった面でも新ルート計画、やはりしっかりと影響を区民にお知らせしていく必要もあると思いますけれども、以前、説明もこの委員会であったと思うのですけれども、この間も３回の説明会が品川でも行われてきましたが、改めて参加者が何人だったのか、それぞれについて、そして、合計人数もあわせて伺います。","respondent":"中村都市計画課長","answer":"大崎ニュー・シティですけれども、こちらが２日間合わせて７５０名、合わせて約１,３８０名です。それから、２月１１日のアトレでつい先日行いました説明会では、１日でしたが、速報値で３９６名です。","voiceIndex":55,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、約２,６００名が参加したと。延べ人数でいっても、その中で参加したというところで、区民は３８万人いるわけですから、そのほんの一部であると。区民に知らせていくためにも、やはりこの請願にもあるように、説明会を行うべきだと思いますけれども、いかがでしょうか。これを求めているのは、幹事会でもしっかりと発言されているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"国のほうへは、品川区は再三、区民の皆様、地域の皆様への情報提供、説明を行ってほしいという話をしておりまして、この説明会まで国としてやってもらっているところですけれども、また、直近では２月１１日に開催いたしましたが。","voiceIndex":57,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間も求めているというお話ですけれども、実際に国はやらないわけです。教室型説明会もやらないというところで、品川区や東京都がやることも必要だと思います。区が国を呼んで会場を確保して、そして、周知もして主催する説明会を１３地域センター管内それぞれで行うことを求めますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"今までもやってきておりますが、これからも区民の皆様へ周知するための説明会、これは区が直接説明をして、責任ある答えをするということができませんので、やはり国にしっかり参加していただくことが大切だと考えております。","voiceIndex":60,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひいろいろなところでやっていただきたいと思いますけれども、今のご答弁は、しっかりと進めていく、国と連携をとって区が主催で説明会を設定していくという認識でよろしいでしょうか。","respondent":"中村都市計画課長","answer":"形としては、あくまで国が主催ということになりますが、それに対する調整等の協力をしっかりとしてまいります。","voiceIndex":62,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"やはり区が国を呼んでしっかりと説明する場、これをつくっていく、このことをやっていくべきだと思いますけれども、区がやらない理由は何なのか伺いたいと思います。あわせて、先ほどの質疑でも、教室型説明会は国にやってもらわないといけないみたいなことをおっしゃっていたと思うのですけれども、それも区がやっていくこともできると思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"区が説明会を開催した中で、この計画をどうします、変更しますといった回答までできませんので、やはり最終的には国が発言をしていただかないといけませんので、やはりどうしても国主催、また。","voiceIndex":64,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後にしますけれども、国がやらない中で、区が主催して、国を呼んで説明させる、こういった場のやり方もあると思いますので、しっかりと国が説明するまで、教室型説明会を開くまで求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"結論を出すでお願いします。それで、態度は採択なのですが、今回、やはり計画への賛否を問うものではありませんし、丁寧な説明を求めるもので、その実行の必要性はどんな立場であろうが共通のものだと思いますし、意見書でも求めている議会共通の意思だということで、いち早く採択して、区も求めているというふうにおっしゃっていますが、議会からも後押しする必要があるのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"継続でお願いしたいと思います。これは非常に迷いました。というのが、要は、品川区や東京都、特に品川区は事業主体でないので、これを説明する主体にはなかなかなり得ないですよね。そういう手法も考えていただけないかということも含めて、今回は継続としていただきたいと思います。多分、区の事業でないものを区が説明会を開くというのは困難であるかと感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"区の職員が説明するのか、国の職員が説明するのかはっきりしないというのがありますけれども、区が会場を提供して、国にもっと説明会を開いてくださいということを求めるということなのか、そこははっきりしないのですけれども、品川区がもっと今回の問題を広く区民に周知する必要があるので、説明会を多く開いていただきたいということと、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-026"}]},{"id":"topic-02","title":"平成２８年請願第８号、住民の理解が得られない中、平成２９年度予算概算要求に、新ルート費用を入れないよう品川区として政府に求める請願","agenda":"平成２８年請願第８号、住民の理解が得られない中、平成２９年度予算概算要求に、新ルート費用を入れないよう品川区として政府に求める請願","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"終わっていることに対して、ここでどうこうというのはどうなのかと思っているのですが、その辺の確認だけ、委員長、お願いいたします。その上で、やはりこれ、どうしてもここで採決を行わなければならないというのであれば、当然、採択のしようもなく、不採択しかやりようがないものですから、そういう形になるとは思うのですが、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"ですから、特段、前回、内容が内容だからというところで取り下げの確認をお願いしているわけですから、であれば、他の請願と同様の扱いのまま進めていただいてもよろしいのではないかという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"継続で結構です。ただ、今回の、前回３月ですか、要するに、年度末の最後の行革委員会で、本来はそこで、これが最後の年度内の審議する場面なので、ここの結論によってはということで、何かそういうご配慮があってもよかったのかと、あのとき思い返すと思うのですけれども、そういう思いも含めて、一回継続で、ほかのものと一緒にまた審査を継続するということで結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"当時のこの審査自体のときにも私たちは採択を主張したわけですけれども、議会の審議で継続となって、今、こういう扱いになってしまっているわけです。ですから、私たちとしては、先ほどの趣旨で、結論を出すで、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"この請願について、どの部分を主要な請願趣旨ととるかという、その解釈にもよるのですけれども、まさに平成２９年度概算要求の内容そのものを求めているとすると、なかなかこれを入れるということが事実上難しいと思っている一方で、都心ルートの強行というところに焦点を当てた請願であると解釈するのであれば、その趣旨について賛同できるところもあると感じているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"結論を出すでお願いします。趣旨採択でお願いします。理由は、平成２９年度政府予算概算要求についてなので、これは既に予算が成立してしまったので、請願内容をフルに認めることはできないのですけれども、住民の理解が得られないまま、既成事実を積み重ねるような予算ということは問題だということの趣旨は酌み取るという理由で、趣旨採択でお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":31705,"voices":98}},{"id":"h29-20170426-18","meetingId":"h29-cm04","date":"2017年4月26日","dateIso":"2017-04-26","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京都宛の要望書","agenda":"東京都宛の要望書","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"基本的にいいと思うのです。したがって、どこの地域でもない品川区のエリアなので、品川区から東京都にその辺のことも、周辺道路のところ、要望書の項目４番にはこういうふうに書いていただいているのですけれども、団地との関係には直接触れられていないので、その辺をうまく挿入できないかと思ったりしていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"委員長のおっしゃるとおり、そこは指摘のとおりだと思うのです。できたら、その後に、「また」ということで簡潔に入らないかなと思ったりして、具体的な文章を出していない中でのあれで申しわけないのですけれども、正副のところで検討していただければありがたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"意見","question":"５番目のところ、反映をしていただいてありがとうあります。お任せいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"議運でやるときには、ここで確定していかないと議運で諮れなくなってしまうのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-004"}]},{"id":"topic-02","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認したいのですけれども、質問してよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる人が入れるような状況ではなくて、ただ立てかけてあって、廃棄物というか、ただ置いているような状況になっていて、ビーチバレーに対してどういう思いがあるのか。オリンピック・パラリンピックに対して、パネル、私も顔を入れて写真を撮りましたと課長も言っていました。どうなってしまっているのですかということだけお伺いしたい。よろしいでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういったものについては、職員が随時点検をし、皆様にご利用できるような形にしているはずなのですけれども、年度がわりのところで、言いわけがましくて大変恐縮なのですが、活動レポートについても新しい。","voiceIndex":30,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":5205,"voices":33}},{"id":"h29-20170428-10","meetingId":"h29-cm04","date":"2017年4月28日","dateIso":"2017-04-28","committee":"議会運営委員会","time":"午後 １時０１分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項","agenda":"特別委員会の調査事項","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"行財政改革特別委員会の備考について、区有施設、国・都有地等の有効活用について、一言意見、要望だけ述べたいと思います。これまでと同様ですけれども、区の土地や現状の暫定活用についても議論を深めていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":8669,"voices":40}},{"id":"h29-20170515-6","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"区民委員会","time":"午後 １時００分～午後 ３時０１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「支え愛・ほっとステーション」の開設","agenda":"「支え愛・ほっとステーション」の開設","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今日同時に厚生委員会にも報告があるということですけれども、地域活動課と、いわゆる社会福祉協議会に運営を委託するのですけれども、どういうふうに仕切っているというのか、役割分担をしているというのか、そこを伺いたいと思うのです。なり手が整わないという意味では、地域センターの所長や職員も含めていろいろ対応が求められてくるのか。","respondent":"遠藤協働・国際担当課長","answer":"なかなかなり手がいないといいますか、民生委員等も含めてですが、なかなか大変な部分があるというのは聞いておりますが、今回、支え愛・ほっとステーションというのが入ることで、何か相談事があれば、そこで簡単にといいますか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"福祉計画課でよかったでしょうか、調整しながらやっていくということですけれども、地域や町会の方にとっては、誰かやってくれる人がいないかということが非常にこの間、話題になっておりまして、ずばりそういうなり手についてはどちらの課が担当になるのでしょうか。コーディネーターの話もありましたけれども、そこだけもう一度ご説明いただけますでしょうか。","respondent":"遠藤協働・国際担当課長","answer":"それぞれ所管によって得意分野といいますか、それぞれつながりの強いところがありますので、そこは区側で一体となっていろいろなところに働きかけてやっていければです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"今までやってきた支え愛・ほっとステーション、その中で見えてきた課題と問題点、あと、そこをどのように改善していって、今回の開設に向けて動いているのかということを伺いたいのですけれども。","respondent":"遠藤協働・国際担当課長","answer":"ただ、今回、５地区新たになりますが、１３地区のうちの４地区が昨年オープンしたばかりということで、徐々に認知度は高まっているというところがありますので、その辺でいろいろなところで周知活動をしながら、地域支援員をどんどん増やしていければと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"新しく開設される荏原第一地域センターだったり、荏原第五地域センターの方からお話を伺ったときに、やはりすぐ支え愛・ほっとステーションができてほしいという声が聞かれたのですけれども、なり手不足というのがまだそんなに解消されていないといいますか、周知をこれからしていくということですけれども、どのように周知をして、人を増やしていくかということをお聞きしたいのですけれども。","respondent":"遠藤協働・国際担当課長","answer":"地域支援員というのは、説明が悪かったかもしれませんが、生活支援サービスの中のほっとサービスというなり手の方、日常生活にお困りの方が介護まではいかないという部分のところで、ちょっと手助けをしてもらえないかというところにボランティアが入って。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"意見","question":"今、これから開設される地域のほうでは、先ほども出ていたように、民生委員に結構負荷がかかっているようで、高齢者に対しての手助けをいろいろなところでやり過ぎて、民生委員が疲れてしまっている部分があるみたいで、やはり開設されるに当たり、ボランティアをしてくださる方がいっぱい来てくれたらいいなと思うので、その周知活動をしっかりとやってほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"これ、お二人だけではなかなか難しいのではないかと思うのですけれども、これまで開設したところの課題も含めて、コーディネーター２人で全部やっていくという、これはどのようにお考えでしょうか。","respondent":"遠藤協働・国際担当課長","answer":"は先ほど申し上げました、新たに登録いただいた地域支援員が定期訪問ですとか、電話で確認するという方法もあるみたいですので、その辺を含めまして、もちろんそれで手いっぱいになって、お二人だけではできない形でありますので。","voiceIndex":14,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。そうすると、細かい話で恐縮なのですが、例えば、介護が必要だという高齢者のご相談だった場合に、在宅介護支援センターとも連携をとりながらやっているという理解でいいのでしょうか。","respondent":"遠藤協働・国際担当課長","answer":"ご指摘のとおり、あくまでも地域支援員が行くのは、日常生活にちょっと支障があるけれどもそういう公的な介護は必要ではないというところがまず第一歩のところでございまして、当然、介護が必要な方につきましては。","voiceIndex":16,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺、どう相談者を必要なところにつないであげられるかというのは、非常に難しいのですけれども大事な分野だと思いますので、その点、これからもやっていくうちにいろいろな課題は見えてくると思いますが、その都度その都度、区民の皆さんの、ここは区役所に行く前段階の相談機能だというふうに皆さん理解をしていくところだと思いますので、頑張っていただきたいというところですが、いかがでしょうか。","respondent":"遠藤協働・国際担当課長","answer":"困った高齢者の方が、今ですと区役所のどこかに相談しに行かなければいけないところだったのを、最初に身近なところを入り口にして、今回、コーディネーターもいるということで、安心して地域センターに来られるように、地域センターの職員もそこにおりますので。","voiceIndex":18,"id":"exchange-008"}]},{"id":"topic-02","title":"今後の区の産業活性化に向けた調査の実施結果について（平成２８年度産業活性化推進事業）","agenda":"今後の区の産業活性化に向けた調査の実施結果について（平成２８年度産業活性化推進事業）","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"１点が、５８４万円をコンサルティング会社に費用として支払いをして、委託という形で調査をしたということですけれども、もう一度確認なのですが、この中身、いろいろ文章が書いてあるのですけれども、この文章は集約をしたコンサルティング会社が書いたものなのか、それとも職員がデータをもとにこういうものではないかというのを分析して、その後。","respondent":"山崎商業・ものづくり課長","answer":"先ほどグラフの母数になる７２２というのは、こちらの調査結果の集約のものということと、それから、その下に(3)、商店街アンケート及びインタビューの実施状況のところで３９票という、これが先ほどの３９の根拠になっているところです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問","question":"すみません。答弁漏れだったのですけれども、５６商店街というのは、要するにこれはイベント事業を実施している区内商店街ということで、何かしら品川区がかかわっているという解釈でいいと思うのですけれども、それであれば、５６商店街というのは、見える商店街なわけですから、なぜ５６商店街のアンケートをとれなかったのか。これ、よくあるパターンなので、５６商店街中で３９商店街なわけですよね。","respondent":"山崎商業・ものづくり課長","answer":"それで、１６ページは品川ブロックのエリア、それから１７ページは大井海岸ブロックというようなところで、１０ブロックありますので、少なくともブロックの連合体で活動している商店街の会長には聞こうではないかという趣旨で、１２カ所。","voiceIndex":27,"id":"exchange-010"},{"speaker":"いながわ委員","kind":"質問","question":"でも、その商店街はおそらく区商連を通してイベントを行っているわけですから、何かしらの補助が入っているわけです。でも、そこはやはり間接的ではあるのですけれども、品川区の商業にかかわることですから、これ、多分、５年に１回ですとか、１０年に１回なのかわからないですけれども、今後経済センサス等も含めた数字上のものを含めてこういうものをつくり上げていくすごく大切なものだと思うのです。","respondent":"山崎商業・ものづくり課長","answer":"ちょうど製造業のほうと同時並行で行ってきたということと、商店街のほうは実際のヒアリング調査は７月４日から７月２９日という限られた時期にできる限りのヒアリングを行ったというようなところで、調査のボリューム、あるいは回収については。","voiceIndex":29,"id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問・要望","question":"母集団は多ければ多いほどいろいろな声が聞こえて、それで、パーセンテージですから、それは多いほうがいいと思いますし、回収率も多いほうがいいのではないでしょうか。なぜ書けなかったのか。要は、時間がないから書けないのか、それとも、商店街、会長、理事長がいるのだけれども、理事長がもしかしたら一人で全部行っていて、そこまで回らなかった、そこも問題なわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。幾つか伺いたいのですけれども、全体の概要について、製造業・情報通信業編と商業編と今回２種類ですけれども、ここに示されている新たな事業展開や新たなさまざまな事業について、スケジュール感といいますか、テンポといいますか、ここに書かれていることはいつまでに実施を目指すといいますか、今後のスケジュールやテンポについてご説明いただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"調査の概要版につきましては、あくまでも調査結果に基づいて、こういった方向の施策の展開が必要ではないかということで、これからこういう施策を調査結果に基づいて打っていくということを書き記しているものではありませんので。","voiceIndex":32,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"職場の復旧というものがなければ、まちのなりわいや成長発展につながっていかないのです。東京都との調整が必要ということではありますけれども、中小企業であり、１００名程度、２００名程度の製造業であり、それぞれの雇用の確保という意味でもこういう防災対策は必要だと思うのですけれども、この点については今後どういう展開を考えていらっしゃるのか、現状を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"いわゆる震災以降、区民の方々の生活の部分に加えまして、区の活性化の重要な要素です商店街なり中小企業の方々そのもののそうした有事の際の対応というのは、すごく大事なことだと区としては認識しております。","voiceIndex":34,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう指摘がありますけれども、ずばり都市計画道路、補助第２９号線、特定整備路線と市街地再開発事業というのが、商店街を私は壊しているのではないかと思っているのですけれども、その点について、この最終報告ではどのような考えが示されているのか伺いたいと思いますし、そういう商店街を壊す計画はやめていただきたいと思っているのですけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"調査結果の最終のほうでは、先ほど区民の皆様の買い物の便などに供するインフラ機能というようなことにプラスアルファして、いろいろ社会的な機能、商店街の持つ公益化、多様化などにも対応していく必要があるので、それに対して支援を検討すべきだというような調査結果です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、ずばり補助第２９号線や戸越公園駅周辺のまちづくり、道路や再開発で商店街が壊れている認識はあるのかと、そこを改めて伺いたいと思います。道路と再開発で商店街を壊して、それを逆に活かしてつくるという、これが区の商業支援の基本的な考え方なのか、ここは改めるべきだと思うのですけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"個店によって、現道のままなのかというようなことに置かれておりますので、そういう意味では、商店街全体の活力ということで、そちらのほうに商店街の方々の中でもいろいろなご意見があって、ただ、１つ基本的な方向としては、このにぎわいなり。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから伺っているのは、補助第２９号線や再開発が商店街を壊しているという認識はあるのかと、そこを伺っているので、しっかりと区の考えをご説明いただきたいと思います。それだけに、区のこういったまちづくりに関与する社会インフラ機能というのは、いわゆる再開発事業の推進が位置づけられているのかいないのか、そこをしっかりとご説明いただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"現状でも、路線型の商店街以外の形態を持つ商店街、例えば、八潮も商店街ということで、パトリアを中心にした個店の集積に対しまして、商店街機能として区としてご支援をさせていただいたりというようなことですので。","voiceIndex":40,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"お伺いしたいのですけれども、５ページ、先ほどご紹介のありました、品川区が外国人旅行者の訪問場所として１３番目で、街歩きと日本食を楽しむということで上位に上がってきているということと、あと、９ページで、全国でも３６位にランクされて、都市として高い魅力を有しているという評価があるという話なのですけれども、これは具体的に品川区のどの辺を指しているのかというのが気になっていて。","respondent":"山崎商業・ものづくり課長","answer":"区の中では有数の、武蔵小山もそうですけれども、すぐ目黒区側と接しておりますので、商売上の商圏というのですかね、そのエリアというのは、目黒区の区民の方々も含めてというようなことで考えて対応しているというようなことで、ご理解いただけたらと考えています。","voiceIndex":42,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"は１０ページなのですけれども、商業集積のことなのですけれども、年間商品販売額を見ると、不動前駅周辺と大井町駅西部が突出して多くあるのですけれども、不動前駅の周辺が何で突出しているのかというのがすごく気になっているのですけれども、具体的に教えてください。","respondent":"山崎商業・ものづくり課長","answer":"すみません、先ほどの摘示いただいた部分もそうなのですけれども、今回の調査結果につきましては、先ほどいろいろございましたが、直接商店街に出向いて、直接やりとりをして、ヒアリングをして得た商店街関係の情報と、それから、今の摘示をいただいたところ等も含めて。","voiceIndex":44,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、どこかから引用したとかもそうなのですけれども、区としての報告書なので、説明ができるようにということは求めていきたいと思います。そして、１６ページから、商店街のブロック別の状況というのが書かれています。なので、報告書として、期待されている反面、そういう声もあることは反映されないのかという、その辺はどうなのかということを伺わせてほしいのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"それで、新たな展開を図ることが期待されるというのは、直接的に商店街の存続を心配されている声を否定するものではなくて、現状のにぎわいを、先ほども申し上げましたけれども、うまくまちの魅力としてどういうふうにすればつなげていけるのだろうかということを。","voiceIndex":46,"id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"でも、もしかしたら書いていたかもしれないし、それがここに反映されていないと、自分たちがアンケートを書いたのにですとか、思いを伝えていてもこういうところには反映されないのかと思ってしまったりもするかと思うので、その辺の聞き取り等も、声としてはやはり多くの商店街の方たちは不安に思っている部分が結構あって、私たちのところにも届いているので。","respondent":"山崎商業・ものづくり課長","answer":"それをどちらかに答えを決めるとかということではなくて、それぞれの特性に応じたご意見ということで、区のほうではしっかり丁寧に拝聴してまいりたいと思ってあります。","voiceIndex":48,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認ですが、この調査の前に、中小企業を含めたこういう方々への支援についての調査を、報告をまとめたものまとめないものも含めてされていたかどうかという確認が１点と、今回のこの調査が、いわゆるこのレジュメでいきますと、大学のヒアリングは今年の２月でしたから、それ以外は約１年前に調査が終わっていると。","respondent":"山崎商業・ものづくり課長","answer":"それで、中小企業の製造業・情報通信業編ほうの冊子では７４ページに最終的な基本政策、「はぐくむ」「つなげる」「ひろげる」というようなことを先程ご説明申し上げましたけれども、私どもでは同じように、私どもといいますか、これは品川区でつくった調査結果ですが、途中では。","voiceIndex":50,"id":"exchange-022"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、一番最初に確認させていただいた、これまでの調査と今回のきちんとしたこの報告書、３カ月に１回、いわゆる調査を個別といいますか、角度をつけて調査をしてきたそのものがあって、今回これがあって、要するに、３カ月に１回、そうやって動向を見てきているわけですよね。これとその３カ月のとはどういうふうに見ていくのですか。これはどういうふうに見たらいいのですか。","respondent":"山崎商業・ものづくり課長","answer":"実は２年前に組織改正がございまして、ものづくり・経営支援課という、そこに私、おりましたけれども、中小企業の支援をメインに行っているところと、それからもう一つが、商店街施策の商業系と、その当時観光がそこにありましたので。","voiceIndex":52,"id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、これからも３カ月に１回の調査もしつつ、これを網羅的に、個別にもお聞きしましたし、アンケートもやってきた、これをベースにして今後していくという理解で良いのかというのが１点と、それから、先ほどおっしゃった、この調査をもとに、確かに平成２９年度、後継者支援ですとか、それから。","respondent":"山崎商業・ものづくり課長","answer":"２点目につきましても、さまざまなところでこうした時代の変化が産業系、速い時代ですので、しっかり情報を把握して、やはり一番大切なのは、中小企業、商店街の皆さんの活力を高めることに資することは何なのかということですので、最適をしっかり考えてまいりたいと思います。","voiceIndex":54,"id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"確認","question":"お伺いしたいのが、表現が最終報告書なのです。ですので、どちらのものを品川区は政策の方向としてとっていくのかという確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"少し配慮をさせていただいて、記載をさせていただければと率直に思っておりますが、そうした意味合いで捉えていただきたくよろしくご理解を賜りたいと思います。","voiceIndex":57,"id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"質問しにくいですけれども、この表現が最終報告書なのです。だから、やはりそこの施策の整合性というのは、横串とよく言うのですけれども、縦割りではなくて横串の中で品川区がどう取り組んでいくのかというのをしっかり見詰めていかないと、こういうことになるわけです。だから、議会はそこを今指摘させていただいていますので、連携をとって進めていっていただきたいと思うのですが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"さまざま、やはりブロックごとの地域特性を適正、的確に、横串とおっしゃいましたけれども、まさにそのとおりで、しっかり努めてまいりたいと考えています。","voiceIndex":59,"id":"exchange-026"}]},{"id":"topic-03","title":"総合体育館非構造部材他耐震化工事","agenda":"総合体育館非構造部材他耐震化工事","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ。補完避難所機能の強化、大事なテーマだと思います。便所排水管耐震化工事ということですけれども、要するにどういう工事になるのか。これが実施されると、災害時に避難をされた方がどういうふうに何が改善されるのか、そこをご説明いただけますでしょうか。","respondent":"池田スポーツ推進課長","answer":"そういったものを、大きな地震が来たとしても、排水がきちんとできるように、耐震化工事です。","voiceIndex":66,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"つなぎ目だったり、ずれが生じないため、要するに、下水道管の耐震化という趣旨なのでしょうか。補完避難所機能の強化ということですから、大震災を想定した際にどういうふうにこれが使えるようになるのか、それともまだ使えない条件があるのか、そこを伺いたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"もともとこちらの体育館のトイレですけれども、水につきましては雨水を使っているところでございまして、今回については水ということでは雨水タンクのほうでやりますので、特段は工事はしませんけれども、ただ、排水の部分につきまして。","voiceIndex":68,"id":"exchange-028"},{"speaker":"中塚委員","kind":"確認","question":"つまり、震災が発生した際の直後、いわゆる電気、ガス、水道のライフラインが途切れても、総合体育館の、補完避難所としてこのトイレは使えるということでよろしいのでしょうか。そこだけ最後、確認いたします。","respondent":"池田スポーツ推進課長","answer":"そのように使えるようにということでの今回の工事です。","voiceIndex":70,"id":"exchange-029"},{"speaker":"本多委員","kind":"質問","question":"工事の必要性については理解できますので、ぜひよろしくお願いします。それで、武道場と卓球・レクリエーション室の代替えについて、何か工夫とかあれば、その辺、教えてください。","respondent":"池田スポーツ推進課長","answer":"そちらのほうでも若干まだ余裕はありますけれども、特に私どもといたしましては、現在、総合体育館を利用されている方に対して、そこを優先的に利用していただくというようなことは考えていないところです。","voiceIndex":72,"id":"exchange-030"},{"speaker":"本多委員","kind":"質問","question":"わかりました。それと、アリーナなのですけれども、オリンピック・パラリンピックに向けてバスケットゴールについて規格に合ったものを設置するに当たって、構造的にすごく重量ですとか荷重がかかることによって、配慮しなければいけない部分が出てくるかと思うのですが、その辺というのは、今回の工事とかに活かされるのでしょうか。","respondent":"池田スポーツ推進課長","answer":"床につきましては、先日、前にバスケットのゴールの重みに耐えられないということが若干ニュースになったかと思いますけれども、こちらのほうについての工事というのは特に行わない予定でございまして、床につきましては。","voiceIndex":74,"id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"説明方はわかりましたけれども、オリンピック・パラリンピックに向けてそれでいいのですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、それはあくまでも立候補ファイル上ということでございまして、その後、大会組織委員会のほうで全体の練習会場の見直しを行いまして、品川区の総合体育館に関しましては、国体の実績を踏まえまして、ハンドボール競技の練習会場ということで、今、検討をしています。","voiceIndex":76,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"基本的なことをお伺いしますが、この文章では「便所」となっているのに、課長の説明では「トイレ」を使うではないですか。その辺も、この間、予特でもちょっと伺ったのですけれども、はっきりこの委員会でどちらを言葉的に言えばいいのか教えていただきたいのが１点と、それと、便所に関してなのですけれども、耐震化というのはわかるのですけれども、それだけではないですよね。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"次の便所の便器についてですけれども、１階から地下２階まで、男性用便所は男性用の便座、女性用の便所につきましては女性用の便座、こちらのほうにそれぞれシャワーつきの温水が出るもの。区といたしましては、積極的にぜひ協力したいと考えているところです。","voiceIndex":78,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"ビーチバレー、もうちょっと顔のはめるところを大きくしていただければ自分も顔が入るのにと思いつつなのですけれども、あの肝いりのすばらしいパネルがもうなくなってしまったのですけれども、部を挙げてやっていたわけですから、最後にどうなって、ビーチバレーに関してはあまり気持ちが入っていないのか、これで最後の質問にしますので、そこだけははっきり答弁していただきたいのですけれども。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ああいったことをきっかけに、あれだけではなく、ビーチバレー、また、ホッケーについても引き続き機運を醸成していきたいと考えていますので、あちらは今、食堂のところからは取り外しましたけれども。","voiceIndex":81,"id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"１点だけ。これは歌とか振りつけとか、全部でき上がっているのですか。それとも、１８日に向けて、今、いろいろ音楽の調整とかをしているのかどうなのかというのをお聞きします。できれば、１８日に初めてではなくて、どういう音楽か最初に聞きたいです。はどういう体操かというのを、区民委員会最後ですので。","respondent":"池田スポーツ推進課長","answer":"お帰りの際には、多分、そのころにはＣＤとかＤＶＤも完成する予定ですので、完成した暁には、参加していただいた方についてはお持ちになっていただければということも考えてありますので、よろしくお願いいたします。","voiceIndex":87,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36599,"voices":92}},{"id":"h29-20170515-7","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"厚生委員会","time":"午後 １時００分～午後 ３時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「支え愛・ほっとステーション」の開設","agenda":"「支え愛・ほっとステーション」の開設","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"「支え愛・ほっとステーション」が全地域センターの１３カ所に開設ということになるということですけれども、これまでもかなり支援者であるボランティアの方を組織することが大変だというお話はあったのですけれども、平成２８年度新たに開設したところの支援者の状況がどのようになっていて、その対策というか対応をどうされてきたのかについてお聞かせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"ただ、そこで「ほっとサービス」ということで、ちょっとした困り事に対して、例えば粗大ごみだったり、あるいは電球の交換といったものをやってほしいというお声をいただくときには、それに対応する形でボランティアの方をお願いする。こういう事業をやっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ボランティアの方の組織というのもなかなか苦労するところなのかなという思いなのですけれども、様々やってほしいという要望、需要とのマッチングというところでは、ボランティアが足りなくて断るとか、できないとか、そういう事例はないのかとこの辺のばらつきの状況というのも、どうしてこんな状況なのかというところもお聞かせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"例えば、大きな家具を３階から１階までおろしたいなどのご相談を受けるケースもあります。そうなってしまいますと、やっていただくのはあくまで一般の方です。なかなか物理的に難しいといったことで、それは専門業者等にということでご案内をするケースがあると伺っております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこで、支え愛活動会議というのは、今どんな状況になっているのか。ワークショップとかも今後行う予定ということで言われていたと思うのですけれども、その支え愛活動会議のメンバーとワークショップの内容とか、そこら辺のところも教えていただけたらと思います。","respondent":"大串福祉計画課長","answer":"ワークショップは、昨年３地区で実施をさせていただきました。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤副委員長","kind":"質問","question":"今年度で全地区展開ということですけれども、「品川の福祉」のこれまでの実績というところで、訪問というところが随分と、例えば品川第二ですと、年々件数が大きく減っていたりするのですけれども、この理由は何なのでしょうか。その辺をもう少し聞かせてください。","respondent":"大串福祉計画課長","answer":"ただ、当然生活していく中で、先ほども言っておりますような日常生活上の何かお手伝いといったことが発生すれば、それは対応しています。決して「支え愛・ほっとステーション」のサービス事業から除外をしているということではありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"わかりました。ちょっとイレギュラーだったということでしょうか。もう１点は、品川区では今年度で全地区展開ということになりますけれども、これは全国に先駆けてという状況なのか、進んでいる自治体ということになるのでしょうか。そこら辺の品川区としての相対的な位置についてのご認識についてお伺いします。","respondent":"大串福祉計画課長","answer":"２点いただきました。１点目の在宅介護支援センターとのすみ分けといったところです。在宅介護支援センターが品川区で高齢者を支える一番大きな組織ということは変わりありません。","voiceIndex":14,"id":"exchange-005"}]},{"id":"topic-02","title":"「しながわっこのサポートブック」の作成","agenda":"「しながわっこのサポートブック」の作成","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、育成会の方に伺ったら、既に育成会では何年も前からこういう取り組みはされているということだったのですけれども、そういう団体とどういう調整をしていくということにより考えられているのかについてもお聞かせいただけたらと思います。","respondent":"中山障害者福祉課長","answer":"ですから、品川区もこれは第１版ということで、要約版と、より細かく書きたい人向けの細かいバージョンと、両方つくってはあるのですけれども、説明会を行い、実際に書き込んでいただく中で、ご意見を伺いながら、版を重ねていく必要があるかなとは思っています。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことを私も育成会の方からも伺ったのですけれども、書いていくことが非常に大変な作業になるので、実際に親が細かいところまで書いていくのは大変だというところでは、様々な勉強会を通して、それがどう役に立っていくのかという意義もわかれば、記入していくということにもつながっていくのかなと思うのです。","respondent":"中山障害者福祉課長","answer":"渡したときに、相手先がそれを有効に支援につなげていただかないと、何もならなくなってしまうわけなのですが、これを全てやろうと思うと、それぞれの保育園にしても学校にしても大変な負担かとは思うのですが、ここだけはなど、特にこういうことに注意してほしい内容を。","voiceIndex":22,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"個人情報が丸々全て、ここの中に網羅されるみたいな形になっていくので、これをコピーして学校なり保育園なりということで渡していくとなると、この取り扱いというのもすごく注意をすることが必要だと思うのですけれども、個人情報の取り扱いに留意するというところでは、保育園だったりとか学校だったりとか、これを取り扱うところに対しての、個人情報の取り扱いに対しての取り組みというのは。","respondent":"中山障害者福祉課長","answer":"例えば保育園ですとか学校でも、特別支援の個別支援計画書とかもありますので、そういったものとあわせて、個人情報の取り扱いについては十分留意してまいりたいと考えております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう方が使えるようにもなるのかどうか、そのことを最後にお聞かせください。","respondent":"中山障害者福祉課長","answer":"６月の品川児童学園の保護者向けの説明会をやった後に、区のホームページにもこちらは載せようと考えています。ですので、そのときにこのシートだけではなく、目的ですとか利用の方法といったところも、しっかり載せさせていただければと考えております。","voiceIndex":26,"id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"記憶が定かではないのですけれども、３年前だったか、私もそのとき厚生委員会に所属していて、視察でそういう障害を持つ子どもの、例えば品川で言えば小さいころは障害者福祉で、小学校になると今度は教育委員会でとなるように、しっかりとつなげるために、こういうものが必要だという議論が出て、ほかの自治体も視察をして、それで厚生委員会の中のほとんどの委員が。","respondent":"中山障害者福祉課長","answer":"クリアファイルに入れると冊子のイメージにはなるのですが、それぞれのシート１枚ごとのものになります。それを透明のクリアファイルの袋の中に差し込むようなイメージで、最終的にはサポートブックという形で考えております。","voiceIndex":30,"id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば、エクセルだったりワードだったりという形で、その時々のお子さんの様子は変わるのではないかなと思いますので、何度も書き直したりですとか、更新を常にできるような形で、もちろんクリアファイルでというところで記録として残しておくことも同じかと思うのですけれども、長く利用していくときに、そのときそのときで成長によって変わっていったり、更新も必要だと思いますので。","respondent":"中山障害者福祉課長","answer":"現在考えていたのは、ＰＤＦファイルでと思っていたのですが、確かに枠をちょっと広げたいところがあったり利用方法は、家庭ごとに違うかもしれませんので、そこは研究をさせていただければと思います。","voiceIndex":34,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"研究していただけるということで、ありがとうあります。今回は一番初めの段階ということで、ＰＤＦで配布をする中で様々なご意見をお聞きしていただいて、また今後利用者の声なども聞いていただきながら、使いやすいものに進化していっていただければと思います。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-012"},{"speaker":"安藤副委員長","kind":"質問","question":"順次導入を図っていくということなのですが、親がこのサポートブックに書き込んで、自分の子どもの特徴などや伝えたい情報を書いて、各支援機関に渡すということになると思うのですけれども、導入以前、導入後で大事なのが、情報を届けられた支援機関のほうだと思うのですけれども、そこがどれだけこのサポートブックということの意義をしっかり捉えるかということが大事になってくると思うのですが。","respondent":"中山障害者福祉課長","answer":"ただ、実際に活用するのは現場ということで、保育園であったり、学校であったりということになりますので、そこに対する説明、どういう意味をこれが持っていて、親御さんがどういう気持ちでこちらを持ってくるのかといったところも含めまして、関係機関への周知。","voiceIndex":38,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"サポートブックということで伺いました。学齢期ぐらいまでというふうにさっき伺いまして、それ以降についてはどのように考えられているのかをお伺いしたいと思います。年に関係なく、様々な障害を持たれている方とかはおられると思うので、福祉課でも利用できるのか、そのような考え方があるのかどうか、他課との連携も含めて可能性について教えていただければと思います。","respondent":"中山障害者福祉課長","answer":"この支援というのは学齢期で終わりということではもちろんなく、そこから社会生活につなげていくための支援のブックになってきますので、成人期をどういう形でケアプランに残していくかというのは、これからの課題と考えております。","voiceIndex":41,"id":"exchange-014"}]},{"id":"topic-03","title":"「グロー障害者相談支援センター」の開設","agenda":"「グロー障害者相談支援センター」の開設","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３カ所目の相談支援センターができるということですけれども、ここの職員の体制が、どういう資格の人が何人ぐらい配置になるのかということを教えてください。それから、所在地なのですけれども、楓ハイツ３階ということですが、この場所がよくわからないので、何かの施設の中というのではなくて、普通の事務所ビルみたいなところの３階というところになるのか、そのところも教えてください。","respondent":"中山障害者福祉課長","answer":"こちらの「グロー障害者相談支援センター」は、現在まだ指定特定相談が始まっていないので、今は２名体制なのですが、これから３名体制になります。","voiceIndex":48,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、福栄会と品川社会福祉協議会がやっている身障者会館のところで、それぞれ６人の体制と、区での２人の体制ということなのですけれども、実際にケアプランが立てられている件数として、何人くらいのケアプランが立てられているのか。","respondent":"中山障害者福祉課長","answer":"遠方の入所施設を除いては、大人のケアプランについてはほぼ立て終わった状況にはなっています。子どものケアプランがどうしても事業所で受けられないということで、区で進めている関係がありまして、こちらがまだ１００％にとても届かないような状況であるところになります。","voiceIndex":50,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"子どものケアプランがこれからももっと充実をさせていくというのが課題としてある。では、この「グロー相談支援センター」は、そういうところも受け持つことにより充実をされていくということになるのでしょうか。","respondent":"中山障害者福祉課長","answer":"平成３１年度になりますと新しい施設も完成しますので、そのときに児童のケアプランをどういう形でつくるのか、例えば児童学園で一本化するのがいいのか、それとも児から者へつなぐことを考えて、こうした３つの相談支援センターでも持つようにしたほうがいいのか。","voiceIndex":52,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ということは、「グロー障害者相談支援センター」というのは、今まで福栄会と身障者会館でやっていたのを、さらに３カ所で分担して、より充実をさせていくという形での相談支援センターということでいいのかということだけ、最後にお願いします。","respondent":"中山障害者福祉課長","answer":"そのとおりです。は大人の部分のケアプランを３拠点に分けて、しっかりとつくっていきたいと考えているところです。","voiceIndex":54,"id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問","question":"２番の事業内容のところの米印に、「地域生活支援拠点マネージャーを配置し、緊急時の受け入れ・対応等が行える体制を整備します」とあるのですけれども、この緊急時の受け入れ対応というのは何を指していらっしゃるのか、いわゆるショートステイみたいな宿泊可のイメージなのか、まずそこを教えてください。","respondent":"中山障害者福祉課長","answer":"ただ、ここの「グロー障害者相談支援センター」にはショートステイがあるわけではないので、ほかの福栄会と会館にある生活・相談支援センターと連携しながら、区内のショートステイの活用をしていくようなイメージです。","voiceIndex":57,"id":"exchange-019"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。では、先ほど聞いた限りではそんなに広くないようなイメージだったので、ここにというよりは、ここで相談を受けて、様々なあいている場所を見つけてくれて、調整するということですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-020"}]},{"id":"topic-04","title":"乳がん検診実施機関の拡大","agenda":"乳がん検診実施機関の拡大","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４カ所新たに増えるということですけれども、対象者に対しての受診率が２５.２％ということで、かなり高いなという思いがするのですけれども、さらに向上させたいということで、ご説明ありましたけれども、受診率をさらに何％まで上げたいという目標というのは、区として持っているのかということと、それから、４カ所新たに増やすことで。","respondent":"川島健康課長","answer":"乳がん検診の受診率の目標というのは、国は５０％と言っておりますが、区では具体的には数字としてお示しはしていないところですが、少しでも高い検診の受診率を目指して、毎回様々な取り組みをしているです。","voiceIndex":64,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成２８年度がどれぐらいかというのがわかったら教えてください。さらに増えているのでしょうか。","respondent":"川島健康課長","answer":"そうです。さらに増えておりまして、平成２８年度、まだ３月分の集計ができていないので、正確な数字というのはお答えはできないのですが、受診率の傾向的にも、こちらに書いてあるとおり、伸びが予想されると見込んです。","voiceIndex":66,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「品川の保健衛生」のところで見ると、受診者が平成２７年度は１万８０５人で、要観察が１,０２５人で、要精密検査が３９５人で、この数は結構な数だなと思ったのですけれども、この方たちに対しては、その結果がどうだったかというところのデータは、区としてはどうされているのか、わかったら教えてください。","respondent":"川島健康課長","answer":"精密検査を受けた方の情報につきましては、区に情報を提供していただくようにドクターにお願いをしまして、情報を収集しておりまして、アフターフォローといった部分もデータを積み上げているところです。","voiceIndex":68,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"乳がんがこの検診によってわかったとかということが、これだけあるという件数があると、また説得力があって、さらに検診に向かうという部分があるのかなと思うのですけれども、そこら辺がわかったら教えてください。","respondent":"川島健康課長","answer":"がんの発見数というところになるかと思いますが、平成２６年度から順に申しまして、２６年度が５１人、２７年度が５７人、２８年度は１月末現在ですが、２６人の方のがんが発見されていると把握しています。","voiceIndex":70,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"改めて、検診でこれだけがんが発見されてというところからすると、さらに受診率が向上されれば、もっと早期発見、早期治療で、人生にとっても大きなマイナスにならなくて済むというところにもつながるかと思いますので、引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"裏面の医療機関のところで、みなと健診クリニックというのが港区にありますけれども、港南なので比較的近いところだと思うのですが、こういう品川区ではないところでも、場合によっては例えば大田区や目黒区などでも、近いところであれば今後拡大していくことも検討されるのでしょうか。","respondent":"川島健康課長","answer":"乳がん検診の医療機関につきましては、今ご指摘のところもそうなのですが、区内だけではないというところがありまして、これは当初、受診者数が以前非常に伸びたときがあったので、利便性も考えて、近隣区でというところで契約したという事情があるようですけれども。","voiceIndex":74,"id":"exchange-026"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。４つ増やしていただいて、しかも土曜日ということで、本当に頑張っていただいていると思うのですけれども、さらに、もしそういう必要性があれば、ぜひ区を越えてでもお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-027"}]},{"id":"topic-05","title":"胃がんリスク検診の判定基準の変更","agenda":"胃がんリスク検診の判定基準の変更","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"この中で、過去感染の方、かかっていたけれども除菌したという方は、除菌しておりますので問題があるのでしょうか。その方にもまた内視鏡を受けなさいという案内が行くのでしょうか。","respondent":"川島健康課長","answer":"今、委員のご指摘の、過去に感染して除菌済みの方というのは、がんになりやすいリスクがある方に分類されるということで、もとから感染がなかった方とは別の扱いになるということから、経過観察が必要になるというところなので、十分に問診をとれば。","voiceIndex":81,"id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問","question":"１回やっていれば受ける必要はないのだけれども、忘れて受けたと。だけれども、除菌されているわけだから、我々のイメージだと、胃がんの大体の原因が、ほとんど九十何％がピロリ菌だと。私自身が除菌したものですから、それは個人的なことだからいいのだけれども、区の検査で５０歳のときにやったので除菌したのですが、イメージがちょっと違ったのですけれども、そこはどうなのでしょうか。","respondent":"川島健康課長","answer":"若年のうち、例えば高校生だと早過ぎるとは思うのですけれども、もし感染している方が除菌した方というのは、かなりリスクが低くなるという報告がありますが、ある程度の年齢に達して、５０代ということだと、大体８割ぐらいの方が感染していると言われているのですけれども。","voiceIndex":83,"id":"exchange-029"},{"speaker":"浅野委員","kind":"質問","question":"今回このような発表があって、私もついこの間、検査をして除菌をしたことがありまして、内視鏡の検査もしましたけれども、該当するかどうかは秋ぐらいにわかるということですので、その結果を見て判断したいと思います。そこら辺を含めて、考え方を教えてください。","respondent":"川島健康課長","answer":"今ご説明しました数値に当たる方ということになりますと、医療機関の扱いによっても変わってくるとは思うのですが、医療保険の範疇になるということで、内視鏡の検査を受けた場合。","voiceIndex":86,"id":"exchange-030"}]},{"id":"topic-06","title":"一般不妊治療医療費助成制度の変更","agenda":"一般不妊治療医療費助成制度の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"不妊治療には非常に高額な費用がかかると思うのですけれども、品川区は１人当たり年間１０万円が限度ということだと思うのですが、大体１人平均で、不妊治療に幾らぐらいかかっているのかを教えていただきたいと思います。","respondent":"川島健康課長","answer":"正確な数字は今すぐは出てこないのですが、年々助成している金額も、助成単価というのでしょうか、上がってきて、１人１０万円の半額を助成するということなので、最大でも５万円ということなのですが、品川区の場合、５年度通算して助成するという形になっております。","voiceIndex":92,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２３区の中でも、多分もっと助成額が多い区もあります。都の助成に加えて追加支給を行っている区もあるというのも書かれていたのですけれども、他区の状況もわかったら教えていただきたいと思います。","respondent":"川島健康課長","answer":"一般不妊治療の助成をしている区は、品川区のみということです。２３区のうちだと１０区が特定不妊治療、これは国の定めたものを都道府県が実施しているのですけれども、それに上乗せをして助成しているところが１０区というところになっております。","voiceIndex":94,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、品川区が行っている一般不妊治療の保険のきかない本人の自己負担というのは、おおよそ年間２０万円くらいで済むということでいいのですか。","respondent":"川島健康課長","answer":"一応、自己負担の半分ということで、助成しているのが例えば５万円ぐらいですので、それを倍すれば、１０万円ぐらいを本人が負担されているのだろうなとは推測しています。","voiceIndex":98,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません。ということは、一般不妊治療が東京都で助成をされるということになれば、それでおおよそ足りてしまうという考え方で、品川区の制度か東京都かということで、上乗せをする必要はないという考え方ということですか。","respondent":"川島健康課長","answer":"東京都がどういう補助の仕組みをしくかというのが、先ほど資料に書いてある部分のみしか私どもも把握はできていないので、これが区の制度にかわるものなのか、それから、今後例えば予算額がまた増やされていくのかとかということも含めて。","voiceIndex":100,"id":"exchange-034"},{"speaker":"安藤副委員長","kind":"質問","question":"ホームページを見ましたら、昨年度より年齢要件を設けたということで、妻の年齢が４３歳までにということなのですが、子どもを授かりたいなと思って悩んでいる方というのは、４３歳以上の方も結構いると思うし、より深刻なのかなと思うのですけれども、そちらが変更になった理由、年齢要件が設けられた理由というのと、年齢要件を超えている方でも切実な方というのはいらっしゃると思うのですけれども。","respondent":"川島健康課長","answer":"区の制度が特定不妊治療に入る前の入り口の段階ということなので、国の年齢制限よりも上というのも、考え方としては少しおかしいのかなという気もしないでもないのですけれども、様々な考え方、様々な需要もあると思いますので。","voiceIndex":103,"id":"exchange-035"},{"speaker":"安藤副委員長","kind":"質問","question":"こういった年齢要件が設けられたということなのですけれども、そういった年齢要件で、妻の年齢が４３歳以上の方々からの相談とか、受けたいのですけれどもという問い合わせですとか、そういった状況がわかれば、あるのかないのか、どういった実態なのか、わかる範囲でいいので教えてください。","respondent":"川島健康課長","answer":"現実に何件かそういったご相談というのはあるのですけれども、実際問題、国の制度の入り口部分を担うところというところもありますので、こちらは年齢制限というのを設けさせていただいたという考え方は、変わるというところではございません。","voiceIndex":105,"id":"exchange-036"}]},{"id":"topic-07","title":"予防接種の接種方法に誤りがあったことへの対応","agenda":"予防接種の接種方法に誤りがあったことへの対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのような方に対して、カルテの保存は５年分ということになっていますけれども、５年以前のものはクリニックにはないのか、５年過ぎても何らかの形でとっているのではないかなと思うのですけれども、そういうことであるのであれば、その人たちにもきちんとお知らせするというのが必要なのではないかなと思うのですが、そこら辺の可能性はないのでしょうかということをお聞かせいただきたいと思います。","respondent":"舟木保健予防課長","answer":"最後の３つ目の自己負担についてですが、品川区では、おたふくかぜについては確かに任意の予防接種ということで、自己負担が生じる接種だったと思うのですが、今回のことに伴う再接種費用につきましては、定期・任意とも無料で実施する方向です。","voiceIndex":111,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２４年３月以前のものというのは、クリニックにはカルテは残っていないということで、情報として得られないということなのでしょうか。","respondent":"舟木保健予防課長","answer":"平成２４年以前のカルテに残っていないかどうかですが、カルテの保存年限が最初の記載から５年間となっているので、場合によっては確かに残っている可能性もありますが、今回の確認作業ではそこまではしておりません。","voiceIndex":113,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区でのカルテの保存期間が５年間というところで、５年間だけを調査したということですけれども、ワクチンの抗体価というところで言えば、それ以前にやった人にも影響してくるということなので、本来であれば、クリニックにカルテが残っているのであれば、区もカルテそのものを、多分クリニックにおいてもカルテというのは、５年間保存というのは法律で決められているので必ずありますけれども。","respondent":"舟木保健予防課長","answer":"そういう意味では、区に請求があってということで、こちらが把握できる５年間を調査して、その方に対して通知するという形で今回はいたしました。なので、そのほかのお申し出については、きちんと確認した上で、丁寧に対応させていただきたいと思います。","voiceIndex":115,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうことであれば仕方がないのかと思うのですけれども、親にとってみれば予防接種は、きちんとやったと思っていたら、それも実際やってみないとわからない部分はあると思うのですけれども、実はそういうことだったとなると、その後の子どもの感染とかにも影響する部分でもありますので、プレスでも発表し、ホームページでも出すということですけれども、そういう点では。","respondent":"舟木保健予防課長","answer":"ただ、閉院して、問い合わせ等がきちんとその後も継続してできるように、こちらからは確認先とかについては提出を求めているところです。","voiceIndex":117,"id":"exchange-040"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういったことになると、プレスの仕方も当然区として、そういうところに委託し、接種方法に誤りがあったというおわびも当然あると思うので、どんな感じのニュアンスでプレスを発表するでしょうか。それから、品川区予防接種事故調査委員会のメンバー構成を教えていただきたいと思います。","respondent":"舟木保健予防課長","answer":"Ｈｉｂの抗体検査については、実施体制が国内では整っていないということでできないため、希望者には再接種という形での対応ということで、Ｈｉｂの再接種について予防接種事故調査委員会の中で検討した上で決めていることでして、再接種の回数がそのほかの４種混合に比べまして。","voiceIndex":119,"id":"exchange-041"},{"speaker":"たけうち委員","kind":"質問","question":"Ｈｉｂのほうは、医療の専門家ではないのでわかりませんけれども、仮に抗体があったとしても、もう１回打っても大丈夫、健康被害はないということなのですね。そうでないと、あるかないか検査しないで、わからないのに、１回でいいと言われているのにもう一回打ってしまって、何か副作用があると心配なので、そこだけ大丈夫だということを教えていただければと思います。その辺はどうなのでしょうか。","respondent":"舟木保健予防課長","answer":"今後費用請求などを考えていくのかということですが、現在のところは当面、取り急ぎの対応として、区民への健康被害の確認、またその対応ということでやらせていただいています。費用的な面については、今後改めて専門家を交えて検討していくこととなっております。","voiceIndex":121,"id":"exchange-042"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは幾つかなのですが、このケルビムこどもクリニックで複数のワクチン液をまぜて接種したということは、いつごろからまぜてワクチンを打たれたのかというのを聞きたいなというのがあります。もう一つが、先ほども効果があるかないかというお話だったのですけれども、悪影響はないのか、ちょっと不安だったのでお聞かせいただきたいと思います。","respondent":"舟木保健予防課長","answer":"ただ、全くついていないわけではないとは思いますし、かといって、きちんとついているとも言えない状況なので、様々予防接種事故調査委員会の中で議論した結果、このような対応となっております。","voiceIndex":124,"id":"exchange-043"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"複数のワクチンをまぜて接種することの子どもへのリスクというところは、できるはずの抗体ができないというだけにとどまるのか、わからないということなのか、そこら辺をもう少しご答弁いただきたいというのが１点です。多くの通園幼児が利用していたのではないかと想像するのですけれども、そういった保育課などの所管との連携や情報共有などはどのようになっているのでしょうか。","respondent":"舟木保健予防課長","answer":"抗体がついているかどうかについては、希望者の方には抗体検査を実施するという中で検証するとともに専門の先生方と検討しながら判断してまいりたいと思います。","voiceIndex":127,"id":"exchange-044"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"これは要望したいのですが、いかがでしょうか。何もリアクションがない方に対して文書を再交付するなども含めて、なるべく現時点で区がつかんでいる方々に対しての周知という点では、もっと工夫が必要なのではないかなというのが１点です。そういった形で最大限努力をしていただきたいのですけれども、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"教育部門とも連携して、周知についてはこちらから情報提供して、どのようにしたらいいのか相談しながらやっていきたいと思います。","voiceIndex":129,"id":"exchange-045"},{"speaker":"安藤副委員長","kind":"質問","question":"ですから、そんなに大きな労力はかからずご家庭に周知できると思いますので、ぜひよろしくお願いしたいと思います。それと、意向調査の締め切りのことですが、とはいってもその期間以降、５月末を過ぎて、そうした連絡が来る方もいると思うのですが、そちらの希望申請というのは当然受け付けるということでよろしいのでしょうか。ぜひそうしてほしいのですが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"確かに５月３０日までに出してくださいという形で書かせていただいておりますが、その後もこちらで調整して、ご発送したり準備している間にも届く可能性等は、もちろん重々承知しています。ここにもできる限り可能な範囲で対応させていただきたいと思います。","voiceIndex":131,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3476#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":39617,"voices":136}},{"id":"h29-20170515-8","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"建設委員会","time":"午後 １時００分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年６月区民住宅（空き室）入居予定者登録募集","agenda":"平成２９年６月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"西本委員","kind":"質問","question":"区民住宅の現在の空き状況がどうなっているのかと、いずれ、区民住宅というのは変わっていくと思うのですけれども、それの告知というものはどういう方法を行って、理解をしていただきながらお申し込みをしていただくことになると思うのですが、それはどういう方法を使われるのですか。","respondent":"長尾住宅課長","answer":"告知につきましては、これから入る入居者ということでいいますと、抽選結果の通知を送りまして、通知をもちまして、あっ旋を受けられる予定の方にはお知らせをしまして、その後、空き室が出た段階で皆様に入居審査のための資料をご提出いただきます。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"５０カ所ということなのですが、この内訳はわかりますか。どこがどのぐらいか。それと、要は、区民住宅の制度が変わっているわけです。いずれは区民住宅がなくなってくるわけではないですか。そういう部分も含めて考えたときに、種類が変わるかと思うのですけれども、それは理解していただいて、入っていただく形になると思うのです。それをどう説明されているのかということです。","respondent":"長尾住宅課長","answer":"借上型住宅についての今後の予定の周知とあわせて入居募集のお話ということですけれども、登録募集のしおりの中で各住宅につきまして返還予定時期を記載しており、その中で周知を図っております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"意見","question":"周知の方法ですけれども、いずれはそうなるという話の中で、借りる側にしてみれば、家賃の変動というのが一番気になるところだと思うのです。今はこれかもしれないけれども、公から返還になったときには、もう決まっているのであれば、変更した際にはこうなってくるということをお知らせする必要があるかと思うのです。そこはどう対処しますか。","respondent":"長尾住宅課長","answer":"こちらも、登録募集のしおりの中で記載しておりますので、そちらをご確認いただきながら、あとは窓口等で申込みに際しては書き方のご案内等もしておりますので、そのときにあわせてご認識いただくようにご案内することになっております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、申込みされている方が、そういうのを知った上で、納得した形で借りていただきたいのです。できれば、あと何年間は区の制度だけれども、あと何年後についてはこうなってくるというのを、きちんと将来にわたって言ってあげないと、急に言われてもということになってしまうので、そこは工夫して、細かく対応していただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"中延二丁目旧同潤会地区防災街区整備事業に伴う建設工事","agenda":"中延二丁目旧同潤会地区防災街区整備事業に伴う建設工事","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先日も、住民の皆さんから説明会の状況を私も伺いまして、やはりまだまだ住民の皆さんからは要望があるなと感じているので、そこを何点か伺いたいと思うのです。こういうことで、前回も全く同じ説明会だったので、字の大きさや、パワーポイントの資料を配ってほしいということを言ったら、後からきちんと配られた。ですので、こういったところをどのように感じられているのかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"今、委員ご指摘のありました工事説明会についてなのですが、先週、５月１２日（金）１９時から荏原文化センターにて、５３名の出席のもと開催されたと、区でも報告を受けております。","voiceIndex":16,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区としても残念に思っているということでした。そういうことを要望すると、誰がどう結ぶのかわからない、こういった回答が返ってくる。そして、この粉じんも本当に飛び散るので、もっと水の量を増やしてほしいという声も出ているのですけれども、こういった騒音、振動、粉じんに関しての住民の声に対しては、区としては、一緒に住民の声を受けとめるという立場で進めていく考えはあるのでしょうか。","respondent":"高梨木密整備推進課長","answer":"家屋調査についてなのですが、説明会の中で、どうしても影響がある１列目のみの実施というところで説明があったということで、私どもも聞いております。５列目の方々までは、どうしても家屋調査というのは難しいという説明が組合からあったということも把握しております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"家屋調査に関しては、要望があれば、何列目であろうが対応していただけないのかと思うのです。ここは真摯にというのであれば、ぜひ進めていただきたいと思います。ですので、仕事のサイクルの関係で、この解体工事の時間に寝るという方もいるので、そういった柔軟な対応をしていただけたらと思うのですけれども、事業者、組合は柔軟な対応をしていただけるのかどうかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"解体工事に伴う家屋調査および振動、騒音が激しい場合の一時仮住まい、ホテルの借上げ、２つとも補償に関するお話だと思います。この事業は、先ほどご説明させていただきましたとおり、事業組合が事業者として進めている事業でございまして、区が実施する事業ではございません。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、最後に、解体にあたって、アスベストの心配の声もあって、そこはきちんと対策を打っていくと環境課からも前回の委員会のときにお話しいただいたのですけれども、アスベストをこういうふうに対策して取り壊したという説明がなかったそうなので、どうやったのかを伺いたいと思うのです。ですので、そういったアスベストの関係での解体がどのように進んだのかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"アスベストにつきましては、解体工事を行う前に、どの程度含まれているかというような事前の調査を行いまして、全８６棟中、アスベストが建材に含有されている家屋が７７棟だったという報告を受けております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そのときの説明会資料はしっかり区も、リハーサルにも協力していたということですので、引き続きやっていただきたいですし、協定書、あと騒音、振動、粉じんの家屋調査の部分、仮住まいの部分、そして、このアスベストの部分、今お話しさせていただいたのは本当に一部ですけれども、住民の思いに応えるように、ぜひ区も協力し、そして入っていっていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"今回の説明会で、先ほど答弁で、区としても残念な思いがあるということでございました。そういう中で今回、組合側、具体的には設計事務所になるのか、そういう対応に終始してしまったということについて、もちろん指導はしていただくということはあると思うのですけれども、その辺の原因をもう少し詳しくご説明していただきたいと思います。それでこういう結果になってしまったという。","respondent":"高梨木密整備推進課長","answer":"今、塚本委員からご指摘のありました、繰り返しの指摘を受けてしまった事項についてなのですが、前回の解体工事のときに、説明の仕方であるとか、資料であるとか、中身に入る前の基本的な事項のところで非常に指摘を受けたところで、今回もそういうことがないように。","voiceIndex":25,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここの段階でしっかりと事業者側に改めていただいて、できることは対応していただきたいと思いますので、その点はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"基本的なことの確認になるのですけれども、建設工事の発注は整備事業組合になるのですが、この総額と企業負担はどうなっていたのですか。その辺の基本的な事項を確認させてください。","respondent":"高梨木密整備推進課長","answer":"費用負担につきましては、今回ご紹介しています建築物本体に関する事業費総額が約６２億円です。これは解体工事を含みません。そのうち、国と区から拠出されます補助金が約２４億円となっております。なお、その２４億円のうち、区の負担は約６億円です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然、事業者が建て替えるのはわかるのだけれども、戸数が１９５戸で、もともとの権利者が何人か、控え損なってしまったのだけれども、建設によってできたものは所有権になるのか。所有権を売却する形になるのか。そこら辺をもう一回、教えてください。","respondent":"高梨木密整備推進課長","answer":"従前お住まいになられていたり、土地、建物を所有されていた方々がそちらに権利を変換してお住まいになるのが、１９５戸のうち７２戸です。残りの１２３戸につきましては、売却し、その金額を事業費に充てていく、そのようなことで報告を受けております。","voiceIndex":32,"id":"exchange-013"}]},{"id":"topic-03","title":"がけ・擁壁安全化支援事業の実施","agenda":"がけ・擁壁安全化支援事業の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この助成金は、区の独自のものでしょうか。支援事業を実施することで、こういったがけや擁壁の安全化をどれだけ進めようと思っているのか。目標は何かあるのかを伺いたいと思います。","respondent":"鈴木建築課長","answer":"先ほどご説明した４３カ所程度、急傾斜地崩壊危険箇所、まずはこれらの安全化に向けて事業を進めてまいりたいというものです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、助成の内訳、国費も入るということですけれども、区の負担としてはどうなるのかを伺いたい。先ほどの調査結果のところで、安全性が低いところには直接こういった事業を周知するということだったのですが、もうそれはやられているのか。その母数、これだけあって、これだけ進めたいというものを伺えたらと思うのですけれども、そういうものはあるのかどうか伺いたいと思います。","respondent":"鈴木建築課長","answer":"擁壁の最終的な母数の目標ですが、先ほど道路沿いの大谷石は２１０カ所程度というご説明を差し上げましたが、その２１０カ所の中には、大谷石の状態が良ければ、目視の状態では比較的状態がいいという調査結果が出ているものもあります。","voiceIndex":40,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これからお知らせしていくということなのですが、直接訪問もされるのか。訪問される方は区の方なのか。それからあと、支援１のアドバイザーの派遣のところでは、そうやって直接訪問なりお知らせをして、こういった事業があるというのをお知らせしていくと思うのですけれども、こちらのお宅はアドバイザー派遣を受けたほうがいいと、こちらからそういう投げかけなどはするのでしょうか。","respondent":"鈴木建築課長","answer":"その４３カ所の個々の状態を見て、こちらについては職員が直接、所有者のところに行って、事業説明あるいはアドバイザーの派遣等について働きかけを行っていきたいです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これはがけ・擁壁の調査ということで、区としても以前からこの調査をしていると思うのです。例えば区政協力委員会の会議のときとか、町会長とかに、荏原地区なら荏原地区、大井地区なら大井地区の、そういった対象地域は、こういうところが危ないといった周知というのは、今現在やられたのか、これからそういった周知をしていくのか、それをお知らせいただきたいと思います。","respondent":"鈴木建築課長","answer":"調査にあたって、一昨年から２カ年をかけて調査してまいりましたが、その際、各町会には、こういった調査が入ると、コンサルの職員が地域を回るというご説明はしてまいりました。","voiceIndex":44,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"地域の町会の対象地域というのは、その地区の町会の住民の人とか、あるいは町会長とかが見て、ここは危険度が高いというところはわかっておられる人もいると思うのです。危険度が高い地域というのは一般の区民にも非常に重要なことだと思うので、もっと見やすくこれからアップしていくのかどうか、お知らせいただきたいと思います。","respondent":"鈴木建築課長","answer":"やはり擁壁の安全性は、最終的には個人の資産が安全か、安全ではないか、そういったところにまで踏み込んでいく話ですので、調査自体が目視で行っていて、最終的には、例えば超音波だとか、内部に踏み込まないと最終的に安全かどうかという確認もできないところがありますので。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは逆に、地域の方がこれを見たときになお心配に、今までも心配されているのですけれども、また話が出てくるのではないか。相手はＪＲですけれども、この辺は区としてどう考えていったらいいのかがちょっと気になった。もちろん、それぞれの地域、安全性を守るためには重要な部分だけれども、ここはかなり続いて、人通りも多いし、本当に線路の向かい側ですね。何か考え方があったら教えてください。","respondent":"中村都市計画課長","answer":"このＪＲのほうは、都市計画課でもかねてから危険性についてはお知らせをしておりまして、ＪＲも十分認識をしています。","voiceIndex":48,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もちろん先方もそれなりにきちんとやっているのでしょうけれども、これを見たときに、かなりそういう話が出てくるのではないかというのは、自分も見た瞬間に色がつながっていると、気になっていたもので。先ほど言ったように、普段からあの辺の道はどうにかならないかというのはよく言われている話なので、今後とも折衝を、安全性を守っていくために、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-020"},{"speaker":"西本委員","kind":"意見","question":"ですので、そこの交通整理というのをどうしていくのか。あくまでも品川区が、助成金があるからそこはやると言うのか、あとは、個人の持ち物なので、いろいろな業者が話をして、どうも助成金があるようだからそれを使ってやりませんかみたいな話も当然出ると思うのですけれども、その辺の調整はどう考えていますか。","respondent":"鈴木建築課長","answer":"擁壁の安全化について、これまでも、いろいろな区内事業者あるいは区外の事業者も、これもいろいろな機会を捉えてだと思うのですけれども、私、いろいろ伺う中で、擁壁だけを安全化にしましょうと言って回っている業者というのはなかなか今はいないような状況でして、通常。","voiceIndex":51,"id":"exchange-021"},{"speaker":"西本委員","kind":"意見","question":"いろいろ考えている方もいらっしゃると思うし、区内業者、区外もあるかもしれませんけれども、いい関係をつくりながら、悪用されないような状況。いろいろ出てきて、それから対処するということになると思うのですが、うまくつき合って進めていただけたらと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"今までの質疑の中で聞き漏らしたかもしれないのですけれども、がけ・擁壁の安全性に関する分布図に出ているところで、急傾斜地崩壊危険度の対象にもなっている、その中の範囲ということだと思うのですが、急傾斜地の崩壊危険箇所の中で、この緑や赤がついていないところはあるのですか。","respondent":"鈴木建築課長","answer":"４３カ所の中に、ついていないところは１９カ所あります。","voiceIndex":54,"id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"そういうのは、どういう考え方なのか、ちょっと説明していただけますか。","respondent":"鈴木建築課長","answer":"ですので、何度かこの場でもご説明しましたけれども、東京都が昨年と今年度で、４３カ所にプラスアルファをして、土砂災害の警戒区域を指定する調査を今進めてありますので、その辺で、この４３カ所が新たに消されるところ。","voiceIndex":56,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"道路・公共施設に面しているところがやはり３分の１で上限２００万円ということで、大体１,５００万円ぐらいのところを見ていると思うのですけれども、ちょっと私の感覚としては、それぐらいでできてしまうのかという気もしたのですが、実際、急傾斜地危険箇所、今、赤や緑がついているところで、大体。","respondent":"鈴木建築課長","answer":"この助成金額を設定するにあたって、いろいろ一般的な積算と、それから何カ所かシミュレーションをやってみて、出しておりますが、４３カ所、相当な数、現地を回って、どれだけこの３分の１の助成でできるかという詳細は把握してございません。","voiceIndex":58,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうところでいきますと、今後、訪問とかをしながら助成金額を説明する中で、そういった実際の工事をしたほうがいいのではないかという話になったときに、費用の話というのは当然、一番問題になってくると思うのですが、この助成以外にも、何かいろいろなところでそういう支援とかは、どんなことが考えられるのか。もしあれば、お聞かせいただきたいと思います。","respondent":"鈴木建築課長","answer":"今後、直接的にいろいろな声を聞きながら、その後の検討策は考えていきたいと、事業の進捗を見ながら考えていきたいです。","voiceIndex":60,"id":"exchange-026"}]},{"id":"topic-04","title":"コンクリートブロック塀の安全点検","agenda":"コンクリートブロック塀の安全点検","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"今、この点検をした上で、いろいろ危険だとなったときに、助成制度等のご案内をされるということです。助成制度にはどういうものがメニューとしてあるのかを教えてください。","respondent":"鈴木建築課長、高梨木密整備推進課長","answer":"それからあと、建築課で所管しております災害の拡幅整備事業の中、道路を広げながらブロック塀の除却についての助成を行っているところです。ただ、不燃化特区の区域内であるとか家屋の建築年という制限がありますので、その制限に合致するかどうか、そこら辺につきましては建築課と情報交換しながら。","voiceIndex":66,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"こういう基準に沿ったブロック塀を新たにつくると、これはもう、例えば震度７でも大丈夫みたいな、そういう感じになるものなのですか。聞きたいのは、壊した後、こういう基準にのっとった、きちっとしたブロックをまたつくるのと、それから、緑化で垣根にするのと、防災上、どちらが望ましいかみたいなことがあるのかどうか、そこをお伺いしたいと思います。","respondent":"溝口公園課長、鈴木建築課長","answer":"防災緑化助成制度の考え方です。これにつきましては、これまでも震災等によって、ブロック塀の倒壊、そういったものがありました。ただ、いろいろな考え方、プライバシーですとか防犯上のこともございまして、一方で、国の法律で定められたものがありますので、いろいろご説明しながら、お使いいただけるものを使っていただければと考えております。","voiceIndex":69,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も、こういったブロック塀、あそこら辺は危険だと思い浮かぶ地域もあるのですけれども、昨年から今年にかけて、ブロック塀を安全化する、そういった対処をした件数はわかりますか。なかなか進みづらいものなのか、結構皆さんもう問題意識を持たれているのか。持たれていないから、こういった安全点検で、自分で知りましょうとなっているのかとも思うのですけれども、件数を伺いたいと思います。","respondent":"鈴木建築課長、溝口公園課長","answer":"細街路が対象となる非常に細い道、ブロック塀が多いのですけれども、その細街路の助成の中で、ブロック塀の助成を使っていただいた件数でいいますと、平成２６年が８６件、平成２７年が４８件という数字が出てあります。延長としましては、大体５０ｍほどのブロック塀が撤去されて、生垣に変わっているという実績が出ているものです。","voiceIndex":72,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"意見","question":"自分自身で知るというのはすごく大事だと思うのですけれども、この点検シート、ブロック塀をお持ちのお宅に配っていくのがいいのではないかと思うのですが、この周知方法はどのようになりますか。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、いかにブロック塀の所有者に直接届けるかというところは大事ですが、やはりマンパワー的なところもありますので、これ専用に個別に調査をかけて配るということは今のところ考えてございませんが、木密ですとか、あるいは。","voiceIndex":75,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"この説明が14)までありますけれども、説明をしている部分もあれば、危険だという部分もあれば、何かバラバラなのです。ですので、目的をきっちりと、どういうアクションをしてほしいのか、なぜそれが危ないのか、こういう可能性があるから危ないのですと、だからチェックしてと。品川区として、どうしていきたいのか。この表現の仕方をちょっと考え直していただきたいのですけれども、いかがでしょうか。","respondent":"鈴木建築課長","answer":"確かに、一級建築士などの専門家に相談してみましょうというところだけで、助成の説明がこの資料から抜けているところもありますので、総合的な、その後どう助成を使っていただけるかとか、その辺の工夫はこれからまたしていきたいと考えています。","voiceIndex":77,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"ご苦労がすごく見えるのです。多分いろいろ工夫されて、なるべく専門用語を使わないようにしているのだろうというのはすごくわかります。もともとの目標、品川区がなぜこれをやろうとしているのかというメッセージをきちんと伝えていくことが一番大切だと思うのです。いろいろやりながら、いろいろご意見をいただけると思うので、ぜひ、ちょっと考えていただきたいと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"耐震化事業とほかの事業にあわせて戸別訪問を行ったりして、今回はこの安全点検シートを書いていただいて、区として今後の事業のデータベースなどにしていかれるのだと思うのですが、がけ・擁壁と同じように目視レベルになってしまうと思うのですけれども、目視レベルで、品川区としては、ちょっと危ないというブロック塀の全体の把握している数というのは大体どのくらいになるのでしょうか。","respondent":"鈴木建築課長","answer":"全体的な区内のブロック塀の数については、把握してございません。","voiceIndex":80,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"それは、あまりにも数が多いとか、そういった理由なのでしょうか。","respondent":"溝口公園課長","answer":"大体５万３,５００ｍぐらいのブロック塀があると、緑化可能な、道路に面しているところの延長です。","voiceIndex":82,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後、今回の安全点検でそれなりの数が出てくると思うので、ぜひとも、その数を出して、安全なブロック塀やデザインフェンス等、生垣の誘導をしていっていただきたいと思うのですけれども、その点、よろしくお願いします。２点目なのですけれども、今、他の委員の方からもご質問があったのですが、ブロック塀安全点検シート。ぜひ、その点のご配慮もお願い申し上げたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-035"}]},{"id":"topic-05","title":"「都市鉱山からつくる！みんなのメダルプロジェクト」への参加","agenda":"「都市鉱山からつくる！みんなのメダルプロジェクト」への参加","exchanges":[{"speaker":"西本委員","kind":"質問","question":"携帯電話等なのですけれども、個人情報の処理はどうするのですか。そういう所に出すときには自分でやってというのが基本なのでしょうけれども、そうとも限らない場合があるので、その対処はどうされるのですか。","respondent":"工藤品川区清掃事務所長","answer":"しかし、全てが全てそういった形でやっているわけではございませんが、認定事業者に渡しまして物理的な破壊、解体等をいたします。その物理的な破壊をもって情報は全く出なくなる、削除される仕組みになっております。","voiceIndex":91,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"依頼する業者も、そういう守秘義務であったり、信頼がある方とは十分に存じておりますが、ただ、何があるかわからないところがあるので、そこの契約上で何か交わしたりとかはあるのですか。","respondent":"工藤品川区清掃事務所長","answer":"認定事業者も、そちらの契約事項を守るということで、国から認定を受けているものですので、そういった意味では二重の間違いのない処理がされているです。","voiceIndex":93,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"区民の皆様方には、自分でデータを消去してくださいというのが基本だと思うのですけれども、それはどういうところで周知するような方法をとっているのですか。","respondent":"工藤品川区清掃事務所長","answer":"こちらは、私どもで人的配置をしておりまして、回収ボックスに入れても、持ち去りとかといったことができないような仕組みを構築しております。そういった意味では、万全の体制で、持ち去り防止や個人情報の保護という部分を図っておるところです。","voiceIndex":95,"id":"exchange-038"},{"speaker":"西本委員","kind":"意見","question":"いろいろと二重、三重のチェックが必要になってくると思うのです。まだ見ていないので、どういうホームページなのかわからないのですけれども、そこは個人情報を別色にするとか、目立つような形にして、自己責任というところを含めて強調してもらいたいと思っています。それと、完全に潰しますから心配しないでくださいというご案内です。そういう形も必要な部分はあるかなと。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、使うものは持ち歩いているということなのです。要らなくなった、使わなくなった携帯電話を捨てるのにすごく抵抗がある人も多いと私は感じるのです。このボックス回収を区としてやるということで、区に持ってきて、データを何とか消去したいのだけれどもと言ってこられた場合は、対処しようがあるのですか。それとも、携帯屋に行って、削除の作業をしてもらって、持ってくる形になるのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"携帯電話につきましては、基本的な考え方といたしましては、自己責任、自己処理ですので、ご自分でやっていただく。そうでない場合には、携帯ショップ等に行ってやっていただくという部分をご案内するです。","voiceIndex":98,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"小型家電は、主に携帯電話とかデジタルカメラだけなのですか。書いてあると思うのですけれども、そういうものの周知も必要ではないかと思うのです。小型家電と言われても、細かく言うと、携帯電話、デジタルカメラというのは浮かんでくるのですけれども、ほかにはどんなものがあるのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"小型家電と言われているもの、私ども回収ボックスで回収しているわけですけれども、こちらは平成２５年１０月に法律が施行されて回収という形になりました。","voiceIndex":100,"id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう回収を始めているということなのですけれども、結構、入るものでしょうか。まだ周知がされていない状況かもしれないのですけれども、もう何点かは入っている状況でしょうか。","respondent":"工藤品川区清掃事務所長","answer":"ただ、今回のこの取組みで、さらにこれが加速されるのではないかというのが私どもの考えです。","voiceIndex":102,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":30010,"voices":107}},{"id":"h29-20170515-9","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"文教委員会","time":"午後 １時００分～午後 ４時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区ライフスタイルに関するアンケート調査","agenda":"品川区ライフスタイルに関するアンケート調査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"ちょっとわからなかったのですけれども、ひきこもり群とひきこもり親和群を除いたものを一般群として統計しましたということですが、ひきこもり群のところを見ると、例えば、統合失調症とか、身体的な病気だとか、妊娠中を選択した云々は除外したと書いてあります。ということは、この除外された人たちは一般群のほうへ入っているのでしょうか。","respondent":"高山子ども育成課長","answer":"こうした除外のものに該当した方に関しましては、その下のひきこもり親和群などに該当するケースもあるかと思いますので、一般群とひきこもり親和群いずれかに入ってくる可能性があるというふうに考えてあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、これはひきこもり群としてもかなりシビアな部分だと思うのですけれども、例えば統合失調症とかは全部ほかのところに回ってしまうということになるのですね。それとあともう１つなのですけれども、このひきこもり傾向群の同居人数でひとり暮らしが９人ということで、この人たちは、ひきこもりなのだけれども一人で暮らしているということですか。","respondent":"高山子ども育成課長","answer":"病気等の理由につきましては、別の施策において対応していくということも従前から言われておりますので、そういった意味で、この分類上はこういった方々を除くということは、我々としても統一のルールとして採用させていただいたものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"もう１つは、前、厚生委員会で名古屋のひきこもりの対策施設に見学に行ったのですけれども、ひきこもりは家の中にこもっているということだと思うから、もともとひとり暮らしでひきこもりというのはあり得るのですか。その辺が単純な疑問なのですけれども。","respondent":"高山子ども育成課長","answer":"大きくは、収入などの面の話もあるかと思うのですが、必ずしもひきこもりの方が一人で住んでいるかどうかというのは、これはやはり家族と同居しているケースなどもありますので、そういう意味では。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、ほかのところでしっかりと支援があるという考えでよろしいでしょうか。アンケートの調査票を見ると、お住まいの地域とか、居住環境も、ひとり暮らしとか、２人とか、３人とか、家族で住んでいる方もいて、状況もいろいろ違うのですが、そういった環境の違いによる傾向といいますか、今のところ、どう見られているのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"そうした病気の方々などは計画の中から除外されていくのかという点です。施策としては、もちろん既にこれまでも取り組みがあるものですので、それは継続していくものです。計画の中には、そうした方々に関する部分についても、やはり盛り込んでいきたいという考えではおります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"傾向群として一緒にした理由ですけれども、大きな傾向をつかむためというお話でしたが、個別の分析もされていくという認識でよろしいのでしょうか。地域分けにすると、母数が少ないところが出てきてしまうということで、人口のパイがもともと少ないので、なかなか地域別で見ると偏りが出てしまうというか、しっかり把握できないという認識だということでいいのか、それは確認です。","respondent":"高山子ども育成課長","answer":"人口のパイにつきましては、やってみないと、というところはあるのですけれども、ミニ品川区のようなイメージだと思うのですけれども、地域別にやることで何か逆に地域によって極端なものが出てしまうと、やはりそれは結果としてよろしくないというふうな部分もありますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりその人の居場所づくりということも必要だと思いますし、当然、勤労の義務も国民にはあるわけですけれども、そこまでまだたどり着けない方も多くいらっしゃると思いますので、まずは誰かと対話をする、社会との関係を持っていく、そういった取り組みも大切だと思うのですけれども、いかがでしょうか。","respondent":"高山子ども育成課長","answer":"こうしたものの限られた情報とはなりますが、お答えいただいた回答の中から、より品川区の若者の実態に迫れるような、そんな分析をこれから進めていきたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"アンケート項目は、そういった趣旨ではないというお話でしたので、そう感じないように、今後もし２回目のアンケートがある場合、答えたいと思うような設問にしていっていただければと思います。それと、対話や話し合いを望まれていたら、その１歩目からしっかりと支援していく、そういった場をつくることや、支援もぜひ検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"先ほどもありましたけれども、内閣府、東京都と調査の仕方が違うので、一概にここでは比べられないということですけれども、それにしてもちょっと低いのかなということが気になっておりまして、ここら辺をどう受けとめているのかということと、実際にこの数でこれから分析を進めていかれるわけですが、この数での調査が進んで、これで足りているのかといいますか。","respondent":"高山子ども育成課長","answer":"今後、同種の調査が行われるに際しましては、訪問なども１つの手法だと考えられますので、そういったものを採用するかどうかについては、またその時点で考えてまいりたいと考えています。それから、回収したものに基づいての分析です。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"この報告の中でちょっとわからなかったのですけれども、例えば、ご家族の方、これは多分、個人宛てに配送されているのだろうと思うのですけれども、かわりに親が答えたとか、この余白の部分で実はこういう状況があって困っているのだというような具体的なご相談が、このアンケートの中で出てきているのか、教えていただきたいと思います。","respondent":"高山子ども育成課長","answer":"その中でいただいた意見としましては、今回、１５歳からが対象者ですので、親御さんが見られて、親御さんがご自分で回答してもいいのかというようなお尋ねでありますとか、あるいは、本当に区でやっていらっしゃる調査なのですかというようなことでのお尋ねがありまして。","voiceIndex":20,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"例えば、またほかの統計ですとか、調査ですとか、家族構成に関する統計のような、あるいはまた、高校中退者の数字ですとか、そのような別の角度からの調査も含めて、大まかな推計値とまで言わなくても、ボリューム感を把握していく何か手法は考えていらっしゃいますでしょうか。","respondent":"高山子ども育成課長","answer":"１つには、品川区の統計などで経年でとっているような統計数値でありますとか、国勢調査の類、そういったものも参考にしながら、いろいろな角度から計画のご審議を進めていただけるような、そんなものをご用意させていただいた上で。","voiceIndex":22,"id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"こういったアンケートが来ても、なかなか回答しにくい内容だと思うのですけれども、やはり相談窓口ですとか、あるいは、支援体制のようなものを整えていくことと並行して、いや、実はうちもという話に多分なっていきやすいと思いますので、これは今後の計画策定とセットだと思うのですけれども、ぜひ受け皿を充実させていくことと、それから把握することを並行して進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"今回、アンケート調査で、結果は概要で大きなところの報告だったのですが、全体像のアンケートのまとめのところは、どこで知らされるのかということが１点です。本当にこれからの分析が大切と思いますけれども、どこで分析されるのか。専門的な方が入るのか、いろいろな部署にかかわる問題が出てくると思うのですが、分析をどこでやられるのかということを教えてほしいのが２点目です。","respondent":"高山子ども育成課長","answer":"いわゆる冊子のまとめのタイミングにつきましては、検討期間がありますので、委員長との相談の中でタイミングについては決めてまいりたいと考えております。","voiceIndex":25,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５歳から３９歳というと、例えば、中学校を卒業した後、高校を卒業した後、大学を卒業した後、時期的な問題と、そこで遭遇した理由というか問題によってさまざまなことが影響して具体的な事象としてあらわれてくるのだろうなと思うので、いろいろなところの横の連携を持って分析をしていただかないと、有効な施策に結びついていかないのではないかと思うので。","respondent":"高山子ども育成課長","answer":"現在、策定検討中の子ども・若者計画につきましては、夏に開催されます青少年問題協議会の場で素案の形で提出をさせていただきたいという思いで、現在、鋭意検討作業を進めているところです。それから、分析につきましては、横の連携をというようなお話もございました。","voiceIndex":27,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"横の連携、庁内のそれぞれの部署でということですけれども、文教委員会としては、学校の現場とか、不登校の問題とか、扱っていらっしゃる部署の意見などもすごく重要であると思いますし、役所以外のＮＰＯでいろいろ居場所づくりなどに取り組んでいるところの意見もぜひ取り入れてほしいし、若者のサポートステーションとか、雇用につながるようなところの部署の意見もどんどん積極的に聞いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"参考調査のところで、４０歳から６４歳の方のアンケートもとられていますけれども、これはどういうふうに利用していくのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"そういう意味では、計画そのものには、やはり若者を中心とした計画ですので、直接的な反映はないのですけれども、やはり課題の認識として、本調査から分析されたものについては、子ども未来部以外の部門でも共有していければと考えているところです。","voiceIndex":30,"id":"exchange-015"}]},{"id":"topic-02","title":"平成２９年４月入園申込状況等","agenda":"平成２９年４月入園申込状況等","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"ちょっと待機児童が増えてしまいましたので、質問します。ここまで増えてしまった要因、この荏原地域に申し込みが多くて、そちらのほうが受け入れができなかったということもありますが、ここまで増えてしまったのはなぜかという点をもう１度教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"そのあたりも待機児童が増えてしまった要因の１つではないかというふうにも感じております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問","question":"マッチングというところも非常に大きいと思うのですけれども、要は、１２月に締め切った段階で、条件の変更はできないですよね。そうすると、例えば、ここはあいているから、こっちの園はどうですかという変更は、個々のそのやりとりはできるということですか。","respondent":"大澤待機児童対策担当課長","answer":"例えば、第４希望、第５希望で入られた方は、近くに認可園があると、２園、３園、通り越してまで行くのが心情的になかなか、そこしかなければきっと行くのでしょうけれども、なかなかそういうことが難しいとか、あとは、私立で特色を打ち出している園が増えてきていますので。","voiceIndex":39,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問","question":"あきのままにしておかないで、やはり入りたい人のところにしっかりマッチングをしてあげて、条件をちょっと変えてといいますか、ここまでの期日だけれども、そういう部分を変えて４月の段階でそこに入れていくことは考えられるのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"今の状況ですと、５月の申し込みで対応するしかないような状況ですけれども、今すぐにいい方法を考えられませんけれども、その辺はやはり４月の時点で７０幾つのあきのまま待機児童として待たせている方がいるというのはよくない。","voiceIndex":41,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"この後、報告いただきますけれども、来年も既に開園が予定されておりますし、荏原地域が多くなるということも出ておりますが、来年こそは待機児童を本当に減らしていく、ゼロに近づけていくという方向で、さまざま今回のことを踏まえて、変えるべきところは、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"それとも、あきさえあれば指数が低くてもどんどん入れていくというようなことになっているのか、例えば、新設園などだと、かなり保育の必要性が低くても、あいているから入れて、その方がずっと最後までいらっしゃるというと、何となく１人を受け入れる行政のコスト、税金のコストということを考えると、ちょっとどうなのかなという気がするのですけれども、どういうお考えなのでしょうか。それが１つです。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"４点ご質問いただいたうちの１点目のあきがあれば入れていけるのかというご質問だと思うのですけれども、今現在、保育園の施設の制度上、定員にあきがあれば定員に達するまで入れるということが国からの通知でもありますので。４月の時点の待機児童の中で、４月１日の時点で認可外に決まって通われている方は８８人いらっしゃいますので、この方たちは、今後、認可外の保育料助成ということで対応していきたいと考えております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"一次で上位希望でないのでと言って辞退される方は、この方々の就労の実態がどのようになっているのか、または何らかの保育を別の手段で用意されているかどうか、ここら辺はわからないことなのでしょうか。違うのか、この２１９人の中に８８人が全て入るとなると、相差の部分が実際に行くところが現在ない方というふうに考えていいのでしょうか。それを教えてください。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"１点目ですけれども、指数の低い方が一度タイミングよく入られた場合、卒園までいるのかというご質問ですが、先ほどの答弁とかぶる部分があるのですけれども、基本的に、児童福祉施設ということもありますので、月１２日以上。待機児童の状況ですが、２１９人のうち、認可外に行っていらっしゃる方が８８人で大体４割、残りの６割の方が、主にお母様になるかと思いますけれども、ご家族が見られている。","voiceIndex":47,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"初めに確認させていただきたいのですけれども、別表１の在籍／定員という一番右のところで、１００％以上になっているのは、いろいろ弾力化とかの理由があると思うのですけれども、区立園も私立園も基準の面積は確保されているということでよいのかということを１つ確認させていただきたいと思います。もし変更した理由があれば伺いたいと思います。","respondent":"佐藤保育課長","answer":"それと、１２番に関してですが、これは夜間保育園がありますので、夜間保育園になるべく入っていただくということで、２点の加算をしているところなのですけれども、統計上、私立保育園も８時半までやっている園が増えていますので。","voiceIndex":50,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"そういった中で、先ほどもありましたけれども、今年は待機児童が減るというお話だったのが増えてしまったというところで、待機児が増えてしまった、待機児をゼロにできなかったという区の責任については、どう考えていらっしゃるのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"受け入れの拡大枠としては、平成２８年が８３９人で、平成２９年４月が８８５人なので、拡大数としては、ほぼ一緒なので、入れる方の人数は、そんなに劇的に増えるということではないという説明でご理解いただけると助かります。","voiceIndex":52,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"入園者の数が増えなかった理由なのですが、今のご説明だとわかりにくかったので、もう少し何か説明があれば伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"すごく単純に言うと。なので、毎年８００人ずつ開設していくと、８００人ずつ入れるという意味なので、前年と比べても入園者数は増えないというのが一番単純な説明です。ゼロに向けて、平成３０年以降、頑張ってまいります。","voiceIndex":54,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この待機児、入園の申し込み、待機児をなくしていくというところにおいては、担当課の皆さんのご努力は重々承知の上、本当に頑張ってくださっているなとは思ってはいるのですけれども、実際に待機児と言ったら、そのお子さんと保護者の方を考えたら、１名も出さないということで、一刻も早く本当にゼロを実現していただきたいというのは多くの区民の方の願いですけれども。","respondent":"大澤待機児童対策担当課長","answer":"あわせまして、保育を希望する方の割合、計画を策定したときにニーズを調査しまして、一定出しておりますけれども、そちらのほうの割合も、今、現実と乖離しておりますので、こちらも実態に見合った数字に直して計画を見直して。","voiceIndex":56,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前年度より１歳児が１２０人増えたというのは、これは予想外だったのですか。先ほど、伺っていてよくわからなかったのが、遠い認可よりも近い認可外と言って、７６枠があいているのはどこを見たらわかるのか、もう１回、７６枠あいて、そこが埋まらなくて認可外で、それが待機児になったということなのですけれども、そこが理解できなかったので、もう１回教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"子ども・子育て計画に沿って開設は進めているところですけれども、なかなか想定外の数値が出てくるということがあります。１歳に関しましては、何らかの方策を実施しないと、委員おっしゃるように、来年、１歳児がまた増えることになるので、それはこれから検討を進める予定です。","voiceIndex":60,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この次の報告のところでも示されているとおり、拡大のご努力はすごくわかるのですが、先ほど、のだて委員も意見を言いましたけれども、ぜひ民間頼みではなくて、区立の保育園の増設のところもぜひ考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"意見","question":"別表１で、定員を在籍が超えているところもあるのですが、こういうところの保育士たちの手当てについては、常勤の方も含め、新年度が始まってしまいましたので、どのような対策をとっておられるのか。４月からの運営に問題ないように、どう体制を整えられたのか。","respondent":"佐藤保育課長","answer":"定員弾力化も含めた公立保育園の受け入れの体制ですが、新規採用職員の採用も当然なのですけれども、引き続き、非常勤、短時間のアルバイト等も、保育課一丸となって面接等を行いまして確保しまして。","voiceIndex":63,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、地域別とか需要のところを伺ったら、不承諾の方の調査が今後必要ではないかということを言われたので、ぜひ中身をもうちょっと、分析をする意味でも聞いていただきたいと思うのと、需要の捉え方が、申請をされる方以外にも、今あまりにも入れないので、もうどうせ無理だろうと思って諦めている人もいるので。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの年度途中の入園ですとか、これから入れたいという人の需要にこたえるまでには、今すぐということは、この状況では難しいと思いますけれども、今後は、そういう方たちも含めて考えていかなければいけないということは認識しています。","voiceIndex":65,"id":"exchange-029"}]},{"id":"topic-03","title":"認可保育園等の新規開設","agenda":"認可保育園等の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これだけ開園されると、待機児童解消にも役立つと思いますので、所管課の努力も評価したいと思います。あわせて、先ほどもぜひ区立園の設置を検討してくださいと言いましたので、よろしくお願いいたします。今回、１４園の中で、園庭のあるところ、ないところを教えていただければと思います。ない場合、代替施設がどこなのか伺いたいと思います。承認予定のものはどこになるのかも伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"承認予定の園ですが、キッズガーデン豊町、キッズガーデン西五反田、キッズガーデン小山とみらいく保育園と、こころしながわふどうまえが５月の予定ということになってあります。","voiceIndex":72,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"園庭がなかなかない中で、やはり公園も、既に保育園が増えてきたところでいっぱいになっていますので、そういったところのお考えは、区としてはどう考えていらっしゃるのでしょうか。公園をつくるというのは別の課になると思いますので、そういった課に要請していたりするのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"保育園がかち合って公園が混んでしまうというような状況は聞いてありますので、新規の園に関しましては、代替施設として設定している園にどこの園があるかということはお知らせして、その近隣の園と調整するように。","voiceIndex":74,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"Kids Smile Projectも３園、アイ・エス・シーも３園ということで、今、保育士を採用するのにかなり困難を抱えている中で、一遍にこれだけの施設を開設するに当たって、保育士等の職員の確保は大丈夫なのだろうかという心配をまず抱いてしまうのですけれども、その辺はどうなのかというのと、保育園ができることはもちろんうれしいのですけれども、保育の内容的に。","respondent":"大澤待機児童対策担当課長","answer":"指導検査につきましても、都との合同ですとか、区独自の検査を積極的に進めていくということでやっておりますので、事故については厳しく、気をつけて指導してまいりたいと考えております。","voiceIndex":76,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事故のことも、現実的に今までの運営をしていた中でどうだったのかと、やはり明らかにしてほしいと思ったのと、あと、園庭も、課長のご努力では、水遊びできる程度のというところを言ってくださってはいるのですが、インターネットで調べると、他区のところでは園庭があるような保育園もあるので、その辺、品川だったら園庭がなくてもいいのかという部分があるのかどうか。","respondent":"大澤待機児童対策担当課長","answer":"待機児童対策でさまざまな方策がいろいろ国からも打ち出されていますけれども、子どもに直接かかわることは、保育の質の問題では慎重な対応が必要だというふうに認識していますので、例えば、面積基準ですとか、保育士の配置基準ですとか、小規模園で定員を超えて受け入れるとか。","voiceIndex":78,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点なのですが、このところ、本当に公立と同じだけ私立、もう私立が上回ってきているわけですけれども、開設にこぎつけるまでもそうですが、その後の園長会の運営とか、チェック機能はいろいろあると思うのですが、担当課のチェックのところで、私、人手不足ではないかとすごく感じているのですけれども、この辺は、担当の課長とか部長はどう受けとめていらっしゃるのかお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"具体的に私立支援係が、４月で１０園、今年度中に１２園増えますので、そこには職員を１人増員しています。足りているか足りていないかということでは、きちんと仕事は回しております。","voiceIndex":80,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"部長はどうかと思って。私立支援係は、基本的には何人いた上で１名増えたのかどうか。具合の悪い人はいないでしょうか。やはりこんなに増えていて、すごい大変だと思うので、健康な方によりよい仕事をしていただきたいと思う見地から、いかがでしょうか。","respondent":"佐藤保育課長","answer":"私立支援係は、昨年度６名、今年度１人増えております。ただ、私立支援係１つの係だけでやっているわけではございませんで、庶務の係もありますし、人事当局のほうからも優秀な人材を人事異動で送ってもらっていますので、私も含めて課全体で私立保育園の増には対応しています。","voiceIndex":82,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"今、認可園と認証園ということでご報告をいただいているのですけれども、今年度から認可外についても一定の公費が、これは園そのものではないですけれども、公費が出るようになって、今後、品川区として、認可外保育園についての、例えば開設状況ですとか、あるいは、一定の質の関係ですとか、そういったことについて、ある程度、品川区として、今、届出先は東京都ということですけれども、ただ。","respondent":"大澤待機児童対策担当課長","answer":"ただ、制度上、区の職員だけで立ち入り調査を行うというのがちょっと難しい状況なので、向こうの了承をとった上で入ることはありますけれども、どこまで区で指導できるかというと、ちょっと微妙なというか、難しい問題がありますので。","voiceIndex":84,"id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうすると、やはり認可外の質についても、公費を出している以上という言い方をしたらちょっと言い過ぎかもしれませんけれども、やはりある程度、区として、より積極的な管理を、今、仕組み上は都の了承を得てということであっても、より積極的に、あるいは頻繁にやっていく必要が今後出てくるのではないかと思うのですが、そういう実態であれば。","respondent":"大澤待機児童対策担当課長","answer":"委員おっしゃるとおり、やはり認可外につきましても、区内の区民のお子さんが通っているわけですから、何らかの関与はしていかなければいけないと思っているのと、やはり助成を始めるということで、今まではなかなか認可外の施設とコミュニケーションというか。","voiceIndex":86,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"新規開設のご努力をされているので、大変によいことですし、施策の進行を非常に心強く思っているので、ぜひこの先も頑張っていただきたいのですが、新規開設園の周辺への説明を、さまざまニュースで出ておりますけれども、そういったところをきちんとするように、開設者に担当の方からしっかりとお話ししていただきたいのですが、そのあたりの体制はどのようにして、実際。","respondent":"大澤待機児童対策担当課長","answer":"個別訪問につきましては、工事について必ず書類を持ってお回りして、複数回訪問して、どうしてもお会いできない場合はポスティングということもありますけれども、基本は説明会または個別訪問で近隣の方には内容をご説明する。","voiceIndex":88,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区のほうで進めている事業の妨げといいますか、いろいろ齟齬があると、うまくいかなくなったりするので、現状では、今出ているところでは、そういうものは出ていないとお聞きしているのですが、そのようなトラブルと言うとちょっと大げさですけれども、現状ではそういうものはないという認識でよろしいでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"去年はいろいろ大きな反対もあったので、５時間にわたって必死に説明申し上げたりですとか、いろいろありましたけれども、今年度について、今のところは、そこまで大きな反対はないという状況です。","voiceIndex":90,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"済みません、１点だけ。先ほど求めたのですが、参入事業者のチェック項目、今日教えていただけるのか、後で資料で出してくださるのか、最低でも離職率と人件費比率は知りたいと考えています。","respondent":"大澤待機児童対策担当課長","answer":"参入するためのチェック項目というのは、具体的には、財政状況と……。そういうことではなくて。","voiceIndex":92,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"さっき言ったのは、保育園の経験があるかどうかとか、事故の件とか、最低でも離職率と人件費比率はお伺いしたいと思っているのですが。","respondent":"大澤待機児童対策担当課長","answer":"それはまた改めてご報告するということでよろしいでしょうか。","voiceIndex":94,"id":"exchange-041"}]},{"id":"topic-04","title":"平成２９年度新入学学校別増減要因一覧","agenda":"平成２９年度新入学学校別増減要因一覧","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"中延小学校は毎年少ないのですけれども、今年も少ないみたいですが、今、学区の組み替えの協議が学事制度審議会でされていますね。その結果が出るまでは現状維持で様子を見るということになるのでしょうか。","respondent":"有馬学務課長","answer":"中延小学校につきましては、基本的に学区を今現在、来年に向けてどうこうするということは、今のところ考えておりません。基本的には学事制度審議会の中で全体としての学事制度の見直しを全体として、この学校でということではなくて、全体として考えております。","voiceIndex":107,"id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"要するに、学事制度審議会で学区の見直しをしているから、今現在、中延小学校の数が少ないことに関しては、何か学区を動かすとかというのではなくて、魅力の発信だとか、取り組みをするとか、何か数が増えるような取り組みとかは考えていないのですかということを聞いたのです。","respondent":"有馬学務課長","answer":"学事制度審議会を待つということではなくて、特に小規模校については、自校の魅力を発信していくということで、毎年それは努力はしているところですので、それは継続して行っていく予定です。","voiceIndex":109,"id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"いや、だから、その結果がこうですかということです。","respondent":"有馬学務課長","answer":"今年度につきましては、中延小学校は希望者が６名ということで、昨年は２名でしたけれども、４名のプラスというようなことで、一応の結果は出ているというふうに認識をしております。","voiceIndex":111,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"この表の中で、小学校から義務教育学校に移った人数は、どこを見たらわかるのか伺いたいと思います。","respondent":"有馬学務課長","answer":"それは在籍している……。〔「意味がわからない。在籍している前期課程の人がそのまま後期課程に進んだという意味なのか、その数字は出ていないのですけれども、裏面を見れば、全体として義務教育学校に進んだ人数は、中学校、義務教育学校の後半の１番から６番の義務教育学校。","voiceIndex":114,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"幼稚園と小学校との連携が大変活発に行われていて、まさに一貫した形の教育が行われていると伺っていますので、その成果で同じ敷地内の幼稚園に通っていらした方が、その小学校に入りたいといった場合に、もちろん住民基本台帳上の学区内ならいいのですけれども、学区外からその幼稚園には入れるわけですね。ところが、上がるときには抽選というか、小学校は学区外の扱いになる。","respondent":"有馬学務課長","answer":"幼稚園だけではなくて、実際には、今、保育園との連携事業もやっているというような部分もありますので、そういったことも総合的に考えていかなければいけないだろうということで、単純に、今、敷地内に幼稚園があるので。","voiceIndex":117,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この前もここで討論したのですけれども、やはり幼稚園と小学校の連携が非常にうまくいっている例だと思うのです、成果が出ているというところだと思うのです。ですから、今なかなか、何ともご報告しようがない部分があるのかもしれませんが、ぜひ何らかの計画を進めていっていただければということで、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-047"}]},{"id":"topic-05","title":"わ！しながわオリンピック・パラリンピック教育「ようい、ドン！」","agenda":"わ！しながわオリンピック・パラリンピック教育「ようい、ドン！」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今、最後のところの説明で、無理のない範囲でいろいろなところで活用していくということなのですが、最後のところ、各教科等における年間３５時間程度の学習、これ、学校で全体ということなのですか。学年とかではなくて学校全体で年間３５時間、いろいろなところで使っていくという、そこのところをお願いします。","respondent":"熊谷指導課長","answer":"この「ようい、ドン！しながわ」につきましても、どの学年でどのぐらいやらなければいけないということではなく、それぞれの子どもたちの実態に応じて、各学校で年間指導計画に位置づけながら活用していただきたいというふうに考えております。","voiceIndex":124,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"オリンピック・パラリンピック教育となっているのですが、オリンピックに当たって、パラリンピックもそうなのですが、精神というか、根本の原則のオリンピックの発祥の当時は、争いをやめて、このときだけでも平和にしていこうとか、心と体と社会全体のバランスよい世界をつくっていこうとか、いろいろな精神的なものが盛り込まれていたと思うのですが、この品川の教育のところのこれをつくるに当たって。","respondent":"熊谷指導課長","answer":"しながわ」になっていくわけなのですが、特に世界ともだちプロジェクトの部分ですとか、また、障害者理解ということで、ブラインドサッカーも載せてありますし、また、環境というところにおいても、やはりオリンピック・パラリンピックは非常に重要なので。","voiceIndex":126,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、課長がおっしゃったように、ぜひ平和の部分、国際的なつながりとか、そういった面で、いかに平和が大事なのかということも含めて、障害者の理解の面でも深まるように活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問","question":"その中でオリンピック・パラリンピック教育のこういう部分を活用する、そこで伝えていくというふうに考えていただかないと、こちらがメーンになって、例えば市民科などでも本来やるべき部分が削られてみたいな話になっていくと、本来の目的が損なわれてしまうので、本来進めていく中で、オリンピック・パラリンピック教育を十分に活用してというふうにしていってあげるといいなと思っているのですけれども。","respondent":"熊谷指導課長","answer":"委員ご指摘のとおり、まずは学習指導要領の目標を達成するためというところが大事です。その中で、例えば社会科で、１９６４の東京オリンピックの前後で町は非常に変わって、そこでレガシーとして今も残っているものがあります。","voiceIndex":129,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"意見","question":"そうしていただければと思います。通常の授業をされていく中で、先生方が過度の負担というか、そういうことにならないように、重要性は十分承知しておりますけれども、実際、配慮をしていっていただけるといいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-052"}]},{"id":"topic-06","title":"平成３０年度品川区立学校教育職員採用候補者選考日程","agenda":"平成３０年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"昨年、たしか６人採用しようということでやって５人採用だったと思うのですけれども、今回も６人程度の採用予定で３０人の目標人数を達成できるということでよろしいのでしょうか。","respondent":"熊谷指導課長","answer":"現在、２４名固有教員がおりますので、今年度、６名程度採用いたしまして、ただ、６名絶対にというよりは、品川区で一生先生をしていただく方ですので、資質ですとか適性を見まして、６名程度採用する予定です。","voiceIndex":136,"id":"exchange-053"},{"speaker":"新妻委員","kind":"確認","question":"済みません、１点だけ確認いたします。資格要件の中で、(1)または(2)というふうに書かれているのですけれども、区としては、(1)のほうを多くとか、(2)のほうを多くとか、何かそういうお考えはあるのでしょうか。","respondent":"熊谷指導課長","answer":"義務教育学校もありますので、どちらでも先生として教壇に立ってほしいというふうに思っていますが、ただ、実際にお会いした、選考を受ける皆さんの様子を見ていますと、中学校免許だけであっても、非常に品川区として、ぜひこの人が欲しい。","voiceIndex":138,"id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問","question":"あまり本質的ではないかもしれないですけれども、これ、６月に募集をして、７月と８月に試験をして、最終的に９月下旬ぐらいに決めるということですけれども、そうすると、これで募集する方は、例えば、今現在、現職の先生という方だと、その時点で、今、仕事をしている職を辞めるということになるのですか。","respondent":"熊谷指導課長","answer":"この選考の募集期間から最終的な結果発表に至るまで、今も講師を続けながらですとか、期限つきの方ですとか、それから、産休育休代替の方もいますので、受かるまでは辞める必要はございません。受かったところで辞めて固有教員になっていただくということになります。","voiceIndex":140,"id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、前のところで、今日も何もいわなかったのですけれども、例えば、６月から９月というのは、これは時期としては適切なのですか。仕事が決まってしまってからということになるのではないかと思いますが。","respondent":"熊谷指導課長","answer":"東京都ですとか、他県も同じ時期に実施していますので、それに準じてということで考えております。ですので、特にこの期間で課題があるかということは今までございませんでしたので、ほかの都道府県と同様に実施していきたいと考えております。","voiceIndex":142,"id":"exchange-056"},{"speaker":"沢田副委員長","kind":"確認","question":"今、現状の確認をしたいのですけれども、小学校と中学校の両方の免許状を持っている先生は、この２４人のうちどれぐらいいらっしゃるのですか。","respondent":"熊谷指導課長","answer":"非常に難しいのですけれども、複数の免許を持っていらっしゃる方がおりまして、実際には、小学校免許と、例えば特別支援の免許ですとか、それから小学校と中学校の教科も複数持っていらっしゃる方もいますので、一概に今何人ということは言えないのですけれども、ただ。","voiceIndex":144,"id":"exchange-057"},{"speaker":"沢田副委員長","kind":"質問","question":"先ほど、今回、３年以内に小学校免許取得の意欲のある方を支援していきたいという話があったと思うのですけれども、この今いらっしゃる中で、そういった小学校免許をこれから取りたいという方がいらしたら、その方も支援していかれるということですか。","respondent":"熊谷指導課長","answer":"今年度採用になった５人のうち２人が小学校免許を持っておりません。ですので、この２人については、今年はなったばかりなので、すぐに免許を取りにいくのは難しいと思いますけれども、この２人についても補助していきたいと考えているところです。","voiceIndex":146,"id":"exchange-058"},{"speaker":"沢田副委員長","kind":"質問","question":"ほかのその前のときに入った方とかはどうなのですか。","respondent":"熊谷指導課長","answer":"もともと小学校免許というふうにうたっていた時期がありますので、実は、昨年度、中学校国語の２級免許を取った方がいます。３年ぐらいかかったのですけれども、実際に全てこちらで補助をして免許を取らせた経緯があります。","voiceIndex":148,"id":"exchange-059"}]},{"id":"topic-07","title":"東京学芸大学と品川区との連携による学習支援事業（ＧＳＰ）の概要","agenda":"東京学芸大学と品川区との連携による学習支援事業（ＧＳＰ）の概要","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"区立の中学校へ入るのは義務教育だから、どこか受け皿を見つけて入るということでいいと思いますけれども、学芸大附属竹早中学の場合は、当然、入試があって、選択して、試験に受かった人が入るところですから、これで進学の枠をつくって４名上限ということは、入試で入ってくる一般生徒との整合性とかはどうなるのですか。","respondent":"熊谷指導課長","answer":"東京学芸大学はさまざまこうした取り組みをしているようでして、この竹早中学校ですけれども、幼稚園から入ってくるお子さんも小学校から入ってくるお子さんもいらっしゃるのですが、特に中学に入るに当たって、全入で、そこに上がるための内部試験等はないそうです。","voiceIndex":154,"id":"exchange-060"},{"speaker":"新妻委員","kind":"質問","question":"もうちょっと詳しくお聞きしたいと思います。竹早中学校への進学、４名枠ということなのですけれども、これは支援の大学生との勉強の支援をする中で、希望した人が、まずは品川の中で４名を決めていくという考え方なのでしょうか。","respondent":"熊谷指導課長","answer":"ですので、４名を決めるのは学芸大附属竹早中学校、学芸大、また、それまでの支援の中でふさわしいお子さんを選んでいくという形になると思います。ですので、最終的には面接で学芸大学附属竹早中学校の先生方との選考の中で決まっていくことになる予定であります。","voiceIndex":156,"id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"非常に独特で興味深い内容だと思うのですけれども、６年生４０名、この選び方と言ったらいいのでしょうか、スケジュールとしては書いてあるのですけれども、これはつまり、要保護等の対象家庭のみにご案内を配付して希望を募ってということにまずなるのでしょうか。ある程度、学力の枠みたいなものを設けていくのかどうか。進学の部分です。その辺の具体的なところを教えてください。","respondent":"熊谷指導課長、有馬学務課長","answer":"人数は後ほど有馬課長からご説明いたしますけれども、そうは言っても、全ての対象者の親御さんが、こうした学習に子どもを向かわせたい、行かせたいというふうにお考えにならない場合もありますので、まず説明会を行いまして、この連携。対象になる人数ですけれども、基本的には、このスケジュールにもあるように、今年の就学援助者が決定してからということになりますけれども、今の６年生は大体２,２５０～２,２６０名いまして。","voiceIndex":158,"id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。うまく４０人の中に希望者が落ち着けばいいですけれども、さっきも伺ったと思うのですが、超えたときには、区教委として４０人に絞り込むという形になるということでよろしいのでしょうか。学芸大と連携ということなのですが、これは学芸大の全体ということなのか、それともどこかの研究室レベルなのか、学芸大のどういう組織と共同研究という形になるのか教えてください。","respondent":"熊谷指導課長","answer":"そのときに、面接と、本人の意欲を見るためにも、２００字から４００字程度の勉強したいという思いを書くような作文等を出してもらおうかというようなことも考えているところです。ただ、それについてはまだ詰め切れていないところがあります。","voiceIndex":161,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"意見","question":"今のところで、どこの研究室ということで、目的があまりはっきり説明のところでわからなかったのですが、どういう目的で、誰がどう動いてこういう新しい試みがされているのか。これによると、私たちはもっと小さい年齢から必要な子に支援してほしいということも発言していたので、機会が増えていくということはいいことであると思っています。とりあえず、ごめんなさい。今ちょっと……。","respondent":"有馬学務課長","answer":"指導課長が話をしたように、学芸大学のほうで、貧困の連鎖を解消するというか、そういう環境にある子どもたちに、学習支援をしていくということで、その成果を見ていきたいということがございまして、それで私どものほうでも、就学援助の対象になっている方が、前回。","voiceIndex":163,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味では、品川区では初めての試みですが、ほかの自治体でもやられていたりするのですか。そういった広がりとか、ここだけの新しい試みなのか、そこを教えてください。","respondent":"熊谷指導課長","answer":"この学習支援事業につきましては、本区と学芸大との唯一の取り組みになります。それ以外で、学芸大学はさまざま研究をされていますけれども、この内容につきましては、本区だけということです。","voiceIndex":165,"id":"exchange-065"},{"speaker":"沢田副委員長","kind":"質問","question":"そういうものはないですか。わかりました。その辺のところがどうなっているのか。","respondent":"熊谷指導課長、中島教育長","answer":"入ってからの学習支援なのですけれども、これも引き続き、竹早中学校で配慮をしながら放課後の学習支援等もしていただけるということなのですが、ここに固有教員１名をおかしすることも考えているところなのですけれども。ただいまのご質問は、まさに品川区が一貫教育を進めている中で、今、指導課長から説明がありましたような多様な進路を提示するということで、一見、矛盾しているという部分をお感じになられるところも重々私どももわかります。","voiceIndex":167,"id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問","question":"それからあと、先ほど、３６人は区立中学に行くということですが、私立に行くことがあるかもしれませんが、区立の中学に仮に入った場合、その後も指導を何らかの形で続けていっていただけるのか、おそらく研究と言ったら失礼ですけれども、そういった成果を見ていくためには、その先もしばらく見るというプロジェクトはあるのではないかと勝手に思っているのですが、その辺はいかがでしょうか。","respondent":"熊谷指導課長","answer":"歩いて通えるかどうかということもあるのですけれども、今の段階では、バス代等の負担は考えていないところなのですけれども、本当ですと、４カ所ぐらいで歩いて通えるところということを検討していく必要があるのですけれども、今の段階では、特段。","voiceIndex":170,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"保護者の説明会や面接、これ、保護者がすごくキーになってくると思うのですけれども、経済的に困窮した家庭の方々、なかなか保護者の方がこの時間に来てくださいと、難しい部分がたくさんあると思います。代替の日を用意するなり、そこに参加しなくても意欲さえあれば、何らかこの事業自体に参加できるような方策をぜひ配慮していただきたい。要望でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-068"}]},{"id":"topic-08","title":"特別支援学級（中学校・義務教育学校後期課程）の新規開設","agenda":"特別支援学級（中学校・義務教育学校後期課程）の新規開設","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ご説明の最後に心を打たれました。浜川のほうですけれども、現在ある通級指導学級については、これは従来どおりありつつ、新たに固定級を設置するということなのでしょうか。現状との比較で教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"現在、浜川中学校にあります通級指導学級の機能はそのまま残りますが、こちらはあくまで通級ですので、平成３０年度より東京都の制度として、特別支援教室に変わっていきます。","voiceIndex":178,"id":"exchange-069"},{"speaker":"あべ委員","kind":"質問","question":"私の記憶に間違いがなければ、浜川の学級は、結構不登校のお子さんを、こうしたお子さんは、多分、支援教室というのとはまた違った扱いになるのではないかと思うのですけれども、といって、固定級に移籍していくということをどういうふうにその辺は変更されているのでしょうか。","respondent":"大関教育総合支援センター長","answer":"ただし、そうではなくて、純粋な不登校だけの対応のお子さんの場合には、週１回の通級機能の活用以外に、２年間経過措置的に、ある程度、校内体制の工夫は続けたいというふうに浜川中学校の校長からは聞いております。","voiceIndex":180,"id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"これは浜川の不登校に関する対応は非常に私はいい面もたくさん持っていると思っているのですけれども、今回この変更をすることによって、品川区として、経過措置はあるにしても、不登校対応の受け皿というが、逆に選択肢が少なくなってしまうような感じがしますけれども、五反田がこの間増えたという例もありますけれども、八潮との関係もあって、何か再配置的な。","respondent":"大関教育総合支援センター長","answer":"マイスクール八潮とマイスクール五反田では、現在、機能ですみ分けを行っておりまして、五反田のほうは完全に学校に通えないお子さんではなくて、復帰をなるべく前提とできる、あるいは未然防止という段階の対応をしておりますので。","voiceIndex":182,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"荏原第五のところは単独だから後期だけですね。突然、中学校になってから一緒に生活するよりも、小学校のときからずっと過ごしていたほうが、ずっと子どもの関係はいいのではないかというご意見もあわせていただいたので、その辺、どうして後期のみなのか、ぜひ前期のほうも入れていただきたいというご要望をいただいたので、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"後段の部分ですが、これまで小学校段階の１年生から６年生、あるいは前期課程の６年生までの段階の特別支援学級の設置状況は、学校に１つという考えというよりも、地域的なバランスで小学生段階、前期課程段階の開設を考える中で。","voiceIndex":184,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ後段のところの参考にして、今後のこと、子どもたちのことも踏まえて、スペースのことがあるかと思いますけれども、ぜひご検討していただきたいというのと、あと、新たに荏原平塚学園に固定級を開設するというところで、学級の配置の位置の問題で、前にも豊葉の杜学園ができるときに、できるだけ多くのクラスの子どもたちの交流を大切にしてほしいというところにおいては、学校の真ん中というか。","respondent":"大関教育総合支援センター長","answer":"学校の状況等も踏まえながら、なるべく孤立しないように、学校の中でも多くのほかの生徒と交流が進むような場所を選定してまいりたいと思います。","voiceIndex":186,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"もう１つなのですが、自閉症と情緒障害のところで、浜川が新たに固定級とするということなのですが、１校で十分なのですか。新しい制度が始まる、特別支援教室が始まっていく中での情緒と自閉症の子どもたちの固定級、１カ所で足りるのかどうか、その辺を聞かせてください。","respondent":"大関教育総合支援センター長","answer":"これまで自閉症・情緒障害特別支援学級、２３区内では、まだ２区しか設置がございません。なかなか保護者の理解も進んでいない実態もありますので、まずは１学級開設して、状況を見ていき、ニーズが増えていけば、当然、将来的にさらに増やしていく必要もあろうかと思います。","voiceIndex":188,"id":"exchange-074"},{"speaker":"高橋（し）委員","kind":"意見","question":"２つあって、１つ目は、それぞれの設置については、該当の生徒や保護者の方にとっては大変これからの学校生活でプラスになることだと思います。お願いしたいと思うのと、さっきの２３区で２区ということなのですが、区のほうで設置するということで、都との連絡調整みたいなところでは、どのようなやりとりがあってこういうふうになったのかお尋ねします。","respondent":"大関教育総合支援センター長","answer":"学校を通じて、近隣等も含めた保護者等へ説明、それから児童生徒への説明は、丁寧に行ってまいりたいと考えています。","voiceIndex":190,"id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校のほうの説明については、通級の状況と固定級では随分学校の様子が変わって、在校生から見た通級と固定級だと違いが出てくるので、そこのところを理解して説明を十分していただきたいと思います。都のほうはわかりました。ぜひ東京都との連絡・調整も充実したものにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"新しくなって看護師は配置されたのか、確認させていただきたい思います。","respondent":"吉田保育施設調整担当課長","answer":"看護師も配置されております。","voiceIndex":197,"id":"exchange-077"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"まだあります。品川の教育、児童福祉推進のために、チェック機関である我々議会、委員会の皆様に、思う存分にご意見を述べていただきたいとの思いから、結果的に長時間にわたる審議が多い委員会であったこと、また、その分、理事者や書記の方にご負担をおかけしたことを申しわけなく思っておりますが、１年間、ある程度の審議を尽くしたのではないかと、職責を終わるに当たりまして、若干ほっとしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":67122,"voices":209}},{"id":"h29-20170515-5","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"総務委員会","time":"午後 １時００分～午後 ３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"シティプロモーションの取り組み","agenda":"シティプロモーションの取り組み","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"すみません。ちょっと不勉強でごめんなさい。２番なのですけれども、３年目を迎えるというところで、この２年間やってきて２年間の予算と、あとどこへ何カ所に実際やって、それの効果はどのぐらいあったのかという評価をされているのかということをお聞きしたい。","respondent":"木村報道・プロモーション担当課長","answer":"今まで同様、助成事業その他範囲につきましては変更なく、申し出があればこちらのほうで検討してということで考えているところですが、繰り返しになりますが、今年度につきましてはそういう方法、インターネットの技術を使って周知をするというあたりの部分。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません。これは１５０万円だと、上限５０万円だと３件ということですよね。ずっとこういうものについて。イベントは１回１回だから、継続するといっても、イベントでもそういうことがあってもいいと思うのだけれども、そういう発想にはなぜ至らなかったのかというのと、あとは、今年の３件１５０万円と減額になったわけですよね。この辺のところの考え方というのを改めて教えていただきたい。","respondent":"木村報道・プロモーション担当課長","answer":"今やられていることでも、少しやり方を変えてとか、ちょっとこうだったからこうしていこうというところにも基本的には対象とするような形に考えておりますので、そこはそこで全く見ないということではございませんので。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうして３５０万円余あったものが、５００万円だった予算が、今年は１５０万円で３件という、新しいところも含めれば、また来るかもしれないではないですか。６件あったのだから。そこを今回は１５０万円で、これを見ると満額でも３件ですよね。そういうふうに減らしたというところの考え方を教えてください。","respondent":"木村報道・プロモーション担当課長、中山企画部長","answer":"実際に、昨年度実施した事業者の中でも、安価に運営をされた、安価に効果的に広くＰＲをしていただいたという方がおりました。予算のフレームのことでのご質問だったので、私の方から補足しますと、もともと５００万円で始まって、正直平成２７年度というのは時間も限られていて、イベントが主に出てきて。","voiceIndex":11,"id":"exchange-003"},{"speaker":"つる副委員長","kind":"質問","question":"実際に魅力発信の事業をやる期間となると、８月下旬から翌年の年度内３月３１日まで実施されるものという形になると思うのですね。例えば会場とかを借りてやるような、今、部長の答弁にあったようなイベント的なものですよね。やる側によっては、１年前とかでの契約だったりするわけです。逆に、その期間というのはなかなかできませんと言うのか、そのあたりを教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"ちょっとかたい答弁で申し訳ないのですけれども、そういう形で進めするというふうに考えております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"つる副委員長","kind":"質問・要望","question":"さっきの発信する時期が、一番いいベストな時期というのは、それぞれの季節によってとか、集客によってとか、いろいろあるのでしょうけれども、例えばさっき冒頭に言ったように、４月であれば新年度、５月であればゴールデンウィークとか、夏の始まりもという、そういった季節に合わせてのこういう魅力を発信するチャンスというのが、民間の力を活用する場合も多分にあるのだろうなと思う中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"すみません。私は１番のほうの目的のところに、「１０月開催予定の全国シティプロモーションサミットも視野に」ということが掲げられているのですけれども、具体的に、まず明日から募集をかけてということですが、何かそういう１０月に向けて盛り上げるような仕掛けを途中でやるとか、そういうことを考えられているのかどうか確認したいのですが、いかがでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"今ちょっとこの場では、なかなかこれをという形で、まだお伝えできない部分も正直あるのですけれども、もちろん、いわゆるそういうムーブメントを盛り上げていくという意味で、全国の自治体の職員、議員さんを対象に集めて来ていただくわけなのですけれども。","voiceIndex":19,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"そういうことを考えていらっしゃるのでしたら、次の段階としてこういう仕掛けを１０月のプロモーションサミットに向けて考えていますというようなご報告もまたしていただけるというふうに考えてよろしいでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"}]},{"id":"topic-02","title":"マイナポータルの運用開始","agenda":"マイナポータルの運用開始","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今かなりネットでもこのマイナポータル制度、制度と言うのですか、こういうシステムを、書き込んでいるいろいろなネットを見ると、否定はしない区と書いてあるところでも、いろいろ情報漏えいが現実的にいっぱいあるし、そういうことを１人１人がきちんと認識して対応していく必要があるというふうに書いてあるのですけれども、個人情報を使って利用していくということになるわけですよね。","respondent":"仁平情報推進課長","answer":"そうしますと、自治体間で情報のやりとりを、照会等をするわけなのですけれども、これはまた新しい仕組みを使い始めることになりますので、これの適切な運用、セキュリティ関係も含めまして、職員の研修のほうをきちんと行って対応をしていきたいと考えています。","voiceIndex":27,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"例えば、自分で外出をすることができない障害を持ってらっしゃる方、身体的な障害も含めていろいろ、そういう方々が自分の情報だとか自分に関するいろいろな手続きをこういうネット上でできるというところは、それはそれで利便性があるのかなとは思うのですけれども、しかし、それはそれであったにしても、そこだけを見てというよりも、全体的に見て個人情報というのが非常に出歩いてしまったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区に限らず。第一次的にどういう行動をとるべきか、第二次的にはどういう、次の対策としてどうすべきかという、そのことがあると思いますので、やはり情報が集約されていくということは危険性も増すということですから、その辺の対策というのも、事故が起きないことは前提としつつも、もし起きたときのというものが、ぜひ今後考えていただきたいなというふうに思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"やはりこういう情報化社会になって、こういうシステムも世の中の流れでやはりしようがない、必要性に迫られてきているのだと思います。かなりの利便性はもうどんどん、今回のこの例を見ても相当出てくるし、これから１００も２００も、それ以上すごい数の情報が簡単に引き出せるというような状況になってくると思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-011"}]},{"id":"topic-03","title":"平和首長会議","agenda":"平和首長会議","exchanges":[{"speaker":"南委員","kind":"質問","question":"宣言事業のレベルアップにつなげていくということなのですけれども、これが具体的にはそういう世論を広げていくという１つの取組みにもなっていっていいのかなと思っているのですけれども、そのあたり、具体的にこのレベルアップにつながっていくということを、ちょっと漠然としているので、具体的なことがあったら伺いたいと思います。３点です。","respondent":"米田総務課長","answer":"具体的にということなのですけれども、会議体は、これから情報をいただくのですけれども、いろいろ被爆体験者の話とかも幅広く、世界的な会議ですから、世界に皆さんが行って話をするわけにはいかないというようなことでは。","voiceIndex":38,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"私、被爆体験者の話をいうのが出たので、ちょっとそこだけ伺いたいのですけれども、被爆者ってだんだん人口的に本当に少なくなっていますよね。高齢になってきているから、当然だと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"},{"speaker":"吉田委員","kind":"提案","question":"予特で意見というか質問もさせていただきましたけれども、品川区で戦後７０周年を記念して作られたＤＶＤは本当によくできた３部作、ああいう形で、本当はあれだけのボリュームのお話を伺ったらもっといいのですけれども、みんなが見通せるぐらいの長さのＤＶＤで記録をしておくというようなこともすごく、やはり映像って違うかなと、文章とまた違って、本当に去年のあのお話はすごく私は胸に迫ったので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問","question":"今期の総務委員会で、委員会の総意という形でこの平和首長会議に品川区として加盟の手続きを行っていくということになったというのは、委員としても喜ばしい思いでいっぱいになるのですが、その上で具体的なところで１点だけ、加盟の手続きに今後入っていくと思うのですが、あと毎月そうした加盟都市数がいろいろ変わっていく中でも、手続きの具体的な部分はどういった部分で。","respondent":"米田総務課長","answer":"それで、インターネット上で加盟都市数というのが公表されているので、毎月１日に塗り変わって、その中でどこどこの自治体が入ったというようなことを踏まえて、発表された後にそれぞれの自治体のほうに、手続きが済みましたというようなことで送られてくると聞いておりますので。","voiceIndex":44,"id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問・要望","question":"わかりました。先ほどご答弁でもありましたけれども、これまでの非核平和都市品川宣言事業、本当に区としての取組みという観点を含めて、さらなるレベルアップと平和発信の区として頑張り続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-016"}]},{"id":"topic-04","title":"東京都議会議員選挙（品川区選挙区）における執行要領","agenda":"東京都議会議員選挙（品川区選挙区）における執行要領","exchanges":[{"speaker":"南委員","kind":"質問","question":"安全性の問題と、あとは準備しなければいけない、昔は自転車に乗ってやったりとか、台というのはもちろん押さえているのですけれども、そういうやり方をしていたときもあったけれども、ちょっとどうなのかなというのが心配で伺いたいなと思う、それだけです。","respondent":"安井選挙管理委員会事務局長","answer":"足もありますので、恐らくは植え込みでそれほど高くならないようにはしていくと思うのですけれども、そういうような形で、はめるような形で設置してまいります。","voiceIndex":51,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"すみません。ちょっと事実関係だけ伺いたいのですけれども、選挙人名簿への登録なのですけれども、学生の登録なのです。品川区の場合は、もう住民基本台帳で掲載かどうかは決めるということでよろしいのでしょうか。どうもそのときに。品川区の場合はどうなのかなと、それだけ伺いたいのです。あくまで住民基本台帳が基準と考えてよろしいですか。","respondent":"安井選挙管理委員会事務局長","answer":"基本的には住民基本台帳で見るというのが普通で、区もそんなに現場で全ての方を全部チェックするということはなかなかできませんので、まずは住民基本台帳を信用してやっていくという形にならざるを得ないというのが実態だと考えています。","voiceIndex":55,"id":"exchange-018"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"群馬県も出していますが、栃木県に関しては、危機管理のために宿日直の規定などをつくって、こういう場合に５月の連休なども職員の方が緊急時に備えて庁舎に来ていたと。こういうような動きをしてくれると、緊急時に備えて区もそういうような対応をしてくれると、区民もやはり頼もしいと思うし安心できると思うのですが、その辺についてどのようなお考えでいるのかちょっとお知らせください。","respondent":"米田危機管理室長","answer":"やはり大きな対応事項だということであれば直ちに参集して対応を図らねばならないというふうに考えているところですが、現状のところは報道以上のものが特に来ておりませんので、そういうところで情報としてはきちんと共有をしているというようなところです。","voiceIndex":59,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"それから対応するとなったら、実際本当にできるのですかという話にもなってしまう。それからあと、今、ホームページ内から情報をとってくださいということですけれども、やはり一般の方にはほとんど心の準備も、情報が入らないという状況なので、やはり町会の掲示板なり、そういうシステムがあるのですから、そういうところにやはり安心を持ってもらうために、私はやはり何らかの対応はすべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"１年間大変にお世話になりました。今期最後の本日の委員会において、先ほども申し上げましたが、平和首長会議ということで、総務委員会の総意、これは本当に大きな成果のうちの１つであるというふうに、私自身は副委員長としても思っております。区民の福祉の向上のためにこの総務委員会が筆頭委員会ですので、総務委員会のために尽力いただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2074#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26081,"voices":64}},{"id":"h29-20170516-14","meetingId":"h29-cm05","date":"2017年5月16日","dateIso":"2017-05-16","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"立派な本文計画そのものだと思うのですが、その辺も含めてまだできていないということだったのか、お伺いします。それと、策定にあたって、この間議論を庁舎内でも重ねてきたと思うのですけれども、改めて策定委員会のメンバー構成、人数と肩書を教えていただきたいと思います。それと、策定のための会議と、委員会なのですかね、何回行われたのか、どのようなことを話し合ったのかお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"討議といいますか内容ですけれども、それにつきましては、そもそもこの施設がどういった経緯であってどういう目的であるのか、施設の老朽度であったりとか今後の予定というものもお示しして、それをヒアリングという形式で受けながら。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、策定委員会は、アドバイザー３人の方それぞれの肩書を教えていただきたいのと、それと計画そのものの策定作業そのものは委託したのでしょうか。あわせて、この間パブコメなどの話もさせていただいたのですが、今回はパブコメに準じた形でやらせていただくということだったのですけれども、それが一定３月中に行われたと思うのですが、何か意見というのは届いたのでしょうか。","respondent":"柏原企画調整課長","answer":"これは長寿命化計画を既に持っております。今回この施設の総合計画ができ上がりましたので、これを踏まえながら更新といいますか５年目の見直しの時期に入りますので、住宅の部分につきましてはこれに基づいて今見直しの検討に入っているです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"パブコメのところは実態的には１件、しかも事業者の方だったということですので、やはり区民からの意見を伺いたいという姿勢がないわけですから、それが結果としてこのような実態としてパブコメに準じたものと言いつつ、ほとんど意見が届かないというところにつながっているのではないかということで私は思いますので、ぜひここら辺はちょっと反省していただきたいと思います。","respondent":"柏原企画調整課長","answer":"そういったところがありまして、こういう形にしなくてはいけないというのは、様式のところにはそれほど国はこだわっていないようなのですが、先ほどちょっと途中お話ししました、このＡ３判でいうところの２ページの方針のところで。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"それで将来の財源予測のことについて出ていますので伺いたいのですが、区の説明がここにも書いていますけれども、公共施設の修繕や更新等に要した経費実績がこの３０年間５４.９億円だったと。だから、将来は１年間に８０.８億円かかると。質問したいのですけれども、これからの８０.８億円の経費見込みに十分対応できるというのが今の品川区の現実ではないかと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですから、東京、特にこの２３区、品川区と地方の計画を見た際に、いずれもこの場で議論があったかと思うのですけれども、ちょっと置かれている状況が違うというところがありますので、一概に公共施設有効活用プランを発展的と言いながら。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"５２９億円から７９４億円と２６５億円も１０年間で増えたということで、もう十分やっていけるのではないかと思うのです。これは十分やっていけるのではないでしょうかということで、もう一度お伺いしたいと思います。そういったところで私は区は進んで市場に公務労働を提供したがっているように見えるのですけれども、区にはそのような考えがあるのかどうか、お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"ですので、考え方をＡ３判の２ページのところに書いてあるのですが、ＰＰＰ／ＰＦＩの項目のところに、その導入の適否を検討するための必要な手続きを定めますということで。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"これまでやっていたことをできるだけ民にやってもらって、その分浮いたお金は再開発なのか道路なのかわかりませんが、そうしたところにほかの施策にあてていくという考えなのだなということを今答弁を聞いて思いましたけれども、では、民間委託をして浮くのですか。伺います。これに関しての区の考え方というのですか、どう対応するつもりなのか。この点をどう解決していこうとしていくのか、お伺いします。","respondent":"中山企画部長","answer":"個別の今の質問にそれぞれ答える答弁にならないかもしれませんけれども、私の認識が違っていれば申し訳ないのですが、お金があれば効率・効果的な施設運営を考えなくてよいのか。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"それと、人口が減ったら施設を減らしていいかという考えでもありません。子どもがこれからちょっと減っていってしまうのであれば、むしろ減らすのではなくて、統合するのではなくて、きちんと少人数学級をやっていくことに踏み出すべきだと私は思いますし、私はそういった考えですので、ちょっと今部長が言ったような認識とは私の言い分の認識は違うということだけは申し述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここにも資料を出していただいて、毎回こういう話はしていて、６０年で建て替える、これは時間は来るわけですからお金のあるなし、当然それは関係があるにせよしっかりと計画を立てて、この先のことも行政需要も考えて進めなければならない第一歩を切ったわけなのですけれども、資料編がまだついていないということなのですが、１点確認は、資料編のところには基本的に全部一覧でこれが昔、四。","respondent":"柏原企画調整課長","answer":"今後の建物の考え方ですけれども、建物の寿命が今６０年とおっしゃっていただきましたけれども、そういったところで、それよりも前のタイミングで、これは個別の計画をつくる部分もあるかもしれませんけれども、比較的早いところで施設のありようというのを検討しながら。","voiceIndex":18,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"ご説明ありがとうございました。統廃合という言葉がいいのか悪いのかというのはちょっと別問題としまして、やはり行政需要というのは刻一刻と変わってきますので、しっかりとそれについていかなければならないわけですから、場合によっては本当に複合施設１つ大きいところができるのだったらつくって集約するとかさまざまな考え方。","respondent":"柏原企画調整課長","answer":"そういったところで区民サービスが遅滞したりとか滞らない、そういったところを見極めながら一定程度の蓄えは必要であると考えていますので、そういったところも蓄えながら抑えるところは抑えるというような行財政改革。","voiceIndex":20,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"私から３点ほどお伺いいたします。","respondent":"柏原企画調整課長","answer":"ちょっとそこにつきましては、今後それもあわせてなのですけれども、人口の伸びというのが推計以上の伸びが今出てきている部分がありますので、この人口推計につきましては、また改めた形で検討したいというのが今の状況です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"何点かお伺いしたいと思います。１個、機能としてはやはり重度障害とか精神障害の方々のグループホームとか中間施設とかまだまだ足りない機能というものはたくさんあると思うのです。そういったものは各種の計画の中で出てきていると思います。こうしたことについて区ではどうお考えか、まずその１点をお伺いします。","respondent":"柏原企画調整課長","answer":"具体的に計画をつくるか、それからどういった場でやるかというのは、まだ具体性のところでは今お話しできるレベルのものはないのですが、１つは今年度からやろうとしています長期計画の検証作業にこれから入っていくというところがありますので。","voiceIndex":24,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは要望です。それから、これも質問というか要望というか。３０年、５０年で使えなくなるような建物をずっとつくり続けていくのではなくて、当初のコストに若干上乗せしても、堅牢な建物をつくって機能もさまざまに時代のニーズに合わせられるような、そういう資産としての建物をきちんとつくっていくという考え方も私は必要ではないかと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"なので、その辺はよくよく検証、検討しなければいけないだろうとは思ってありますけれども、考え方というところで伺った中では、参考にさせていただきたいと思ってあります。","voiceIndex":26,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"今回、計画が策定されて、この資料の中にも施設の統廃合という部分がありますけれども、前回骨子の議論のところで３月１日の委員会でも課長の答弁で、「施設を充実されるための手法として統廃合がある」というお話だったのですけれども、統廃合が区民の福祉向上にどう向かっていけるのかというのが私は理解できないので、改めて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"一例といいますか、平塚橋の会館が今の形でいろいろ検討して、特別養護老人ホームであったりゆうゆうプラザであったり、別の機能として生まれ変わっているです。","voiceIndex":28,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"点検・診断のところで、そうすると全て既に把握はされているということですかね。その中で特に構造体の強度について詳細に把握していくということなのでしょうか。伺いたいと思います。このところはしっかりと慎重にやっていっていただきたいと思うのですけれども、そうすると施設は減らしてはいかないというか、活用していた土地は区の新たなニーズに活用していくということになるのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"別の近隣の施設の活用を促したりだとかというところをしてということで、全くそこを排するということではなくて、そういった方々のニーズも捉えながら新たなニーズにも応えていくというような手法を今までもとってきているです。","voiceIndex":30,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"個別の施設について伺っていきたいのですけれども、児童センターとシルバーセンター、どちらも転用と転換とあるのですが、これは２つを一緒の施設にして減らしていくということでは、今の答弁だとないということでいいのか確認させていただきたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、今の段階でどういった考え方に持っていくかというのはいろいろなご意見を聞きながら、これについては他の施設と比較検討しながら進めていくというものでございまして、具体的に何か今の段階でこうするというようなところの方針を持ってというところではないですけれども。","voiceIndex":32,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで今まで使っていた人が利用しにくくならないようにしていただきたいと思いますけれども、いかがでしょうか。それと、あと概要版で文化・スポーツ施設のところです。「振興に資する施設の可能性について検討する」とあるのですが、これはどういったことなのかちょっとイメージが湧かないのですけれども、お考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こういったところでいろいろな多機能として使えるような考え方を持っていきたいです。現に使っている方がいらっしゃいますので、こういった方々の利用の状態であるとかそういったところは十分考えながらどういった機能になっていくのかというのを検討するというものです。","voiceIndex":34,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、この資料でいくと、ご説明の内容が、今この表題の下に書いてあることを今ご説明いただいたのですが、そうするとこの（２）の表題のところの「統廃合」というところは、「統合・複合化」というふうにされたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"確かにこちらの表題のところとここの部分では「廃」という言葉が入っていないというところがありますので、この表記につきましてはちょっと検討しますが、用途転用であったりだとかこういった機能のところで。","voiceIndex":36,"id":"exchange-017"},{"speaker":"こんの委員","kind":"提案","question":"ご説明よくわかりました。この内容も先ほどのご説明でよく理解はしているところなので、整合性をというのでちょっと提案をさせていただきましたが。用途変更という形なので今までの機能は変更してなくなって、あるいはもっと機能を高めるという意味というふうなことであれば、やはり整合性を持ったほうがいいのかなと思ったので、もう一回ご答弁をお願いできますか。","respondent":"柏原企画調整課長","answer":"意味合いとしては、先ほどお話をしたとおりですけれども、ご意見をいただきましたので、全体の構成等と若干絡む部分がありますので、ちょっとその部分を検証させていただきたいと思います。","voiceIndex":38,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"概要版２ページですけれども、ＰＦＩのところですけれども、「手法の導入の適否を検討するための必要な手続きを定めます」とあるのですが、どのような手続きなのでしょうか。具体的にはどういうことなのでしょうか。人口を増やすということなのでしょうか、ご説明いただきたいと思います。どっちかをなくしてしまうよという考えなのか、そこら辺ちょっとはっきりお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"ＰＰＰ／ＰＦＩのところですけれども、これにつきましては、先ほどもちょっとご議論あったところですけれども、まずＰＰＰ／ＰＦＩの手法というのが使えるかどうかを優先的に検討しなさいというのが考え方です。","voiceIndex":40,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは意見です。ですから、これを国のほうがまず第一に検討しろと上からおろしてきたのでやっている面もあるとは思うのですけれども、区としてはこの手法を、今回具体的にちょっとさらに踏み込んで、こうした手続を定めますと言わざるを得ないところになってしまったと思うのですけれども、このＰＦＩという手法のどこに問題点や課題を感じているのか、いないのか、そこら辺だけ一点お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"これが一概に全部使えるかどうかというのはこれからちょっと見ていかなくてはいけないというところではありますので、必ずこれをやるということではなくて、必要な場面に区としては、最小限の経費で大きな効果、成果を出すという命題がありますので。","voiceIndex":42,"id":"exchange-020"}]},{"id":"topic-02","title":"のその他","agenda":"のその他","exchanges":[{"speaker":"本多副委員長","kind":"意見","question":"１年間取り組んできたことがさらに充実されることを願っております。さらに取り組む必要があると思います。いずれにしましても、１年間皆様のご協力に感謝いたします。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":39892,"voices":50}},{"id":"h29-20170517-18","meetingId":"h29-cm05","date":"2017年5月17日","dateIso":"2017-05-17","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ４時１０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員長","kind":"提案","question":"私から挨拶をします。この１年は本当に、自分の中でも大変多岐にわたり、充実した委員会運営ができたかと思います。その理由は、委員の皆様方のご発言やご提案が大変多かったこと。本当にありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":2461,"voices":9}},{"id":"h29-20170519-10","meetingId":"h29-cm05","date":"2017年5月19日","dateIso":"2017-05-19","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会改革推進会議等の設置","agenda":"議会改革推進会議等の設置","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"会派で協議いたしまして、こちらの提案のとおりで進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-001"},{"speaker":"須貝委員","kind":"確認","question":"私の会派では、反対です。今回、会議の運営に関しては「議会・委員会運営に関する申し合わせ確認事項」に載っている、また載せるべきものだと思うのですが、今回の議会改革推進会議の内容は、あくまで一過性のものだと思います。以上、我々の会派としては、反対ということで表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"},{"speaker":"須貝委員","kind":"確認","question":"ちょっと待ってください、委員長。この申し合わせ事項に載せるということは、議員全体、議会全体の申し合わせ確認事項ですよね。それをやはり全会派で賛成していない以上、私は載せるのは筋違いだと思います。ならば、あくまで賛同できる委員、賛同できる会派が出席する、参加するというのが、私は議会のやり方として、また、筋道ではないかと思うのですが、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"いや、和らいだと言っても、入っていますよね。幹事長どうのこうのという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"提案","question":"認識の違いがあると思うのですが、申し合わせ確認事項は、今までずっと積み上げてきて、ご提案もあって、最終的には、私も原則は全員、皆さん、賛同していただいて申し合わせ確認を直していくというのは、あくまでそれが原則でありまして、今までずっとお話をしてきて、全員参加でこういうことをしていきましょう、議会改革を２年間やってきた中で、継続していくこともある。","respondent":"鈴木（真）委員長","answer":"もう１点、先ほど、幹事長が出席というお話をいただきましたが、前回配られた資料、設置についての４項目の中に、そのような要件は入っておりません。","voiceIndex":28,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"私が勝手に何か目に触れてしまったのかもしれないです。一応、原則論ということを、それだけは確認をさせていただきたいと思います。やはり我々としては、３人とも賛同できないということなので、原則として進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"よくお話を聞いていただきたいのですが、別に反対をされることに対して、それは個人のご意見ですから、我々はどうのこうの言っていることでもないし、申し合わせ確認事項が、原則、全員賛成をするということは原則論でありまして、そういうことも多分、須貝委員はおわかりの中で、反対をする中で、今、賛成多数で諮ろう、ここまで来て議論を尽くした中で諮ろうという中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"この中でメンバーが出てくるわけでありますけれども、会派の中でもメンバーを決めていくという形を考えると、今、上の部分がありますけれども、リーダー・サブリーダーについては、この割り振りでやっていただいたほうが人選をするにもいいと思いますので、そういう形でお願いできればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":8182,"voices":40}},{"id":"h29-20170525-10","meetingId":"h29-cm05","date":"2017年5月25日","dateIso":"2017-05-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議事日程（１）、追加議事日程および追加議事日程（２）","agenda":"議事日程（１）、追加議事日程および追加議事日程（２）","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"監査委員の選任同意につきまして、この後、採決の方法について態度を示す関係もありますので、提案者からの説明について若干伺いたいと思うのですけれども、今回の選任したい理由は何か、また共産党を選ばないという考えがあるのか、説明を聞いていましたら伺いたいと思います。","respondent":"久保田区議会事務局長","answer":"こちらにつきましては、区長から選任同意の議案のご提案があったということで、詳しい理由につきましては、私どもでは聞いておりません。","voiceIndex":14,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"今の点については聞いていないということですけれども、もう１点、従来は第３党が監査に選任されていたという経過が長年あったと思いますけれども、共産党が第３党になるとこれを変えた理由について、何か伺っているのでしょうか。質問したいと思います。","respondent":"久保田区議会事務局長","answer":"第３会派だというような決まりはございませんので、これはあくまでも区長からの議案としてお預かりしているということでございまして、第３会派から監査委員が出ていたということではございませんので、ご報告します。","voiceIndex":16,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"従来の流れを見ておりますと、第３会派が選任されていたという経過がありますので、ご質問させていただきました。選任同意について、ぜひ質疑の場が私は必要ではないかと思いますので、その点は意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"もしそれがないならば、議会で皆さんに問うて、立候補等をしていただいて、それで皆さんでまた選んで、妥当なものだということならば、それを区長にお願いして、我々に選任同意を求めるという筋をきちんとしないと、いきなりこの方が選任同意を求められますというのは、ちょっと違うのではないかと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"それで、逆に、監査として私がやりたいという方もいると思いますので、そこは区議会としても、そういう方を逆にこちら側から事前に推薦するとか、そういうルールも今後必要になるのではないですかという意見だけ言わせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどお話はしたのですけれども、今回はこういう形で、選任同意という形で区長から求められましたけれども、今、中塚委員の言うような意見もありますので、そこは是正していくように、区議会としても私は考えていくべきかと思います。今回に関しては、これに対しては同意します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"そのときの石田議長の功績は本当に立派なものだと思います。ですから私は、その使い方をきちんと区議会で決めた以上、それに沿って議員一人一人もやっていくべきだと思います。ぜひ、議長を含めていろいろ大変だと思うのですが、その正論だけは歪めないでやっていただきたいと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":11466,"voices":66}},{"id":"h29-20170526-5","meetingId":"h29-cm05","date":"2017年5月26日","dateIso":"2017-05-26","committee":"総務委員会","time":"午後 １時０４分～午後 １時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３８号議案、品川区特別区税条例の一部を改正する条例","agenda":"第３８号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"自動車製作者の不正に対する処置ということで、軽自動車税の賦課徴収に関し、納付すべき不足額が生じたときに、こういうふうに対応していくという新しい法改正ということで、私は賛成します。これはやらなければいけないことだと思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"自動車製作者による不正行為ということですけれども、一般的な言い方をしているわけですが、具体的にこれが発生するより、こういう処置をとらなくてはいけないと判断したのはどういう状況があったのか、改めて伺いたいというのが１つと、同じような出来事というのは過去にあったのかどうか、その辺と、品川区で不足額はどのくらいの額になるのか、その３点を伺いたいと思います。","respondent":"伊東税務課長","answer":"そういうことを踏まえまして、このたびの改正がされたです。過去のことですけれども、品川区におきましては昨年の影響によりまして、総額で１９万４,４００円ほどの不足が生じたです。それに関しては、昨年の１２月の段階で全て完納をしております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"予想していた額より随分、額的には少ないので、それはそれとして伺っておきたいと思います。同様の事例があったのかどうかということも聞いたつもりですけれども、その点と、メーカーの名前というのは、私もテレビでこれは明らかになっているのですけれども、改めてこういう場ではっきりと伺っておきたいことかなと思いましたので、差し支えないと思いますので、ぜひ教えてください。","respondent":"伊東税務課長","answer":"同様の事例ですけれども、昨年のことは別として、過去にはありません。メーカーですけれども、昨年の不正に関しては、三菱自動車ということで新聞報道もされております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"今、環境負荷が軽減されることもあるし、環境に対して優しい車であってほしいとみんなが共通に思うわけで、そういう開発がされた車種だということを信用して導入するわけでありますので、不適切なそういうことを名乗って購買力を高めるということであったとしたならば、本当に許されないことだと考えていますので、そのことは申し上げておき、こういうことのないように、そういう社会の仕組みをつくって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"品川区民の方。個人の方に案内を出したのか。もしそういうことが起きたら、所有者に１回案内が行くのか、それともメーカーの車の台数というのがわかるから、直接メーカーに例えば請求してしまうのかとか、具体的にどういうふうに動いて、なおかつこれが可能になったかという、今回も特にだけれども、今後も、これがもし生じた場合はどういうやり方でやっていくのかというのを教えてほしいです。","respondent":"伊東税務課長","answer":"昨年の状況ですけれども、うちの課税情報をもとに、不正車種から税額を再度算出しまして、それで変更の賦課決定をしたわけです。それに伴って、そもそも所有者が納税義務者ということでありますので、そちらの方にその旨の通知は出しています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"よくわからないのですが、こういう場合というのは、例えば１,７００ぐらいの自治体があって、今回の場合は一斉に同じ扱いをしたのか、今度こういうのができれば、多分一斉にということなのだけれども、今回はメーカー側も、自分のところでもそういうのがわかっていたから、例えば台数もわかっているだろうし、１,７００自治体のそういうのも全部、全ての自治体が同じようなことをして。","respondent":"伊東税務課長","answer":"メーカーの今回の対応ですけれども、どこまで全く同じような形になったかというのはわかりませんが、ほぼ同じような形でやられたと聞いております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"だから、所有者の方にどういう影響が引き続きあるのかということと、それから、ごめんなさい、これはその他のところで、単によくわからないのですけれども、「当該第三者に対して当該不足額に係る軽自動車税の納付を申し出る機会を与えることができることとする」というのは、具体的にどういう場面の想定なのか教えていただけますか。","respondent":"伊東税務課長","answer":"その他のところですけれども、これは過去というか、平成２８年度以前の、仮にこれから過去の分として発生した場合に、いきなり所有者に、こうですから払ってくださいということではなくて、その前にメーカー側に、こういうことがあるけれども、メーカーさん。","voiceIndex":17,"id":"exchange-007"},{"speaker":"大倉委員","kind":"確認","question":"１点確認で、納付される場合は、今の話の流れでわかったのですが、例えば納付し忘れてしまった方がいた場合は、これにきちんと該当して、不足分はメーカーが補って払ってもらえるのかというのは、納付忘れがあるかどうかわからないのですけれども、例えば納付してくださいという通知が来て、払い忘れていたときに、これは払い忘れていたけれども、これからの条例改正の部分でどうなるのかという。","respondent":"伊東税務課長","answer":"今回の特例を創設させていただければ、納付忘れといいますか、メーカー側に請求といいますか、賦課しますので、通常の納付忘れに関しては、所有者に対しての督促の際は行わない、そういうことになります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"大倉委員","kind":"確認","question":"ごめんなさい、聞き方が。納付を例えば今回忘れてしまっても、特段、課税がかかった部分にお金は改めて払う必要がないかという確認なのですが、ないということでいいのか。","respondent":"伊東税務課長","answer":"はい、そこの部分に関してはありません。大丈夫です。","voiceIndex":22,"id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"単年度、メーカー側が不足分を払う。それはそれで当然だと思うのですけれども、環境に優しいはずだったのに、そうではなかった自動車の性能が、ずっと悪いまま使用し続ければ、そういう状態で使用するわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"ユーザーが使い続ければ、環境に関して非常にダメージを与えるという状況が続くわけですから、そういう点で、今回この不足額は払ったよということで、世間的にというか、税の負担については免除されたにしても、社会的な責任というのは免れないと思うのですけれども、その点についての、二度とこういうことをさせないということも含めて、しっかりした規制というか、国なり自治体から。","respondent":"榎本総務部長","answer":"それで、これについては社会問題化すれば、当然メーカーに対しては賠償する責任、追徴する責任等がありますし、風評の関係で販売は当然落ちるという形になりますので、そういった意味で、ユーザー側もどういう車を選ぶかという目をしっかり見るとともに。","voiceIndex":26,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"だって、改ざんしているのですから、見抜けるはずがないではないですか。行動的にも資料的にも、数字を信用して買うわけですから。そういうことはだめだというところは厳しく、いろいろな機会を通じて、環境を守るというところと、企業の社会的責任を果たさせるというところを強調する、そういう認識が必要かなということを、改めてこれを機会に広げていく必要があるなと思います。最後は私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2076#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":6449,"voices":41}},{"id":"h29-20170526-10","meetingId":"h29-cm05","date":"2017年5月26日","dateIso":"2017-05-26","committee":"議会運営委員会","time":"午後１時４６分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1118,"voices":11}},{"id":"h29-20170612-6","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"区民委員会","time":"午後１時００分～午後３時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"民進党・無所属クラブのあべ祐美子です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"概要と方向性について２つだけ伺いたいと思います。それと戸籍住民課の民間委託の問題ですけれども、簡単に改めて、大井町サービスコーナーの民間委託を導入した目的、そして将来的には庁舎の戸籍住民課についても導入を検討したいという説明が、この間ありましたけれども、実施するに当たってどういう条件が整ったと判断したら踏み切るのか、これについての条件についても伺いたいと思います。","respondent":"伊崎地域活動課長、提坂戸籍住民課長","answer":"地域センターの位置づけ、主に防災という視点からです。荏原第四地域センターの関係につきましては、３階に備蓄倉庫の設置、それから蓄電池の設置ということを計画しております。本庁舎の民間委託については、大井町サービスコーナーの民間委託ですとか、あとは目黒のサービスコーナーについても来年度から委託を今、準備を進めているところですが、その辺の運用状況を見極めつつ。","voiceIndex":37,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"事務事業概要なので大きくお伺いしますが、まず商業・ものづくり課の説明で、ボリューム的に言っても、枚数的に言うと文化スポーツ振興部と同じぐらいあるではないですか。私は、産業振興課というのが前にあって、そのときは課長がお一人だったではないですか。２つの課を１つにしてまでという思いがあるのですけれども、その辺について、これから１年やっていくわけですから教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つのテーマだけ、文化観光課の品川歴史館について今後考える概要を伺いたいのですけれども、つまりは都市型観光を今始めておりますけれども、ここにかかわって品川歴史館の役割や位置づけをどう考えていらっしゃるのか伺いたいと思います。今後の歴史館の強化・充実について方向性を持っているのか。","respondent":"鈴木文化観光課長","answer":"合わせまして２点目の今後の活用等につきましては、近くにある大森貝塚、先ほど申し上げましたように１４０周年というようなこともありますので、貝塚と連携をしながら活用することで。","voiceIndex":53,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"歴史館そのものに大勢の方がいらっしゃるということは大事なことだと思いますけれども、品川全体の文化や積み上げてきた歴史、その全体の掘り起こしという役割も、この課は担っていると思うのですよね。そういう位置づけについてもう一度お伺いしたいのと、そのために向けた常勤化というのがまた大事なテーマになってくると思いますので、そこの点については要望したいと思います。","respondent":"鈴木文化観光課長","answer":"区全体の歴史を保存したり、また区民の方に知っていただくという重要な機能については、今後も変わらずしっかりと取り組んでいく必要があるというふうには考えておりますので、そのことも含めて現在検討しています。","voiceIndex":55,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"それともう１点だけ。オリンピック・パラリンピックなのですけれども、機運という意味においては、予算特別委員会でも伺いました品川区の施設等の塀、壁に写真を、どういうふうにやっていく、載せていく、写真と言うのですか、あれはすばらしいですね。ただ、ちょっと寂しさを感じるのは庁舎の３階。機運醸成に向かってどういう気持ちで課長はやっていきたいと思っているのか、その辺を答えていただけますか。","respondent":"鈴木文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"ただし、神社等のお祭りを中心に地域全体でイベントに取り組んでいただいて、地域のにぎわいであるとか、よそから来訪者の方をたくさん来ていただいて楽しんでいただくという部分については観光の視点ということで。１点目の、区内の工事中の壁を活用した３競技の写真の展開ですが、現在なぎさ会館の所と、それから役所を出てすぐの所にやらせていただいているところで、まちづくりのほうと連携をしながらそういった工事中の所などをチャンスと捉えて。","voiceIndex":57,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"今後、振り込みなど時間が自由になる形でこの手続きができるような体制をとっていただきたいと思うのですが、区としてはそのような考えがあるかどうかということ、なければぜひご検討いただきたいと思うのですが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"例えばの話では、コンビニでのお支払いができないかとか、あと利用時間について、受付はもう少しできないかというようなことも含めて考えているところですので、今以上の形で、区民の方にとって利便性が高まるようなシステムにしたいということで検討しています。","voiceIndex":60,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"それを聞いてとても安心いたしました。スケジュール的にいつ頃を目途というのがもしあれば教えてください。","respondent":"池田スポーツ推進課長、本多委員長、伊崎地域活動課長","answer":"予定といたしましては平成３１年１月に稼働したいという目標で動いているところです。ほかになければ以上で事務事業概要を終了いたします。お配りいたしました平成２９年度品川区民まつり予定表をご覧ください。今年度におきましては、例年どおり７月に各地区での区民まつりが行われます。","voiceIndex":62,"id":"exchange-008"}]},{"id":"topic-03","title":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","agenda":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"現在の指定管理者がどこかということと、今回、簡易型プロポーザル方式（公募型）に切り替えた理由について、きゅりあんと同様ということですけれども、それだとちょっと理由がよくわからないので、その簡易型プロポーザル方式（公募型）にした理由をもう少しご説明いただきたいと思います。","respondent":"鈴木文化観光課長","answer":"きゅりあんと同様に選定方法を変えた理由ですが、資料の４番の理由の所にも記載しておりますように、当初は、新しく施設を設置したばかりのときは、運営形態だとかより効率的なノウハウというものがございませんでしたので。","voiceIndex":72,"id":"exchange-009"},{"speaker":"塚本副委員長","kind":"提案","question":"今の、今回は公募、簡易型プロポーザルということで、選定基準というのがここに1)～5)とあるのですけれども、これはいわゆる今までよりも区として期待する指定管理者のいろいろな提案というのですか、そういうところでのプロポーザルする特徴というか期待するところ、応募してくれる候補者に期待するところというのはどういうものがあるのか、教えていただきたいと思います。","respondent":"鈴木文化観光課長","answer":"それともう１つは、先ほど申し上げましたように自主事業も可能ですので、いかにうまく収益を上げながら、より区に、もしくは区民の方に還元できる事業運営なり施設運営ができるかというような視点が中心になるというふうに考えております。","voiceIndex":74,"id":"exchange-010"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"これは前年度の区民委員会の最終回だったと思うのですけれども、ＤＶ被害に関わって情報を出した件について、品川区自身は謝罪をいたしましたけれども、これは重大な問題だと思いますので、区の対策はなぜ数年後になったのか、あとどうして失念という事態が起きたのか、この辺について明らかにする必要があると思いますので、戸籍住民課の個人情報保護についてというのが１つです。この２点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"意見","question":"大きく大項目で２つかなというイメージを持っています。都市型観光の推進。これはもう流れと街の施策、他の連携の施策でも、来訪者をおもてなすというか区内でどう活用というか、日常生活にどう反映していくかというか、継続的でなおかつ年々変化も多いので、この年度の所管事務調査でも都市型観光、これをキーワードにやるべきかなと思っているのが１つです。もう１点が国際交流。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"提案","question":"視察先２点。唐津でもう１点、歴史ツーリズムというのも１つ引っかかりまして、とてもメジャーな所ではない土地柄の中でいろいろ発信をしていこうと、歴史資源がすごくメジャーではないのに発信力をつけていこうとしている姿勢が、何となく親近感を持ったというか、親しみを持って提案したいなと思います。もう１点、土地的には離れるのかな、伊勢市。ここでスポーツです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"私は視察に関しては、まず所管事務調査を深める立場で、内容を、特にふさわしい視察先を選ぶのがいいのかなと思って。今回ちょっと委員会の日程上で同時に進んでいるという、その状況はあったにしても、今後正副で調整していく所管事務調査、このテーマに沿った中身がよいのではないかなというのが１点と。","respondent":"本多委員長","answer":"その後、所管事務調査等を正副で検討させていただき、同時に進めていきたいと考えています。６月１６日金曜日までに、ありましたらお出しいただければと思います。続きまして、日程について確認をします。","voiceIndex":93,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2782#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":54948,"voices":95}},{"id":"h29-20170612-7","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"厚生委員会","time":"午後１時００分～午後４時０４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護保険なのですけれども、介護保険は第七期の計画をされるということで、第七期を計画するに当たってのスケジュールがどういうスケジュールになっていくのか。そして、総合事業にかかわって、１点だけ、要支援相当ということで、認定を受けずにサービスを受ける総合事業対象者ということになると思うのですけれども、その人数だけ教えていただきたいと思います。全部聞いてしまったほうが良いですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"毎回この問題をやっていて、個々の問題が出てくるということですけれども、今この時点で確かめておきたい、そして、次に出てきたときにはさらにそれを踏まえて深めていきたいという思いで聞いているのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"続けて、障害者福祉なのですけれども、障害者福祉では、今年、障害児福祉計画を３年ごとにつくるということで、来年度からの障害児福祉計画をつくるということになっていくと思うのですけれども、そのスケジュールというのがどうなっているのかということと、改めて障害児福祉計画を見たときに、ＰＤＣＡサイクルということになっているということなのですけれども、これは１年に１回以上、実績を把握して。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長、飛田障害者施策推進担当課長、三ッ橋国保医療年金課長","answer":"したがいまして、来年８月ということで報道されております３割負担の人数につきましては、今の段階では余りにも変動要因が多うありますので。住民主体のＢにつきましても、今、モデルとして実施しているのですが、今年度、それぞれそちらのほうを来年度に向けて。そこのところを受けまして、２月の第３回自立支援協議会のほうで計画の承認を受けるというような予定で考えております。最後に、広域化の件ですけれども、先ほど事務事業概要の説明のときにも申し上げましたとおり、国や都の動向を踏まえ。","voiceIndex":61,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎回の国保運営協議会の中で、仕組みそのものが皆さんわからないということを言われているのが、この間の数回の特徴だと思っているのですけれども、そういう点では、この制度そのものの、説明のときに制度そのものがわかるような形の説明というのももちろんあるのですけれども、こういう制度ですという新しくなるに当たっての学習会みたいな、そういうのもここの委員会でも。","respondent":"松山高齢者地域支援課長、寺嶋高齢者福祉課長、飛田障害者施策推進担当課長、三ッ橋国保医療年金課長","answer":"先ほどの２２ページの実績のケアプランの総合事業につきましては、総合事業を受ける方のケアプランをつくっているので、こちらにつきましては。制度推進委員会の件ですけれども、あくまでも今の段階の予定ということにはなりますが、全体のスケジュールから考えますと。障害福祉計画と障害児福祉計画の件です。自立支援協議会の中で今回諮っていきますので、新たな協議体の設置は考えておりません。","voiceIndex":66,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護保険は本当にずっと３年ごとの計画ということで、大変国のほうの制度改悪もあって、なかなか厳しい状況というのがありますけれども、そういうのがぜひ区民の状況も反映して議論できるような場をつくっていただきたいということで要望します。最後に、私は総合事業の対象者、この人数が何人ですかと、一番初めの質問がそれなのです。","respondent":"飛田障害者施策推進担当課長","answer":"現在は公開はしておりません。","voiceIndex":71,"id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"成人歯科健診のことについて伺いたいのですが、私、ずっと成人歯科健診の年齢、対象拡大を求めてきまして、今回２０歳から、５歳刻みですけれども進んでいくということで、この事務事業概要のほうに、６月１日から実施期間ということで、始まったばかりだと思うのですが、これに当たって、いつからどんな形で若い世代に成人歯科健診の対象ですよというＰＲ、周知というのをしてきたのか伺いたいのと、あと。","respondent":"川島健康課長","answer":"障害者歯科健診のほうなのですが、実施医療機関については、こちら、現在、何か一覧表を見てここに行くというふうな形での受診ではなく、歯科医師会のほうに問い合わせいただき、そちらで紹介されたところに行くという仕組みになっているので、少し利用者の方にしてみると。","voiceIndex":73,"id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"対象者は、要は、受診券を郵送した数ということになるのではないのですか。その総数がわかれば教えていただきたいです。","respondent":"川島健康課長","answer":"対象者数ということで、受診券を送った数ですが、平成２８年度が３万５,５００件で、平成２９年度、今回送る数というのは今手元にはないです。申しわけございません。","voiceIndex":75,"id":"exchange-007"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"品川区議会自民党・子ども未来は、この提案に沿ってなのですけれども、総合事業に関することということで、テーマを挙げました。そして、福祉計画課、高齢者福祉課、高齢者地域支援課、この３課にまたがった部分もありますし、先ほども他の委員の方、先ほどの事務事業概要の中でも総合事業という言葉が出ていましたけれども、この点、私ども会派としては必要性があるということで、この判断をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"この支え愛・ほっとステーションとか、それから、今、去年ですかね、システムとして一応進められた医療連携のシステム、こういう一つの事業を１つ２つ取り上げて、あと、同じ考え方で障害者の相談事業についても、いわゆる在宅支援、生活支援という障害支援、就労も含めてあるのですけれども、そもそも相談とケアプランというのが、どういうふうに相談をされ、それを受けて、介護と一緒ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"障害者福祉の問題では、障害者福祉も本当に今大きな変わり目で、障害者権利条約が通され、障害者差別解消法ができて、本当に全体としても大きく改善が求められているところだと思うのですけれども、そういうところでどうあるべきなのかというのを調査研究ができればいいなということで、提案をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-010"},{"speaker":"大倉委員","kind":"意見","question":"ほかのところでも他課との連携という部分は結構重要な部分であるのかなというのを、今勉強している中で感じたので、これを書かせていただいたのと、その中で、２となっていますけれども、高齢者支援体制については、公明党の中にもあるように、支え愛・ほっとステーションも全地域に設置がされたという部分で、そういった部分を受けて、高齢者の生活支援体制というのをもう一回どこまでできるのかという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"委員会として提言のような形で、それをまとめて行政のほうにお示しするというような、そういう所管事務調査ということは私としても考えていません。結構、視察に行って、これはよかったよねというような、そういう中で、やはりこういうところは品川区としても検討していただきたいというものは結構この委員会の中でもまとまるような部分というのも確かにあったりするのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3478#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":61966,"voices":93}},{"id":"h29-20170612-8","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"建設委員会","time":"午後１時００分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認です。やはり近年、他課との連携事業が増えてきているなと感じるのです。その中で、今後、部内であれば調整可能なのでしょうけれども、部外という話が来たときに、調整をどうされるのか。それと、今後、委員長仕切りになると思いますけれども、部がまたがった場合も、計画実行の仕切りというか、まずは委員長がされて、実際はどういう形で仕切りをしているのかというのを教えてください。","respondent":"松代防災まちづくり部長","answer":"そういった意味では、観光分野に大きく関連するところです。そういったところも、今後連携を図りながら、しっかりとご説明をし、齟齬がないような感じで進めたいと考えています。","voiceIndex":52,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"お願いなのですけれども、それぞれの担当がありますので、同じ事業であっても、ここはこの部署、ここはこの部署となると思うのですが、説明は説明で委員会はまたがってしまうとは思うのですが、そこは全体像がわかる形の説明をお願いしたい。共通的なところは、やはり関係部署には説明いただきたいなと思っているのですか、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"都市計画課と住宅課についてお伺いしたいのです。都市計画課のほうは、東京都の事業で、ほかに聞く場面がないのでお伺いしたいのです。区はどういう姿勢なのかというのをお伺いしたいのが１つです。マンションの建設ラッシュで公共インフラ不足の対応というのは、まちづくり全体にかかわることなので、どう考えるのかなというのをお伺いしたいと思います。直近の状況を伺いたいというのが１つ。","respondent":"中村都市計画課長、長尾住宅課長","answer":"しかし、この道路の整備に向けましては、東京都と連携して進めていくということで考える中、品川区としては、今道路の沿道の不燃化のために防火の規制をかける、あるいは防火の建物の建替えがしやすいように容積率等の見直しを行うなど。２点目のご質問に関しましては、建築紛争調整事務の中の中高層建築物の紛争予防のお話かと思います。現在、中高層建築物の紛争を予防するために、事前に標識の設置および説明会の実施を建築主の方にしていただいているところです。","voiceIndex":60,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"よくわからなかったので、そこをもう一回だけ、どういう意味だったのか、もう一度ご答弁いただきたいと思います。都市開発課と防災まちづくり部についても幾つかお伺いしたいのです。区の評価を伺いたいというのが１つです。もう一つ、２９ページです。その具体的な工事に際しての問題に対しての区のかかわり方でもあると思うのですけれども、その両面について、区のスタンスをお伺いしたいと思います。","respondent":"中村都市計画課長、東野まちづくり立体化担当課長、稲田都市開発課長","answer":"したがいまして、区としましては、防災上必要な道路についての整備がスムーズに、速やかに進むことを願っているところですけれども。まちづくりを全般的に考えたときに、部としての体制、課としての体制の中で。２２ページを開いていただきますと、委員ご指摘のまちづくり整備手法の検討の部分なのですけれども。","voiceIndex":63,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"五反田については、１７ページの説明が単純にわからない。区は、結局何を要請するのか、お聞きしたいと思います。すみません。先ほど忘れてしまったのですが、防災まちづくり部について２点だけお伺いしたいのです。上流の区の現状を含めて、この対策を加速していくべきだと思うのですけれども、東京都からいらっしゃっているということもありますので、現状と今後をお伺いしたいと思っています。","respondent":"稲田都市開発課長、古巻防災課長、持田河川下水道課長","answer":"そういう意味で、日本郵政には、まちづくりの中におきまして、文化的なもの、それから、それをもって。その中に、防災対策に関する考え方というものを定めております。そちらの理念にのっとりまして、今後も災害対策を進めていきたいと考えております。目黒川につきましても、立会川につきましても、この後のさまざまな取組みをしながら、少しずつ改善していこうという考えがありますので、今。","voiceIndex":68,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"防災まちづくり部の事務事業概要の資料の１０４ページの国民保護のところについてお聞きしたいのです。今年度の動きは全くないのかということが２点目です。３点目として、いざ有事の際は大変な仕事になるかとは思われます。これが防災安全担当のみで賄えるのか。ひいては、他の課との連携はお考えになられていないのかということが３点目です。以上３点、ご回答のほど、よろしくお願いします。","respondent":"曽田災害対策担当部長","answer":"実際のところ、国民保護計画につきましては、つくってからしばらくたっておりまして、組織改正などに対応しておらず、改訂をしなくてはいけないなというところであります。国の方針が大きく変わっておりませんので、まだ改訂には至っておりません。","voiceIndex":75,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"今年度は、国の動きを待って、それから行くということで、今年度は予算もないということで、国の動きを注視して、それに合わせていくということでよろしいのでしょうか。","respondent":"曽田災害対策担当部長","answer":"はい、そのとおりです。","voiceIndex":77,"id":"exchange-007"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"開発の２７ページの立体化についてお伺いしたいのです。それで、今、戸越公園という話なのです。このために立体化担当課長がいるのか、それとも今後の品川区のまちづくりのために、これから先、踏切があるところはなくしていこうかななど、限定的なものなのか、それとも長期にわたっての立体交差のビジョンなのか、その辺を教えていただきたいのです。","respondent":"東野まちづくり立体化担当課長、松代防災まちづくり部長","answer":"長期的に全体をというところにつきましては、今のところ、全体をどうするということはないのですけれども、私どもは、その２路線につきまして、まちづくりと一体的に進めていくという課です。今言いましたような、立体化というのは、非常に莫大な費用と時間を要します。加えて、区単独事業では非常に難しいところで、東京都での連携をもって進めるというのが、これまでの一番進めやすい形で進めてきたところです。","voiceIndex":82,"id":"exchange-008"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"ただでさえ、今、急行が走るようになって、踏切の遮断回数が増えてきて、朝はなかなかすれ違えないところをみんな抜けていくので、本当に３０分とか１時間の間なのですけれども、そういうことを考えること、品川区全体のまちづくりを俯瞰したときに、細かい部分なのかもしれないですけれども、そういうものも視野に入れて、鉄道がどうあるべきかというのも、ぜひ考えていただきたいなと思って質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-009"}]},{"id":"topic-02","title":"平成２９年７月区営住宅入居者募集","agenda":"平成２９年７月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"お一人暮らしの高齢者の方を中心に、こういう低廉な住宅に対する要望というのは強く感じているのですけれども、２点だけお伺いします。広報しながわには載せるということは書いていますけれども、私の記憶違いというか、忘れてしまったのですが、例えば掲示板に張ってある７月のしながわというポスターみたいなところでも掲載したほうがいいのではないかなと思うのですけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"窓口でもお問い合わせがありましたら、募集の時期でなければ、一般的な対応としてお伝えさせていただいている状況です。ポスターへの掲載等につきましては、それに限らず、区民の方への周知については、いろいろ状況を踏まえながら工夫していきたいと考えております。","voiceIndex":92,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"応募されている方の現状については、どれだけ困っているのかという区民の実態も見えてくると思うので、可能なのかはわからないのですけれども、どういった方が本当に苦労して何回も応募している方がこれだけいるのだとか、あるいは新規なのか、何回応募したことがあるかというのは、ぜひ把握していただきたいというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-011"}]},{"id":"topic-03","title":"平成２９年度品川区電力節減方針","agenda":"平成２９年度品川区電力節減方針","exchanges":[{"speaker":"西本委員","kind":"確認","question":"２点だけ確認です。毎年節電をされているのですけれども、いろいろな部署にまたがっている中で、最終的にデータ等についての集約は、環境課が取りまとめるという形でよろしいのでしょうか。毎年、方向をつけて、全体的な動きになってくると思うのですが、そこのまとめ役は環境課という認識でよろしいですか。","respondent":"小林環境課長","answer":"データの集約ですが、毎月、各課からデータを集計いたしまして、環境課で取りまとめて、最終的に何％だったかということを公表しています。","voiceIndex":99,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"それと同時に、権限というのは、どこまで権限があるのですか。例えば、ここはあまり節電されていなかったね。もう少し何とかしなさいとか、対応しなさいという権限というのは、環境課にあるのでしょうか。","respondent":"小林環境課長","answer":"今回の削減方針にもありますように、暑ければ区民の皆様への影響等もありますので、そこまで絶対下げろというところではございません。やはり節電というのは非常に大切なところですので、強制力はないにしても、努力は続けてくださいということで指導はあります。","voiceIndex":101,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"２の(3)の「区民サービス低下」ということです。そうしたときに、そういうところはこのぐらいの節電をしましょうという、一律ではなくて、一律でマイナス１５％と言っていますけれども、目的によっては、このパーセンテージは変わってくるのではないかなと思うのです。施設によっての細かい節電のあり方を検討していただけるものなのか、しているのか、いかがでしょうか。","respondent":"小林環境課長","answer":"委員ご指摘のとおり、１つ１つ施設の用途・目的に応じて、削減率を定めるという方法もあるとは思うのですが、なかなか利用者、または利用団体、あるいは利用率によって、そういったパーセンテージを細かく出すというのは、非常に難しいかなと考えております。","voiceIndex":103,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"今、ＬＥＤという話もありました。なかなか難しい判断になるかとは思いますが、関係施設の状況をきっちり踏まえて、環境課がちゃんとまとめていくという流れをつくっていただきたいなと思うのです。将来的には、何年先にはこれぐらいのＣＯ２削減まで含めての計画的な目標ができるのではないか。ぜひ環境課が中心になって、安全に進めていただきたいなと思っていますので、ご検討よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"エアコンの設定温度についてなのですけれども、つい先頃、２８度の根拠はないとか、いや、あるんだという論争に一時なりました。品川区としては、推奨設定温度は何度になるのですか。","respondent":"小林環境課長","answer":"エアコンの設定温度ではなくて、室温を２８度に設定するように調整するです。２８度が推奨温度です。","voiceIndex":109,"id":"exchange-016"}]},{"id":"topic-04","title":"平成２９年度立会川・勝島運河環境美化運動","agenda":"平成２９年度立会川・勝島運河環境美化運動","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今年は７月５日となっておりますけれども、社会を明るくする運動と重なっているのです。どちらかというと、社会を明るくする運動のほうが、通常７月１日だったので、選挙の件があってということなのですけれども、この日程設定はどうだったのでしょうか。そうなると、いろいろな方々がかかわっていただいたのだけれども、どうしても手薄になってしまう。日程の調整は、どういう調整をされたのでしょうか。","respondent":"持田河川下水道課長","answer":"大井第一町会連合会会長へは、その辺は正直に事前に説明しておりまして、この日に、この時間でやりますということで、開催については、町会の皆様、また小学校のお子さんたちもいらしていますので、この日で決定という形になっている状態です。","voiceIndex":115,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"お互いが日にちを譲れないというのは、わからないではないのですが、都議選が７月２日にあるというのは、もう大分前に決まっていた話です。重ならないような調整は、別にここだけを責めるわけではないのですが、全体的な調整になってくるので、厳しい状況であるのはわかっていつつも、やはり今後、調整していかないものについては、調整を図っていただきたいと思っていますが、いかがでしょうか。","respondent":"持田河川下水道課長","answer":"学校は学校で、いろいろ学校の行事等がありまして、それ以降にずらすのも、実態としてはなかなか難しいということもあり、さらにもっと前にずらすなど、いろいろ案は考えたのです。","voiceIndex":117,"id":"exchange-018"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"概要の中でも、幾つか計画の改訂の話があったと思うのです。区の耐震改修促進計画も含む地域防災計画について、所管事務調査で取り上げてはどうかというのが１つです。それと、パリ協定等の動きもいろいろ報道されていますけれども、環境三計画の改定ということなので、こちらも所管事務調査に入れたらいかがかなという考えです。提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"今も委員から発言がありましたけれども、地域防災計画が今年度改訂ということですので、具体的なところをしっかりと調査を進めていきたいなというところです。特に避難所計画や女性の目線、子ども、弱者の方のための避難所対策のあり方など、ペット対策も含めて、そこもぜひしっかりとやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも、いつ来るともわからない首都直下型地震に備えるために、都市型の防災という、少し抽象的になりますけれども、そういったことを考えていただきたい。避難所の運営です。最近、他区でもかなり先進的な取組みが見られますので、避難所。無電柱化の推進ということも、１つの項目かもしれませんけれども、それも踏まえて、ぜひ調査をしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-021"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"先ほど来お話があるように、改訂についてはしっかり議論したほうがいいのではないかなという思いであります。どちらにしても、もう一点は、後日提出させていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-022"},{"speaker":"新妻委員","kind":"意見","question":"品川区には木密地域があるというところで、昨年起こりました糸魚川市の火災を、少し時間がたちましたので、行政側がどのような対応をしているのかというところを、しっかりと見て参考にしていきたいなという思いがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36838,"voices":132}},{"id":"h29-20170612-9","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"文教委員会","time":"午後１時００分～午後３時４１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"就学相談のところで、今まで６年生のときにアセスメントをやっていたというお話を聞いたのですが、それが、義務教育学校に入ると、１年生で入ったその後ずっとそういったことをやらないというお話を聞きまして、それが本当にそうなったのか、なぜ変わったのか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしましたら、義務教育学校で３分割しているところは、授業ではそういったことはないのですか。６年間たってきているわけですから、就学について様々な悩みなどあるのではないかと思うのですけれども、そういったところを巡回指導員の方がしっかりと把握できているということなのでしょうか。改めて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"アセスメントにつきましては、ＷＩＳＣだけではなくて、様々な形の実態把握をしています。例えば、東京都教育委員会が３月に全ての学校に読み書きアセスメントを配布したところですので、今後はそちらのほうの十分な活用等も含めた研修を今進めているところです。","voiceIndex":46,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"図書館のことについてもお伺いしたいのですけれども、今、３５０万冊ぐらい貸出があるということですけれども、やはり図書館の関係の方からお話を聞くと、１人当たり１０冊ぐらいになってくると、よく活用されているというところで、そこを超えていくべきだというお話をお聞きいたしました。そういった観点から区の考えていること、さらに促進していこうと思っていることがあれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"どの程度か私も具体的に見ていないから何とも言えないのですけれども、ビー玉が転がっていくということは、ある程度の傾斜があるということですから、そういうゆがんだところで長時間座り授業を受ける、そういう状況が日常茶飯であると、やはり子どもの健康状態にも影響が出てしまうのではないかと私は心配したのですけれども、そういう状況がある学校があるのだということはつかんでいるのか。","respondent":"篠田学校計画担当課長","answer":"学校の様々な状況ですけれども、そういったものは随時私どもの庶務課の担当などに入ってまいりますので、それは随時必要な対応をとっているところです。","voiceIndex":53,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"毎年１校ずつということですけれども、ごめんなさい。不勉強で教えていただきたいのですけれども、毎年１校ずつ、今年度４校というのは、前年度から経過していて、トータルで４校だと、そういう理解でいいかということが１つです。つかんでいなければ、さっき言ったように調査をするべきですし、３０年、４０年の古い校舎があることは、私も承知しております。","respondent":"品川庶務課長","answer":"床についてですが、子どもの健康状態に影響するような状況がある床はないと考えています。ただ、それが子どもに影響があるということが証明できるような情報があれば、それは即刻見に行って改修なり何なりやっていかなければいけないと考えます。","voiceIndex":55,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、そういう声があるということなので、即刻調べていただきたいと思います。個別に後で私も申し上げたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"クリスマスツリーが飾られなかったとか、サンタが来なくて子どもたちがかわいそうだったという声をお聞きしまして、今まではやっていたと思うのですけれども、やらなくなってしまったということとか、あとは、忘れ物をしたときに、貸してくれなくなったり、ひどいところでは、入り口で１歳児の子どもがうんちをしてしまったらしいのですけれども。","respondent":"福島子ども未来部長","answer":"今後も様々なご意見は出るかと思いますけれども、保護者の身になって誠実に対応していきたいというふうに考えております。ですから、個別の１つ１つについて、どれをこうしたということはここでは答えませんけれども、苦情につきましては全て適切に対処しています。","voiceIndex":68,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"特に、うんちをした子どもをそのまま帰されてしまったということで、子どものためにもよくないと思いますし、子どもが楽しみにしているクリスマス会をやらなかったということで、そういったところで適切にやっているというお話なのですけれども、今後そういったことがあったときも、やはり帰されてしまうということになるのでしょうか。そこは、しっかりと対応していただきたいのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"私も実は同じような話を聞いているのです。それで、個別具体的な話ではあるけれども、保育園という施設が親に対してそういう対応をしていいのかという問題ですから、保育内容そのものなのです。それで聞いているわけです。答弁をもう１回お願いしたいと思います。","respondent":"福島子ども未来部長","answer":"もちろん適切に対応してまいりますし、個別的に見ていきますと、やはり様々な事情があってその問題は起きています。","voiceIndex":75,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"今、様々な問題があってという説明だったのですけれども、それは様々な状況下で職員側がそういう対応をとらなければいけなくなってしまったという理由は、様々あるかもしれないけれども、しかし、あるかもしれないけれども、親が子どもを預けに来たときに、自宅に帰りなさいと、貸してくれるべきものを貸してもらえないで自宅に帰れということは、出勤するな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"１件だけ確認をいいですか。その方は何名ぐらいいて、例えば、制度がなくなっても大丈夫なのかということが１点と、これは記憶違いだったら済みません。区がこの手のことで債権放棄したことについて報告を受けたような記憶があるのですけれども、例えば事業廃止によって何かそういうトラブルになったりしないのかというところだけ確認させてください。","respondent":"廣田子ども家庭支援課長","answer":"授業料の貸付については、都の育英資金もかなり借りる方が減っておりまして、予定数を満たしていないので、都の育英資金を申し込めば、現状では所得の要件等があえば借りられるという状況ですので、補完して拾うというような類ではないので、であれば、近いものをやるよりも。","voiceIndex":78,"id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"確認","question":"大前提として歓迎できると思って伺っていますけれども、就学援助受給者の中から４０人という話ですけれども、それにしても多数の対象者がいる中での４０人だと思うので、どんなふうな選び方をされるのか、それが１つです。４点目には、会場ですけれども、品川図書館と品川区の教育総合支援センターということでよかったのですか。その確認です。","respondent":"熊谷指導課長","answer":"場所につきましては、先ほど委員ご指摘のとおり、教育総合支援センターと品川図書館の２か所を考えているところです。","voiceIndex":89,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方々に対する対応も同時に考えていってほしいというふうに思っているので、意欲のある子で作文等を確認して、さらに面接をして選ばれていくのですけれども、そのほかにも絶対に意欲がある子や親御さんもいらっしゃると思うので、そこへの対応、例えば、子ども未来部のほうで出されている高校に向けての就学支援といいますか。","respondent":"有馬学務課長、熊谷指導課長","answer":"確かに６年生のときには就学援助対象者で、その後、進路、東京学芸大学付属竹早中学校に行ったときにどうなるのかということですけれども、そのときの取り扱いをどうするのか、対象者は公立としていますけれども。２点目の交通費ですが、これにつきましては、現段階ではご自身で出費ということになるかと思います。これについても、今後、学芸大学と提携を進める中で考えていきたいと思います。","voiceIndex":91,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つお伺いしたいのですが、１つは、都教委のほうで昨年度の体罰の数字が出されたのですが、いつも文教委員会で後から詳しく説明いただくのですが、現時点で品川区でそういうことがあったのかどうかということが１つです。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"ただ、本来ですと、本日の文教委員会でお示しする予定でございましたけれども、東京都教育委員会の発表が先週の木曜日に急遽出たということでございまして、次回の文教委員会で詳細を説明させていただきたいと思います。児童連れ去り未遂という形での報告は受けておりませんが、何月何日のどの件でございましょうか。","voiceIndex":100,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"先週、小学校に入る前の子どもが、お母さんと一緒にいるときに、歩いてきた若い男の人に連れていかれそうになって、それでお母さんが「やめてください」と言ったので、その犯人は逃げていったということがあって、それで小学校のほうにその情報が行って、下校するときには気をつけるようにという一斉配信があったとお聞きしているので、その辺の事情がもしもわかったらということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-015"},{"speaker":"渡部委員","kind":"意見","question":"当然、品川区は独自の市民科がありますから、そういうものとあわせて少し通して様々な勉強をできたらなというような思いと、あと１つは、義務教育学校が立ち上がりまして１年間が経過して６校がすごく順調に、もっともその前には小中一貫教育をやっていますから順調に滑り出しているのですけれども、いわゆる義務教育学校というもので、これをどういうふうにこの先発展させていくかというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"ここまでが教育委員会です。その観点も、たくさん、本当に待機児童対策で先ほどもご説明いただいて、かなり定員を拡充をしていただきましたし、対策をとっていただいておりますけれども、１つ１つの園の保育の質というところを確保し、向上していただきたいという思いで、今、現状どういう形で調査をし、質の確保をしているのかというところを調査をしてみたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"子どもの貧困というところで、品川区も子どもの貧困に焦点を当てたシンポジウムを開催することにもなっているし、様々な意味での貧困家庭への支援を具体的な施策に上げてやるようになってきているので、そういう背景もあるので、やはり子どもの貧困をなくす、そういう角度からどういうふうに取り組んでいったらいいかということで、１つは、２年生と７年生でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"そういったことも含めて調査していただきたいというのが１つ。これも、今、国においてキッズウィークや教師の日の創設もして、休みを分散化するようなニュースも議論されているというお話も伺っておりますので、現在、その教職員の実態を把握して、今後も負担軽減について調査をしていただきたいということで、この２点をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"意見","question":"教育のほうでは、特別支援教室も置かれるなど、特別支援について体制が再構築というか、されていく部分があると思うので、その特別支援教育の新たな体制といいますか、整備されていく体制について、それに関連すると、就学前の部分での一部区でもやってきていますが、幼稚園、保育園におけるそういった教育という言い方が正しいかどうかわかりませんが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"ただ、これだけお話もありますから、正副委員長で検討いただいて、またどういう形であればその辺が調査研究がこちらで可能なのか、もしくは、例えば、行政視察とかもありますので、そういう場を活用してだとか、そういうところで入れていただけるのであれば、私どもとしてもそれは進めていきたいような課題であるとは思いますので、それは行財政改革特別委員会とのすり合わせが必要なのかと思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"相手先の申し込みも含めて、一定の時間がかかるのは承知しているのですけれども、調査内容が決まってから視察先を、私たちも一生懸命努力して探しますので、そういう扱いではどうでしょうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-022"},{"speaker":"渡部委員","kind":"意見","question":"今回はこの内容を精査していただいて、正副委員長のほうで、こういうところでこういうものが、日程とかそういうものもありますから、もしお調べいただけるのであればお調べいただいて、そちらのほうにみんなで勉強に、研修に、視察に行くというような形で、特段どこでどういうものというよりも、そのような形でお進めいただいて私どもは結構ですので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4914#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":50733,"voices":119}},{"id":"h29-20170612-5","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"総務委員会","time":"午後１時００分～午後３時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"中には文書で出されても、電話番号や連絡先が書いてあったりしたら、ぜひ直接意見も聞いてほしいといったご要望もありますので、その辺をぜひ検討していただきたいと思うのが２点目です。３点目が、１６ページのタウンミーティングのことなのですが、テーマの選定について、どこでどのように検討されて決められるのかお伺いします。その辺でテーマの選定の仕方について教えてください。お願いします。","respondent":"秋山財政課長、中元広報広聴課長","answer":"現時点で、中身や資料等の見出しも含めてやっておりますので、今年度、平成２９年度につきましては予算編成から入りますので、予算編成の前の時点で、もう予算書については一度お示ししておりますけれども、構成が決まり次第。所管のほうにも文書での回答を依頼しておりまして、その文書が来た時点で、またもう一度、区長まで決裁をとらせていただいて回答させていただいているところで、なるべく早くということで所管のほうにも。","voiceIndex":59,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこを１点お伺いしたい。大分昔、ちょっと質問したことがあるのですが、担当がどこにあるのかというのをお伺いしたいのと、あと職員のパワハラ、セクハラの問題は、職員のメンタルヘルスや健康面にも大いに影響を与えていくので、ぜひここのところは明らかにしていってほしいと思うのですが、どこに書かれているのか、どこで受けとめているのか、教えていただきたいのが２つ目です。","respondent":"島袋人権啓発課長、黒田人事課長","answer":"２点目、パワハラ、セクハラについての職員の研修等ですけれども、人権啓発課の男女共同参画のほうでは、ＤＶ研修の一連の流れの中で、毎年ではないのですけれども、何年かに１度ずつ、パワハラ、セクハラについて。職員の人数の割合ですが、正確な数字ではございませんが、正規の職員の人数が約２,５００人で、非正規の職員が約１,０００人といったような職員構成です。","voiceIndex":62,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり外国からたくさんの方がいらっしゃるところにおいて、もっと区民が理解を深めるという立場に立って、品川区は性的マイノリティーの問題をもっと真剣に取り上げてほしいという思いで質問したので、もう一回、そこをお答えいただきたいのと、あとパワハラ、セクハラのところは、第三者機関などは全然かかわりがない状況なのでしょうか。","respondent":"島袋人権啓発課長、黒田人事課長","answer":"区民の皆様への啓発というところですけれども、やはり広報の特集号がありますので、そちらのほうでしっかりと周知してまいりますのと、講演と映画の集いのパンフレットには。は職員の先ほどの人数ですが、正規換算で出した人数ではなくて、雇用している人数と捉えていただければというもので、今後の方向性ですが、非常勤職員につきましては、自治法が改正されまして。","voiceIndex":65,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後になります。ぜひ職員の人権問題もしっかりと捉えて、どうしたら改善していくのか、私たちはぜひ、第三者の関与も含みながら、前向きに改善していっていただきたいので、そこのところはよろしくお願いします。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"監査委員もそうですが、議員というのは、もともと各委員として予算・決算、認定、賛成、反対、さまざまやっておりますが、そういう方たちが監査に入って監査するというのは、これも公平・公正の観点からいかがなものかと思うのですが、これも第三者の人がやはり監査としてきちっと見るべきものだと思うのですが、その辺についてご見解をお聞かせください。","respondent":"米田危機管理室長、伊東税務課長、安井選挙管理委員会事務局長、江部監査委員事務局長","answer":"そういうことで、今回の件についても基本的に防災課のほうから広報等をしていますけれども。賦課されるに当たって寄附額分の控除があったりということで、それを、どれだけの影響が出るのかというところ、そこの部分だけを抜き出すというのは。選挙管理委員会の委員につきましては、基本的に構成がどうのこうのというよりも、議会のほうで選任するという形になってありますので。","voiceIndex":72,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問ではないのですが、先ほどご答弁で、危機管理室のミサイル対応のお話をしましたが、総務部の組織図の中に、危機管理担当部長（危機管理監）、曽田さんの名前がこういうふうに明示されているということは、やはり、今、主管は防災課というお話でしたが、私は、ここに載っている以上は、やはりきちんと危機管理室でもミサイルの問題も注視していくということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、正式な名称をきちんと覚えていなくて、昨年度までに、公共施設等総合計画でしたっけ、それが全部、大体の自治体でできたと思うのですけれども、その後、国のほうの進める方向として、ＰＰＰ／ＰＦＩ方式ですか、そういうものが進んでいくというようなことを聞いておりまして、４ページの（４）に、「区政に密接に関連する国および都の施策について、情報の収集。","respondent":"柏原企画調整課長","answer":"ですので、計画担当のほうで、ではそれをどういうふうに進めていくのかというよりは、その考え方に沿った形で、各主管部門のほうでそれを検討するという流れになっているというものです。","voiceIndex":79,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう計画というのは、その施設が関係する各部署でまず検討されてということで、ここでということではないという理解でよろしいですか。わかりました。それからもう一点。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-008"}]},{"id":"topic-02","title":"」を聴取いたします。「品川音頭リニューアルの周知","agenda":"」を聴取いたします。「品川音頭リニューアルの周知","exchanges":[{"speaker":"高橋（伸）委員","kind":"意見","question":"そういった公務員制度の内容、斬新な取り組みをしている自治体という、どこの自治体というのはまだ決めていないのですけれども、そういう公務員制度というのと、あと危機管理ということで、自治体のテロ対策について１年間通して調査していきたいと考えています。あわせてその復興状況なども調査していきたいと考えています。以上、３点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"今、自民党・子ども未来から出された防災対策については、ぜひ、あちこちで起こった災害を受けて、さらに品川区でどういう対策ができるのかという意味では、これはやれたら良いと思っていて、１点です。先ほど人権の問題で質問などさせていただいたのですが、ＬＧＢＴなど性的マイノリティーの問題をやはり前に進めていく意味では、議会が勉強していきたいと思っているのが１点です。３点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"確認","question":"それと、あとは東京都において、今、入札や契約制度の改革ということで、この６月から試行が始まっているのですが、予定価格の公表の廃止であるとか、一者入札の禁止であるとか、さまざまこれに関して、区内業者からも非常に不安の声が漏れているという中で、品川区はもちろん、今のやり方をとっているのですけれども、ここについて、現在の品川区の制度の状況を確認して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんのご意見、それぞれ必要だと思ってしまうのですけれども、さっきも意見を言いましたけれど、私はやっぱりずっと新公会計制度を推進したほうがいいと主張してきたのですけれども、さっきも言いましたが、ほかの先行して実施している自治体の話を聞くと、やっぱり、いわゆる企業会計そのままではなじまないところなどがあるわけで、それをうまく自治体の会計にして点検に役立てている例とか、だから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"それに、どんどん高齢化が進んで、高齢化対策、医療もそうなのですが、区に対するプレッシャーがいよいよ大きくなっている時代で、どういうふうにこれを克服していくのかというのは非常に興味があるところなので、できれば皆さんと一緒に議論しながら、また教えていただければありがたいということを、所管事務調査の一つに加えていただけるとありがたい。希望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-013"},{"speaker":"石田（し）委員","kind":"意見","question":"うちは、１つは、ダイバーシティ・マネジメントについて。それと、あとは情報の受発信は、シティプロモーションもそうですし、さまざまな情報については、これからもどんどん複雑化もしてくると思いますので、その点について調査したらいいのではないかと思っています。以上、３点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"以前にも我が会派から意見を出させていただいたのですけれども、品川区に大井競馬場があるというところがあるかもしれませんけれども、毎年、総務委員会が視察をする必要があるのかどうか。もし内容的なものだったら、申しわけないのですけれどご足労いただいてお話を伺うとか。何か、車を用立てて全員で行く必要は、どうなのかと考えています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"シティプロモーションで、北九州をはじめ、さまざま見させていただきました。ですが、それぞれの地域、人口が流出している、産業が低迷している、それぞれ大変苦労しているというお話を聞いております。朝の通勤のときも、駅の中に入る改札口で相当、人が並んでいる。何も２泊３日に限らずとも、１泊でもいいのでしょうし、皆さんどうでしょうかという提案をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"意見","question":"だから、２泊３日でそろって行って帰ってくるという考え方は捨てていただいて、もうちょっと違った方法でも効率よくできるのではないかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"提案","question":"同じ兵庫県の神戸にも、これは非常に難しいのですけれど、シティプロモーションの観点で、私はずっとフィルムコミッションについて伺っていたのですが、今回、観光のほうに所管が移ったのですが、シティプロモーションの観点で言うならば、神戸フィルムオフィスというところは日本で一番最初にフィルムコミッションに登録されたところで、そこの代表をされていた方が、今、この前かわって。","respondent":"伊藤委員長","answer":"ただいまいただいたご意見を参考に、これまで行ってきた行政視察の調査項目や視察先、それから今年度の所管事務調査等々、さまざまな観点から検討させていただきまして、次回、７月の委員会で、正副委員長でまとめさせていただいた日程。","voiceIndex":110,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":42884,"voices":111}}]);
